const e="hsk",t=6,n=[{num:1,title:"孩子给我们的启示",points:[{id:"HSK6.01.1",name:"动词“巴不得”",pinyin:"bābude",type:"动词/固定用法",explainEn:"Use 巴不得 to mean “wish very strongly that something would happen”.",structure:"巴不得 + 小句",examples:[{zh:"我巴不得马上放假。",en:"I wish the holiday could start right now.",py:"Wǒ bābude mǎshàng fàngjià."},{zh:"他巴不得孩子早点儿回家。",en:"He really wishes his child would come home earlier.",py:"Tā bābude háizi zǎo diǎnr huíjiā."},{zh:"有人帮我，我巴不得呢。",en:"If someone helps me, I would be delighted.",py:"Yǒu rén bāng wǒ, wǒ bābude ne."}],exercises:[{kind:"choice",q:"有人愿意替我值夜班，我___呢，怎么会拒绝？",instr:"辨析",instrEn:"Pick the right one",body:"有人愿意替我值夜班，我___呢，怎么会拒绝？",options:["恨不得","巴不得","舍不得","来不及"],answer:1,explain:"“巴不得”可以单独带“呢”作谓语，表示非常盼望；“恨不得”后面必须带动词短语，不能单说。",explainEn:"巴不得 can stand alone before 呢 (“I'd love that”); 恨不得 must be followed by a verb phrase."},{kind:"choice",q:"听说今天可以提前下班，同事们巴不得___。",instr:"完成",instrEn:"Complete the sentence",body:"听说今天可以提前下班，同事们巴不得___。",options:["留下来继续加班","把报告再改一遍","明天早点儿来上班","马上收拾东西走人"],answer:3,explain:"“巴不得”表示迫切盼望的好事，提前下班时大家盼的是马上走；其他选项都不是此时盼望的事。",explainEn:"巴不得 means eagerly wishing for something you want; here that is leaving at once, not staying to work."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我很巴不得早点儿毕业。","他巴不得这场雨快点儿停。","要是能去海边，孩子们巴不得呢。","她巴不得天天都能见到妈妈。"],answer:0,explain:"“巴不得”本身已表示程度很深，前面不能加“很”，应改为“我巴不得早点儿毕业”。",explainEn:"巴不得 already expresses strong desire and cannot take 很; say 我巴不得早点儿毕业."},{q:"翻译：The kids can't wait for the summer holiday to begin.",a:"孩子们巴不得暑假早点儿开始。",instr:"翻译",instrEn:"Translate",body:"The kids can't wait for the summer holiday to begin."}],note:"多用于口语，表示迫切希望；愿望通常是说话人认为很好的事。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bābude + Clause = wish very much that …",noteEn:"Mostly spoken; expresses an eager wish, usually for something the speaker sees as good.",typeEn:"Verb / Set usage"},{id:"HSK6.01.2",name:"“别提多……了”表示程度很深",pinyin:"biétí duō ... le",type:"程度结构",explainEn:"Use 别提多…了 to mean “extremely / you can't imagine how…”.",structure:"别提 + 多 + 形容词/心理动词 + 了",examples:[{zh:"听到这个消息，我别提多高兴了。",en:"I was extremely happy to hear the news.",py:"Tīngdào zhège xiāoxi, wǒ biétí duō gāoxìng le."},{zh:"那天山上别提多冷了。",en:"It was unbelievably cold on the mountain that day.",py:"Nà tiān shān shang biétí duō lěng le."},{zh:"孩子回来以后，她别提多放心了。",en:"She was extremely relieved after the child came back.",py:"Háizi huílai yǐhòu, tā biétí duō fàngxīn le."}],exercises:[{kind:"choice",q:"第一次站上领奖台，他心里别提___激动了。",instr:"辨析",instrEn:"Pick the right one",body:"第一次站上领奖台，他心里别提___激动了。",options:["很","太","多","非常"],answer:2,explain:"固定格式是“别提多+形容词+了”，只能用“多”；“很、太、非常”不能进入这个格式。",explainEn:"The fixed pattern is 别提多 + adj + 了; only 多 fits, not 很/太/非常."},{kind:"choice",q:"我一个人在国外生活，刚去那几个月别提多孤单了，___。",instr:"完成",instrEn:"Complete the sentence",body:"我一个人在国外生活，刚去那几个月别提多孤单了，___。",options:["天天都盼着早点儿回国","但我一点儿也不觉得寂寞","所以那几个月过得特别开心","所以我一次也没想过家"],answer:0,explain:"“别提多……了”表示程度极深，意思是非常孤单，所以后面接“天天盼着回国”；“不觉得寂寞、过得特别开心、没想过家”都把“别提”误解成了否定，和“非常孤单”正相反。",explainEn:"别提多…了 means “extremely”, i.e. terribly lonely, so it is followed by longing to go home; the other options misread 别提 as a negation (“not lonely”)."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["那天傍晚的晚霞别提多美了。","收到录取通知书，她别提多很高兴了。","一想到要考试，我心里别提多紧张了。","比赛赢了，队员们别提多得意了。"],answer:1,explain:"“别提多”后面直接跟形容词，不能再加“很”，应改为“她别提多高兴了”。",explainEn:"别提多 is followed directly by the adjective; remove 很: 她别提多高兴了."},{q:"翻译：It was unbelievably cold that day.",a:"那天别提多冷了。",instr:"翻译",instrEn:"Translate",body:"It was unbelievably cold that day."}],note:"带有夸张和感情色彩，常用于口语。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biétí + duō + Adj / mental verb + le = you can't imagine how … / extremely …",noteEn:"Exaggerated and emotional; common in speech.",typeEn:"Degree structure"},{id:"HSK6.01.3",name:"具有语体差别的同义词",pinyin:"jùyǒu yǔtǐ chābié de tóngyìcí",type:"词汇/语体",explainEn:"Words with similar meanings can differ in style: some are formal, others are conversational.",structure:"书面词 ↔ 口语词：将↔把；即↔就是；令↔让等",examples:[{zh:"请将材料交给老师。",en:"Please give the material to the teacher.",py:"Qǐng jiāng cáiliào jiāo gěi lǎoshī."},{zh:"你把材料给老师吧。",en:"Give the material to the teacher.",py:"Nǐ bǎ cáiliào gěi lǎoshī ba."},{zh:"通知写道，会议将于九点开始。",en:"The notice says the meeting will begin at nine.",py:"Tōngzhī xiědào, huìyì jiāng yú jiǔ diǎn kāishǐ."}],exercises:[{kind:"choice",q:"啊？你说的那个新同事___我表哥啊！",instr:"辨析",instrEn:"Pick the right one",body:"啊？你说的那个新同事___我表哥啊！",options:["即为","乃是","就是","实为"],answer:2,explain:"带“啊”的日常聊天要用口语词“就是”；“即为、乃是、实为”都是书面语，放在随口说的话里很不自然。",explainEn:"In casual speech with 啊, use the spoken 就是; 即为/乃是/实为 are written-style and sound odd in chat."},{kind:"choice",q:"【通知】本次会议将于明日上午九点召开，___。",instr:"完成",instrEn:"Complete the sentence",body:"【通知】本次会议将于明日上午九点召开，___。",options:["大家可千万别迟到了啊","到时候都早点儿来哈","请各位与会人员准时出席","谁也别忘了这事儿呗"],answer:2,explain:"正式通知用了书面语“将于”，后文也要用书面语“请各位……准时出席”；其他几句是聊天口吻，与通知语体不合。",explainEn:"A formal notice with 将于 needs formal wording like 请各位…准时出席; the others are chatty and clash with the register."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他的表现令我们非常感动。","会议即将开始，请大家关闭手机。","小王，你将那本书给我递一下吧。","请将个人物品放在指定位置。"],answer:2,explain:"朋友之间随口请求属于口语，不宜用书面语“将”，应改为“你把那本书给我递一下吧”。",explainEn:"A casual request to a friend should use spoken 把, not formal 将: 你把那本书给我递一下吧."}],note:"高级学习要注意词义相近但语体不同；正式写作与口语应选择合适表达。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Formal ↔ spoken: jiāng ↔ bǎ; jí ↔ jiùshì; lìng ↔ ràng, etc.",noteEn:"At higher levels, watch for near-synonyms that differ in register; pick the formal or spoken one to suit the context.",typeEn:"Vocabulary / Register"}]},{num:2,title:"父母之爱",points:[{id:"HSK6.02.1",name:"动词“恨不得”",pinyin:"hènbude",type:"动词/固定用法",explainEn:"Use 恨不得 to mean “wish very strongly / cannot wait to…”.",structure:"恨不得 + 立刻/马上 + 动词",examples:[{zh:"我恨不得现在就回家。",en:"I wish I could go home right now.",py:"Wǒ hènbude xiànzài jiù huíjiā."},{zh:"他急得恨不得马上知道结果。",en:"He was so anxious that he wished he knew the result immediately.",py:"Tā jí de hènbude mǎshàng zhīdào jiéguǒ."},{zh:"天气太热，我恨不得一天都待在空调房里。",en:"It is so hot that I wish I could stay in an air-conditioned room all day.",py:"Tiānqì tài rè, wǒ hènbude yì tiān dōu dāi zài kōngtiáo fáng li."}],exercises:[{kind:"choice",q:"他气得___把那封信撕得粉碎，可最后还是忍住了。",instr:"辨析",instrEn:"Pick the right one",body:"他气得___把那封信撕得粉碎，可最后还是忍住了。",options:["不由得","忍不住","恨不得","不得不"],answer:2,explain:"“恨不得”表示非常想做却没有真做，所以后面能说“最后还是忍住了”；“不由得、忍不住”表示控制不住真的做了，“不得不”表示被迫做了，都和“忍住了”矛盾。",explainEn:'恨不得 = wish badly to do something but not actually do it, so it fits "but held back in the end"; 不由得/忍不住 mean you actually did it, 不得不 means you were forced to.'},{kind:"choice",q:"听说母亲住院了，他恨不得___。",instr:"完成",instrEn:"Complete the sentence",body:"听说母亲住院了，他恨不得___。",options:["过几天再回去看看","等放了假再说","立刻飞到母亲身边","慢慢地考虑一下"],answer:2,explain:"“恨不得”表示非常急切，常和“立刻、马上”连用；其他选项都表示不着急，与它的意思相反。",explainEn:"恨不得 expresses urgent longing, usually with 立刻/马上; the other options show no hurry."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["热得我恨不得跳进河里。","他饿得恨不得一口吃下整个蛋糕。","听完他的话，我恨不得马上跟他吵一架。","她想家想得马上恨不得飞回国。"],answer:3,explain:"“马上、立刻”要放在“恨不得”后面，应改为“她想家想得恨不得马上飞回国”。",explainEn:"马上 must come after 恨不得: 她想家想得恨不得马上飞回国."},{q:"翻译：She wished she could fly to Shanghai at once.",a:"她恨不得马上飞到上海去。",instr:"翻译",instrEn:"Translate",body:"She wished she could fly to Shanghai at once."}],note:"和“巴不得”接近；“恨不得”常带急切、焦急或强烈感情。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"hènbude + lìkè/mǎshàng + Verb = can't wait to … right now",noteEn:"Close to 巴不得; 恨不得 often carries urgency, anxiety or strong feeling.",typeEn:"Verb / Set usage"},{id:"HSK6.02.2",name:"副词“顿时”",pinyin:"dùnshí",type:"副词",explainEn:"Use 顿时 to mean “suddenly / immediately at that moment”.",structure:"情况 + 顿时 + 变化",examples:[{zh:"听到好消息，大家顿时高兴起来。",en:"Everyone became happy at once after hearing the good news.",py:"Tīngdào hǎo xiāoxi, dàjiā dùnshí gāoxìng qilai."},{zh:"门一打开，房间里顿时亮了。",en:"As soon as the door opened, the room suddenly became bright.",py:"Mén yì dǎkāi, fángjiān li dùnshí liàng le."},{zh:"他的话让我顿时明白了。",en:"His words made me understand immediately.",py:"Tā de huà ràng wǒ dùnshí míngbai le."}],exercises:[{kind:"choice",q:"听到这个坏消息，她的脸色___变得苍白。",instr:"辨析",instrEn:"Pick the right one",body:"听到这个坏消息，她的脸色___变得苍白。",options:["随时","顿时","及时","按时"],answer:1,explain:"“顿时”表示某事发生后状态立刻变化；“随时”指任何时候，“及时、按时”指不晚、按规定时间，都不合句意。",explainEn:"顿时 means a state changed at once after something happened; 随时/及时/按时 mean any time / in time / on time."},{kind:"choice",q:"他的话音刚落，会议室里顿时___。",instr:"完成",instrEn:"Complete the sentence",body:"他的话音刚落，会议室里顿时___。",options:["安静了下来","会安静下来","应该安静下来","要安静下来"],answer:0,explain:"“顿时”只描述已经发生的变化，不能和“会、应该、要”等表示将来或要求的词连用。",explainEn:"顿时 describes a change that has already happened, so it can't go with 会/应该/要."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["阳光一照进来，屋子里顿时暖和了许多。","听了这番话，他心里顿时轻松了。","你到了酒店以后，请顿时给我打个电话。","哨声一响，球场上顿时一片欢呼。"],answer:2,explain:"“顿时”不能用于请求或将来的动作，这里应改为“请马上给我打个电话”。",explainEn:"顿时 can't be used in requests or for future actions; say 请马上给我打个电话."},{q:"翻译：The room suddenly became bright.",a:"房间里顿时亮了。",instr:"翻译",instrEn:"Translate",body:"The room suddenly became bright."}],note:"多说明某件事发生后，状态马上发生变化。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Situation + dùnshí + change = … at once / suddenly",noteEn:"Usually says that right after something happens, the state changes at once.",typeEn:"Adverb"},{id:"HSK6.02.3",name:"副词“不由得”",pinyin:"bùyóude",type:"副词",explainEn:"Use 不由得 to mean “cannot help doing something”.",structure:"不由得 + 动词",examples:[{zh:"听到这个故事，我不由得笑了。",en:"I could not help laughing when I heard the story.",py:"Tīngdào zhège gùshi, wǒ bùyóude xiào le."},{zh:"看到老照片，她不由得想起了小时候。",en:"Seeing the old photos, she could not help remembering her childhood.",py:"Kàndào lǎo zhàopiàn, tā bùyóude xiǎngqǐle xiǎoshíhou."},{zh:"他说得太感人，大家不由得流下了眼泪。",en:"He spoke so movingly that everyone could not help crying.",py:"Tā shuō de tài gǎnrén, dàjiā bùyóude liúxiàle yǎnlèi."}],exercises:[{kind:"choice",q:"看到孩子认真写字的样子，妈妈___笑了起来。",instr:"辨析",instrEn:"Pick the right one",body:"看到孩子认真写字的样子，妈妈___笑了起来。",options:["不得不","不见得","不至于","不由得"],answer:3,explain:"“不由得”表示控制不住、自然地做出某个动作；“不得不”是被迫，“不见得”是不一定，“不至于”是不会到某种程度。",explainEn:"不由得 means doing something involuntarily; 不得不 = forced to, 不见得 = not necessarily, 不至于 = not go so far as."},{kind:"choice",q:"看到那张熟悉的老照片，他不由得___。",instr:"完成",instrEn:"Complete the sentence",body:"看到那张熟悉的老照片，他不由得___。",options:["想起了大学时的朋友","决定明天去整理房间","计划下个月去旅行","打算把照片卖掉"],answer:0,explain:"“不由得”后面是自然而然、不受控制的反应；“决定、计划、打算”都是有意识的安排。",explainEn:"不由得 introduces an involuntary reaction; 决定/计划/打算 are deliberate plans."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["听到熟悉的歌声，她不由得跟着唱了起来。","看到这么美的景色，大家不由得停下了脚步。","为了通过考试，他不由得每天学习到深夜。","想到明天的面试，我不由得紧张起来。"],answer:2,explain:"为了考试而努力学习是有意的行为，不能用“不由得”，应改为“他每天都坚持学习到深夜”。",explainEn:"Studying late for an exam is deliberate, so 不由得 doesn't fit; say 他每天都坚持学习到深夜."},{q:"翻译：She could not help remembering her childhood.",a:"她不由得想起了小时候。",instr:"翻译",instrEn:"Translate",body:"She could not help remembering her childhood."}],note:"表示动作自然发生，并非有意去做。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùyóude + Verb = can't help doing …",noteEn:"The action happens naturally, not on purpose.",typeEn:"Adverb"}]},{num:3,title:"一盒月饼",points:[{id:"HSK6.03.1",name:"量词“番”",pinyin:"fān",type:"动量词",explainEn:"Use 番 after an action or noun to mean “a round / an occasion of effort, discussion, thought, etc.”.",structure:"一番 + 名词/动词性成分",examples:[{zh:"经过一番讨论，我们终于决定了。",en:"After a round of discussion, we finally decided.",py:"Jīngguò yì fān tǎolùn, wǒmen zhōngyú juédìng le."},{zh:"他为这件事费了一番心思。",en:"He put a lot of thought into this matter.",py:"Tā wèi zhè jiàn shì fèile yì fān xīnsi."},{zh:"老师对我进行了一番鼓励。",en:"The teacher gave me some encouragement.",py:"Lǎoshī duì wǒ jìnxíngle yì fān gǔlì."}],exercises:[{kind:"choice",q:"为了修好这台旧电脑，他费了___功夫。",instr:"辨析",instrEn:"Pick the right one",body:"为了修好这台旧电脑，他费了___功夫。",options:["一番","一次","一顿","一遍"],answer:0,explain:"“费了一番功夫”是固定搭配，“番”用于花费心力的过程；“一次、一顿、一遍”都不能修饰“功夫”。",explainEn:"费了一番功夫 is a set collocation; 番 counts effortful processes, while 次/顿/遍 can't go with 功夫."},{kind:"choice",q:"客人来之前，妈妈把客厅仔仔细细地___了一番。",instr:"完成",instrEn:"Complete the sentence",body:"客人来之前，妈妈把客厅仔仔细细地___了一番。",options:["打开","关上","看见","打扫"],answer:3,explain:"“动词+了一番”要求动词表示需要花时间、花力气的过程，如“打扫”；“打开、关上、看见”是一下子完成的动作。",explainEn:"V + 了一番 needs a verb of extended effort like 打扫; 打开/关上/看见 are instant actions."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她精心打扮了一番才出门。","经过一番努力，他终于考上了研究生。","生日那天，他送给我一番礼物。","我们对这个方案进行了一番研究。"],answer:2,explain:"“番”不用于具体的物品，应改为“他送给我一份礼物”。",explainEn:"番 doesn't count concrete objects; say 一份礼物."},{q:"翻译：After some preparation, the party started on time.",a:"经过一番准备，晚会按时开始了。",instr:"翻译",instrEn:"Translate",body:"After some preparation, the party started on time."}],note:"常与“讨论、努力、考虑、心思、解释”等搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yì fān + Noun / verbal phrase = a round of … (effort, talk, thought)",noteEn:"Often paired with 讨论, 努力, 考虑, 心思, 解释, etc.",typeEn:"Verbal measure word"},{id:"HSK6.03.2",name:"副词“过于”",pinyin:"guòyú",type:"副词",explainEn:"Use 过于 before an adjective or verb to mean “too / excessively”.",structure:"过于 + 形容词/心理动词",examples:[{zh:"你不必过于担心。",en:"You do not need to worry too much.",py:"Nǐ búbì guòyú dānxīn."},{zh:"这个要求过于严格。",en:"This requirement is too strict.",py:"Zhège yāoqiú guòyú yángé."},{zh:"过于依赖手机不是好事。",en:"Relying too much on a phone is not a good thing.",py:"Guòyú yīlài shǒujī bú shì hǎoshì."}],exercises:[{kind:"choice",q:"他平时说话___直接，常常不小心得罪人。",instr:"辨析",instrEn:"Pick the right one",body:"他平时说话___直接，常常不小心得罪人。",options:["超过","过多","至于","过于"],answer:3,explain:"“过于”是副词，修饰形容词“直接”，表示程度太高；“超过”是动词，后面要带比较对象，“过多”指数量多，“至于”用来转换话题。",explainEn:'过于 is an adverb meaning "overly" before an adjective; 超过 is a verb needing an object, 过多 is about quantity, 至于 changes the topic.'},{kind:"choice",q:"这篇文章写得过于简单，___。",instr:"完成",instrEn:"Complete the sentence",body:"这篇文章写得过于简单，___。",options:["所以大家都很喜欢读它","因此特别适合做范文","很多重要问题都没讲清楚","读起来非常有深度"],answer:2,explain:"“过于”表示超过了合适的程度，后面应该是不好的结果；其他选项都是好的评价，与“过于”的意思不合。",explainEn:"过于 means “excessively”, so the result should be negative; the other options praise the article."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你不必过于担心，事情没那么糟。","这个计划过于理想化，很难实现。","他对自己要求过于严格，常常很累。","他这样对待父母，实在太过于了。"],answer:3,explain:"“过于”是副词，后面必须带形容词，不能单独作谓语，应改为“实在太过分了”。",explainEn:"过于 is an adverb and needs an adjective after it; say 实在太过分了."},{q:"翻译：You don't need to be overly modest.",a:"你不必过于谦虚。",instr:"翻译",instrEn:"Translate",body:"You don't need to be overly modest."}],note:"比“太”更正式，常用于书面语。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"guòyú + Adj / mental verb = too … / excessively …",noteEn:"More formal than 太; common in writing.",typeEn:"Adverb"},{id:"HSK6.03.3",name:"“……着呢”表示程度/状态",pinyin:"... zhe ne",type:"助词结构",explainEn:"Use …着呢 to strongly emphasize a state: “very / far from…”.",structure:"形容词/状态 + 着呢",examples:[{zh:"时间还早着呢。",en:"It is still very early.",py:"Shíjiān hái zǎo zhene."},{zh:"这件事复杂着呢。",en:"This matter is really complicated.",py:"Zhè jiàn shì fùzá zhene."},{zh:"他身体好着呢，你别担心。",en:"He is perfectly healthy, so do not worry.",py:"Tā shēntǐ hǎo zhene, nǐ bié dānxīn."}],exercises:[{kind:"choice",q:"你别小看这孩子，他聪明___，什么都一学就会。",instr:"辨析",instrEn:"Pick the right one",body:"你别小看这孩子，他聪明___，什么都一学就会。",options:["呢","着呢","着","的呢"],answer:1,explain:"形容词后加“着呢”表示程度很高，带夸张语气；单用“呢、着”或“的呢”都不能这样表示程度。",explainEn:"Adj + 着呢 means “really very”; 呢, 着 or 的呢 alone can't express this degree."},{kind:"choice",q:"你别看他个子小，力气___着呢，一个人就能搬动这张桌子。",instr:"完成",instrEn:"Complete the sentence",body:"你别看他个子小，力气___着呢，一个人就能搬动这张桌子。",options:["很大","大","有点儿大","非常大"],answer:1,explain:"“着呢”本身已表示程度高，前面只能用单个形容词，不能再加“很、非常、有点儿”。",explainEn:'着呢 already means "very", so use the bare adjective; no 很/非常/有点儿 before it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["从这儿到机场远着呢吗？","那家店的生意好着呢。","作业多着呢，今晚别想出去玩了。","他脾气大着呢，你说话小心点儿。"],answer:0,explain:"“着呢”只用在陈述句里强调程度，不能用于疑问句，应改为“从这儿到机场远不远？”。",explainEn:"着呢 is only used in statements for emphasis, not in questions; ask 从这儿到机场远不远？"},{q:"翻译：Don't worry, there is still plenty of food.",a:"别担心，吃的多着呢。",instr:"翻译",instrEn:"Translate",body:"Don't worry, there is still plenty of food."}],note:"口语色彩较强，用来加强状态或程度。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Adj / state + zhene = very … indeed",noteEn:"Strongly colloquial; intensifies a state or degree.",typeEn:"Particle structure"}]},{num:4,title:"完美的胜利",points:[{id:"HSK6.04.1",name:"副词“乘机”",pinyin:"chéngjī",type:"副词",explainEn:"Use 乘机 to mean “take the opportunity to…”.",structure:"乘机 + 动词",examples:[{zh:"我去北京出差，乘机看了一个老朋友。",en:"I went to Beijing on business and took the opportunity to visit an old friend.",py:"Wǒ qù Běijīng chūchāi, chéngjī kànle yí ge lǎo péngyou."},{zh:"大家休息时，他乘机问了老师几个问题。",en:"During the break, he took the opportunity to ask the teacher some questions.",py:"Dàjiā xiūxi shí, tā chéngjī wènle lǎoshī jǐ ge wèntí."},{zh:"趁会议结束，我乘机介绍了自己的想法。",en:"When the meeting ended, I took the chance to introduce my idea.",py:"Chèn huìyì jiéshù, wǒ chéngjī jièshàole zìjǐ de xiǎngfǎ."}],exercises:[{kind:"choice",q:"老板一出差，几个员工就___偷起懒来。",instr:"辨析",instrEn:"Pick the right one",body:"老板一出差，几个员工就___偷起懒来。",options:["随机","乘坐","时机","乘机"],answer:3,explain:"“乘机”是副词，表示利用某个机会做事；“随机”是随意、不定，“乘坐”是坐交通工具，“时机”是名词。",explainEn:"乘机 is an adverb meaning “seize the chance to”; 随机 = random, 乘坐 = ride, 时机 is a noun."},{kind:"choice",q:"敌人一时放松了警惕，我们乘机___。",instr:"完成",instrEn:"Complete the sentence",body:"敌人一时放松了警惕，我们乘机___。",options:["失去了联系","迷失了方向","冲出了包围","受到了攻击"],answer:2,explain:"“乘机”后面是主动利用机会去做的事；“失去联系、迷失方向、受到攻击”都不是主动做的，也不是利用机会。",explainEn:"乘机 is followed by a deliberate action taking advantage of a chance; the others are things that just happen to you."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["那天下大雨，他乘机感冒了。","趁父母不在家，弟弟乘机玩了一下午游戏。","主任心情好，我乘机提出了请假的要求。","对方守门员滑倒了，前锋乘机把球踢进了球门。"],answer:0,explain:"“乘机”后面要接有意利用机会的动作，“感冒”不是主动做的事，应改为“他不小心感冒了”。",explainEn:"乘机 needs a deliberate action; catching a cold isn't one. Say 他不小心感冒了."},{q:"翻译：He took the opportunity to ask the teacher.",a:"他乘机问了老师几个问题。",instr:"翻译",instrEn:"Translate",body:"He took the opportunity to ask the teacher."}],note:"与“趁机”接近，“乘机”较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"chéngjī + Verb = take the chance to …",noteEn:"Close to 趁机; 乘机 is more formal.",typeEn:"Adverb"},{id:"HSK6.04.2",name:"连词“不料”",pinyin:"bùliào",type:"连词/副词",explainEn:"Use 不料 to introduce an unexpected result: “unexpectedly / to one's surprise”.",structure:"原来的计划/预期，不料 + 意外结果",examples:[{zh:"我以为他不会来，不料他第一个到了。",en:"I thought he would not come, but unexpectedly he arrived first.",py:"Wǒ yǐwéi tā bú huì lái, búliào tā dì-yī ge dào le."},{zh:"天气预报说晴天，不料下午下起了雨。",en:"The forecast said it would be sunny, but it unexpectedly rained in the afternoon.",py:"Tiānqì yùbào shuō qíngtiān, búliào xiàwǔ xiàqǐle yǔ."},{zh:"我们准备得很充分，不料还是出了问题。",en:"We prepared well, yet an unexpected problem still occurred.",py:"Wǒmen zhǔnbèi de hěn chōngfèn, búliào háishi chūle wèntí."}],exercises:[{kind:"choice",q:"本以为这场比赛稳赢，___对手在最后一分钟追平了比分。",instr:"辨析",instrEn:"Pick the right one",body:"本以为这场比赛稳赢，___对手在最后一分钟追平了比分。",options:["果然","难怪","于是","不料"],answer:3,explain:"前面说“本以为”，后面是意外结果，要用“不料”；“果然”表示和预料一样，“难怪”表示明白原因，“于是”表示顺承。",explainEn:"After 本以为, an unexpected result needs 不料; 果然 means “as expected”, 难怪 “no wonder”, 于是 “so then”."},{kind:"choice",q:"我们本想周末去爬山，不料___。",instr:"完成",instrEn:"Complete the sentence",body:"我们本想周末去爬山，不料___。",options:["那天天气特别好","周六一早就下起了大雨","大家都按时到了","一路上都非常顺利"],answer:1,explain:"“不料”引出和原来的计划或预期相反的意外情况；其他选项都顺着计划发展，没有意外。",explainEn:"不料 introduces something that goes against the plan; the other options mean everything went as planned."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他本想给妻子一个惊喜，不料妻子早就知道了。","天气预报说今天有雨，不料果然下雨了。","我以为这道题很简单，不料做了半天也没做出来。","大家都觉得他会赢，不料他第一轮就输了。"],answer:1,explain:"“不料”表示出乎意料，不能和表示“和预料一样”的“果然”连用，应改为“天气预报说今天有雨，果然下雨了”。",explainEn:"不料 means “unexpectedly” and clashes with 果然 (“as expected”); drop 不料."},{q:"翻译：Unexpectedly, it rained in the afternoon.",a:"不料下午下起了雨。",instr:"翻译",instrEn:"Translate",body:"Unexpectedly, it rained in the afternoon."}],note:"常用于叙述中，强调结果和预想相反。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Original plan / expectation, búliào + unexpected result = but, unexpectedly, …",noteEn:"Common in narration; stresses that the result is the opposite of what was expected.",typeEn:"Conjunction / Adverb"},{id:"HSK6.04.3",name:"副词“未免”",pinyin:"wèimiǎn",type:"副词",explainEn:"Use 未免 to mean “rather too / a bit too…”, often showing mild criticism.",structure:"未免 + 太/有点儿 + 形容词/动词",examples:[{zh:"你这样说未免太直接了。",en:"What you said is a bit too direct.",py:"Nǐ zhèyàng shuō wèimiǎn tài zhíjiē le."},{zh:"因为一点小事就放弃，未免太可惜了。",en:"Giving up over such a small matter is really a pity.",py:"Yīnwèi yìdiǎn xiǎoshì jiù fàngqì, wèimiǎn tài kěxī le."},{zh:"这个价格未免有点儿高。",en:"This price is rather high.",py:"Zhège jiàgé wèimiǎn yǒudiǎnr gāo."}],exercises:[{kind:"choice",q:"为了一点儿小事就跟朋友吵架，你___太小气了。",instr:"辨析",instrEn:"Pick the right one",body:"为了一点儿小事就跟朋友吵架，你___太小气了。",options:["未免","难免","不免","以免"],answer:0,explain:"“未免太……了”用来委婉批评某事过头；“难免、不免”表示自然会出现某种结果，“以免”表示目的。",explainEn:"未免太…了 gently criticizes something as excessive; 难免/不免 mean something is hard to avoid, 以免 means “so as not to”."},{kind:"choice",q:"他才工作一年就想当经理，这未免___。",instr:"完成",instrEn:"Complete the sentence",body:"他才工作一年就想当经理，这未免___。",options:["很正常啊","合情合理","太心急了","值得鼓励"],answer:2,explain:"“未免”表示说话人认为有点儿过头，后面是委婉的批评；其他选项都是肯定的评价。",explainEn:"未免 introduces a mild criticism of going too far; the other options are approving."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你的中文说得未免太流利了，真让人羡慕。","这么晚才通知大家，未免有点儿不负责任。","一次失败就放弃，未免太可惜了。","让一个孩子做这么多作业，未免太多了吧。"],answer:0,explain:"“未免”用于委婉批评，不能用来夸奖，应改为“你的中文说得真流利”。",explainEn:"未免 is for mild criticism, not praise; say 你的中文说得真流利."},{q:"翻译：That is a bit too direct.",a:"这未免太直接了。",instr:"翻译",instrEn:"Translate",body:"That is a bit too direct."}],note:"常用于评价某事“有点儿过头”，语气比直接批评更委婉。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèimiǎn + tài/yǒudiǎnr + Adj/Verb = rather too … / a bit too …",noteEn:'Often used to judge something as "a bit too much" — gentler than open criticism.',typeEn:"Adverb"}]},{num:5,title:"学一门外语需要理由吗",points:[{id:"HSK6.05.1",name:"助词“而已”",pinyin:"éryǐ",type:"助词",explainEn:"Use 而已 after a statement to mean “only / nothing more”.",structure:"小句 + 而已",examples:[{zh:"我只是随便问问而已。",en:"I was only asking casually.",py:"Wǒ zhǐshì suíbiàn wènwen éryǐ."},{zh:"这只是一个建议而已。",en:"This is only a suggestion.",py:"Zhè zhǐshì yí ge jiànyì éryǐ."},{zh:"他开个玩笑而已，你别生气。",en:"He was only joking; do not be angry.",py:"Tā kāi ge wánxiào éryǐ, nǐ bié shēngqì."}],exercises:[{kind:"choice",q:"我只不过是随口说说___，你可别当真。",instr:"辨析",instrEn:"Pick the right one",body:"我只不过是随口说说___，你可别当真。",options:["似的","而已","来着","着呢"],answer:1,explain:"“只不过……而已”放在句末，表示仅此而已；“似的”表示比喻，“来着”表示回忆，“着呢”强调程度高，意思都不对。",explainEn:`只不过…而已 means "just…, that's all"; 似的 compares, 来着 recalls the past, 着呢 stresses a high degree.`},{kind:"choice",q:"他只是随便开开玩笑而已，___。",instr:"完成",instrEn:"Complete the sentence",body:"他只是随便开开玩笑而已，___。",options:["你一定要认真对待","这件事已经定下来了","大家必须照他说的做","你别往心里去"],answer:3,explain:"“而已”把事情往小里说，表示不重要，所以后面应是劝人不必在意；其他选项都把事情看得很重。",explainEn:"而已 plays something down, so the follow-up should be “don't take it to heart”; the others treat it as serious."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我不过是做了自己该做的事而已。","他的汉语水平非常高而已。","这件衣服才一百块而已，不算贵。","他只是有点儿感冒而已，休息两天就好了。"],answer:1,explain:"“而已”表示往小里说，不能和“非常高”这种强调程度的说法连用，应改为“他的汉语水平只是一般而已”或去掉“而已”。",explainEn:"而已 minimizes, so it clashes with 非常高; drop 而已 or say 只是一般而已."},{q:"翻译：I only had a quick look, that's all.",a:"我只是随便看了看而已。",instr:"翻译",instrEn:"Translate",body:"I only had a quick look, that's all."}],note:"放在句末，弱化事情的重要性或范围。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Clause + éryǐ = only … / that's all",noteEn:"Goes at the end of the sentence and plays down the importance or scope.",typeEn:"Particle"},{id:"HSK6.05.2",name:"连词“固然”",pinyin:"gùrán",type:"连词/副词",explainEn:"Use 固然 to admit one fact before adding another important point: “admittedly / it is true that…”.",structure:"固然 + A，但是/可是/不过 + B",examples:[{zh:"经验固然重要，但是态度也不能忽视。",en:"Experience is important, but attitude cannot be ignored.",py:"Jīngyàn gùrán zhòngyào, dànshì tàidu yě bù néng hūshì."},{zh:"钱固然重要，健康更重要。",en:"Money is important, but health is more important.",py:"Qián gùrán zhòngyào, jiànkāng gèng zhòngyào."},{zh:"这个办法固然简单，不过不一定适合所有人。",en:"This method is simple, but it may not suit everyone.",py:"Zhège bànfǎ gùrán jiǎndān, búguò bù yídìng shìhé suǒyǒu rén."}],exercises:[{kind:"choice",q:"你能亲自来一趟___最好，派个助手来也同样可以。",instr:"辨析",instrEn:"Pick the right one",body:"你能亲自来一趟___最好，派个助手来也同样可以。",options:["虽然","固然","果然","既然"],answer:1,explain:"“A固然最好，B也可以”先肯定A，再说B同样能接受，后面不需要转折；“虽然”必须引出“但是、可是”式的真正转折，不能和“也同样可以”配合；“果然”表示和预料一样，“既然”要引出推论。",explainEn:"“A固然最好，B也可以” grants A is best while B is equally acceptable, with no real contrast; 虽然 needs a genuine turn (但是/可是), 果然 means “as expected”, and 既然 leads to a conclusion."},{kind:"choice",q:"学历固然重要，___。",instr:"完成",instrEn:"Complete the sentence",body:"学历固然重要，___。",options:["但能力和经验同样不能忽视","所以大家都该读研究生","因此找工作只看学历","于是他决定继续读书"],answer:0,explain:"“固然”先承认一个事实，后面要用“但、可是”等引出转折或补充；“所以、因此、于是”表示因果，不能配合。",explainEn:"固然 admits a fact and then turns with 但/可是; 所以/因此/于是 show cause and effect instead."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["医生说吃了药就会好，他吃了两天固然好了。","他的建议固然有道理，不过很难实行。","考试成绩固然重要，但不是唯一的标准。","住在市中心固然方便，可是房租太贵了。"],answer:0,explain:"“固然”是先承认一个事实，后面要接转折或补充，不能表示“和预料的一样”，应改为“他吃了两天果然好了”。",explainEn:"固然 concedes a point before a turn or addition; it does not mean “as expected”. Use 果然: 他吃了两天果然好了."},{q:"翻译：Talent is certainly important, but hard work matters more.",a:"天赋固然重要，但是努力更重要。",instr:"翻译",instrEn:"Translate",body:"Talent is certainly important, but hard work matters more."}],note:"先承认前一事实，再强调后面的补充或转折。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gùrán + A, dànshì/kěshì/búguò + B = admittedly A, but B",noteEn:"First admits one fact, then stresses the addition or contrast that follows.",typeEn:"Conjunction / Adverb"},{id:"HSK6.05.3",name:"副词“无非”",pinyin:"wúfēi",type:"副词",explainEn:"Use 无非 to mean “nothing more than / simply”.",structure:"无非 + 是/就是 + 名词/小句",examples:[{zh:"他这么做无非是想帮你。",en:"He did this simply because he wanted to help you.",py:"Tā zhème zuò wúfēi shì xiǎng bāng nǐ."},{zh:"原因无非有两个。",en:"There are only two possible reasons.",py:"Yuányīn wúfēi yǒu liǎng ge."},{zh:"这件事无非就是时间问题。",en:"This is nothing more than a matter of time.",py:"Zhè jiàn shì wúfēi jiùshì shíjiān wèntí."}],exercises:[{kind:"choice",q:"他绕来绕去说了半天，___是想让我们帮他搬家罢了。",instr:"辨析",instrEn:"Pick the right one",body:"他绕来绕去说了半天，___是想让我们帮他搬家罢了。",options:["莫非","无非","并非","除非"],answer:1,explain:"“无非是……罢了”表示不过如此；“莫非”用于猜测性问句，“并非”是否定，“除非”表示唯一条件。",explainEn:"无非是…罢了 means “nothing more than”; 莫非 is for guessing questions, 并非 negates, 除非 means “unless”."},{kind:"choice",q:"问他周末都干些什么，他说无非就是___。",instr:"完成",instrEn:"Complete the sentence",body:"问他周末都干些什么，他说无非就是___。",options:["去国外参加重要比赛","在家看看书、睡睡懒觉","完成一项伟大的发明","做一件惊天动地的事"],answer:1,explain:"“无非”表示范围有限、不过如此，后面应是平常的小事；其他选项都是不寻常的大事。",explainEn:'无非 means "nothing more than", so it is followed by ordinary things, not big events.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["大家吵来吵去，无非是为了一点儿钱。","他这样做无非不是想帮你。","孩子哭闹，无非就是想引起父母注意。","成功的方法无非两条：努力和坚持。"],answer:1,explain:"“无非”后面用“是、就是”，不能用“不是”，应改为“他这样做无非是想帮你”。",explainEn:"无非 is followed by 是/就是, not 不是: 他这样做无非是想帮你."},{q:"翻译：He came here simply to borrow money.",a:"他来这儿无非是想借钱。",instr:"翻译",instrEn:"Translate",body:"He came here simply to borrow money."}],note:"表示范围很有限，常有“不过就是……”的意思。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wúfēi + shì/jiùshì + Noun/Clause = nothing more than …",noteEn:`The scope is very limited — often means "it's just…".`,typeEn:"Adverb"}]},{num:6,title:"当好职场插班生",points:[{id:"HSK6.06.1",name:"副词“唯独”",pinyin:"wéidú",type:"副词",explainEn:"Use 唯独 to mean “only / except for this one”.",structure:"唯独 + 人/事物 + 谓语",examples:[{zh:"大家都同意，唯独他反对。",en:"Everyone agreed; only he objected.",py:"Dàjiā dōu tóngyì, wéidú tā fǎnduì."},{zh:"什么都准备好了，唯独忘了带钥匙。",en:"Everything was ready except the key was forgotten.",py:"Shénme dōu zhǔnbèi hǎo le, wéidú wàngle dài yàoshi."},{zh:"其他问题都解决了，唯独这个最麻烦。",en:"All other problems were solved; only this one is troublesome.",py:"Qítā wèntí dōu jiějué le, wéidú zhège zuì máfan."}],exercises:[{kind:"choice",q:"全班同学都交了作业，___小王一个人没交。",instr:"辨析",instrEn:"Pick the right one",body:"全班同学都交了作业，___小王一个人没交。",options:["单独","独自","唯一","唯独"],answer:3,explain:"“唯独”是副词，用来指出和其他人不同的那一个；“单独、独自”表示一个人做，“唯一”是形容词，不能直接放在名词主语前作状语。",explainEn:"唯独 singles out the one exception; 单独/独自 mean “alone” and 唯一 is an adjective."},{kind:"choice",q:"这家饭馆的菜样样都好，唯独___。",instr:"完成",instrEn:"Complete the sentence",body:"这家饭馆的菜样样都好，唯独___。",options:["每道菜都非常好吃","服务员的态度差了点儿","所有的菜都很便宜","店里的环境也不错"],answer:1,explain:"“唯独”引出和前面情况不同的例外，前面说都好，后面应是一个不好的地方。",explainEn:"唯独 introduces the one exception, so after “everything is good” it must be something not good."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["别的科目都及格了，唯独数学没及格。","他什么都不怕，唯独怕打针。","大家都去了，小李唯独没去。","我们家人人都爱吃辣，唯独妹妹一点儿也不能吃。"],answer:2,explain:"“唯独”要放在被强调的人或事物前面，应改为“唯独小李没去”。",explainEn:"唯独 goes before the person it singles out: 唯独小李没去."},{q:"翻译：Only this problem is troublesome.",a:"唯独这个问题最麻烦。",instr:"翻译",instrEn:"Translate",body:"Only this problem is troublesome."}],note:"强调一个人或事物与其他情况不同。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wéidú + person/thing + predicate = only … / all except …",noteEn:"Stresses that one person or thing is different from all the others.",typeEn:"Adverb"},{id:"HSK6.06.2",name:"副词“明明”",pinyin:"míngmíng",type:"副词",explainEn:"Use 明明 when a fact is very clear, often followed by a surprising contradiction.",structure:"明明 + 明确事实，却/还 + 相反情况",examples:[{zh:"他明明知道答案，却不告诉我。",en:"He clearly knows the answer, yet he will not tell me.",py:"Tā míngmíng zhīdào dá'àn, què bú gàosu wǒ."},{zh:"明明是你迟到了，怎么怪别人？",en:"You were clearly late; how can you blame others?",py:"Míngmíng shì nǐ chídào le, zěnme guài biéren?"},{zh:"天气明明很好，他却带了两把伞。",en:"The weather is clearly good, yet he brought two umbrellas.",py:"Tiānqì míngmíng hěn hǎo, tā què dàile liǎng bǎ sǎn."}],exercises:[{kind:"choice",q:"他___已经答应了，现在却说什么也不记得了。",instr:"辨析",instrEn:"Pick the right one",body:"他___已经答应了，现在却说什么也不记得了。",options:["明确","果然","明明","明白"],answer:2,explain:"“明明……却……”强调事实很清楚，后面却出现相反的情况；“明确”是形容词或动词，不能直接修饰“已经答应了”，“果然”表示和预料一样，“明白”是动词。",explainEn:'明明…却… stresses an obvious fact followed by a contrary situation; 明确 cannot modify 已经答应了 this way, 果然 means "as expected", 明白 is a verb.'},{kind:"choice",q:"你明明知道他不吃辣，___。",instr:"完成",instrEn:"Complete the sentence",body:"你明明知道他不吃辣，___。",options:["所以点了清淡的菜","因此没有点辣菜","却还点了这么辣的菜","于是给他点了汤"],answer:2,explain:"“明明”后面要接相反的情况，常用“却、还”，表示不理解或不满；“所以、因此、于是”是顺着说的。",explainEn:"明明 must be followed by a contrary fact with 却/还; 所以/因此/于是 just follow on logically."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他明明生病了，所以没来上课。","这道题明明很简单，他却做错了。","你明明在家，为什么不接电话？","钥匙明明放在桌子上，怎么找不到了？"],answer:0,explain:"“明明”后面应该是相反的情况，不能接因果关系，应改为“他生病了，所以没来上课”。",explainEn:"明明 needs a contrast, not cause and effect; drop 明明: 他生病了，所以没来上课."},{q:"翻译：You were clearly late.",a:"明明是你迟到了。",instr:"翻译",instrEn:"Translate",body:"You were clearly late."}],note:"常带不理解、不满或强调事实的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"míngmíng + obvious fact, què/hái + opposite situation = clearly …, yet …",noteEn:"Often carries puzzlement, annoyance, or emphasis on the obvious fact.",typeEn:"Adverb"},{id:"HSK6.06.3",name:"固定短语“大不了”",pinyin:"dàbuliǎo",type:"固定短语",explainEn:"Use 大不了 to mean “at worst / the worst that can happen is…”.",structure:"大不了 + 最坏结果",examples:[{zh:"失败了大不了再试一次。",en:"At worst, if we fail, we can try again.",py:"Shībài le dàbuliǎo zài shì yí cì."},{zh:"没车大不了走回去。",en:"If there is no car, at worst we can walk back.",py:"Méi chē dàbuliǎo zǒu huiqu."},{zh:"这个工作不合适，大不了换一个。",en:"If this job does not suit me, I can always change it.",py:"Zhège gōngzuò bù héshì, dàbuliǎo huàn yí ge."}],exercises:[{kind:"choice",q:"这次面试没通过也没关系，___明年再来一次。",instr:"辨析",instrEn:"Pick the right one",body:"这次面试没通过也没关系，___明年再来一次。",options:["了不起","不得了","大不了","免不了"],answer:2,explain:"“大不了”引出最坏的打算，带有看得开的语气；“了不起”是很厉害，“不得了”表示程度深或情况严重，“免不了”是避免不了。",explainEn:"大不了 means “at worst, we'll just…”; 了不起 = amazing, 不得了 = extremely/terrible, 免不了 = unavoidable."},{kind:"choice",q:"别着急，钱丢了就丢了，大不了___。",instr:"完成",instrEn:"Complete the sentence",body:"别着急，钱丢了就丢了，大不了___。",options:["有人会把它送回来","以后省着点儿花","明天就能找到了","警察会帮你找回来"],answer:1,explain:"“大不了”说出可以接受的最坏结果，有安慰的意思；“有人送回来、能找到”都是好的结果，不能用“大不了”引出。",explainEn:"大不了 introduces the worst acceptable outcome; good outcomes like getting the money back can't follow it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["火车赶不上，大不了坐下一班。","你复习得这么好，这次考试大不了能得满分。","这件事你去说吧，大不了被他骂一顿。","工作找不到，大不了先回老家住一段时间。"],answer:1,explain:"“大不了”只用来说最坏的情况，不能用于好的结果，应改为“这次考试说不定能得满分”。",explainEn:"大不了 is only for the worst case, not a good result; say 说不定能得满分."},{q:"翻译：At worst, we can walk back.",a:"大不了走回去。",instr:"翻译",instrEn:"Translate",body:"At worst, we can walk back."}],note:"用于把最坏情况说出来，常有安慰、看得开的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dàbuliǎo + worst outcome = at worst … / the worst that can happen is …",noteEn:'Names the worst case, often in a reassuring, "no big deal" tone.',typeEn:"Set phrase"}]},{num:7,title:"我的人生我做主",points:[{id:"HSK6.07.1",name:"介词“于”",pinyin:"yú",type:"介词",explainEn:"于 is a formal preposition that can mean “at/in/to/from/than”, depending on context.",structure:"动词/形容词 + 于 + 人/地/时间/比较对象",examples:[{zh:"会议将于九点开始。",en:"The meeting will begin at nine.",py:"Huìyì jiāng yú jiǔ diǎn kāishǐ."},{zh:"这本书出版于去年。",en:"This book was published last year.",py:"Zhè běn shū chūbǎn yú qùnián."},{zh:"他的成绩高于平均水平。",en:"His score is above the average.",py:"Tā de chéngjì gāo yú píngjūn shuǐpíng."}],exercises:[{kind:"choice",q:"据记载，这座寺庙始建___唐朝初年。",instr:"辨析",instrEn:"Pick the right one",body:"据记载，这座寺庙始建___唐朝初年。",options:["于","从","自从","向"],answer:0,explain:"“始建于”是固定的书面说法，“于”表示时间；“从、自从”表示起点，要和“开始、以来”等配合，“向”表示方向。",explainEn:"始建于 is a set formal phrase with 于 marking time; 从/自从 mark a starting point, 向 a direction."},{kind:"choice",q:"这部小说最早___于一九二〇年，后来被翻译成多种语言。",instr:"完成",instrEn:"Complete the sentence",body:"这部小说最早___于一九二〇年，后来被翻译成多种语言。",options:["阅读","喜爱","发表","推荐"],answer:2,explain:"“动词+于+时间”表示事情发生在什么时候，要用“发表、出版”等表示一次性事件的动词；“阅读、喜爱、推荐”不能这样用。",explainEn:"V + 于 + time needs a one-time event verb like 发表; 阅读/喜爱/推荐 don't take 于 + time."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["大会将于下月初在北京召开。","今年的收入比去年高于不少。","这种病多发于秋冬季节。","他的能力明显强于其他人。"],answer:1,explain:"“高于”本身就表示比较，不能再用“比”，应改为“比去年高不少”或“高于去年”。",explainEn:"高于 already means “higher than”, so 比 is redundant; say 比去年高不少 or 高于去年."},{q:"翻译：This museum was built in 1950.",a:"这座博物馆建于一九五〇年。",instr:"翻译",instrEn:"Translate",body:"This museum was built in 1950."}],note:"“于”书面语色彩强，具体意义要根据搭配判断。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Verb/Adj + yú + person/place/time/compared item = at / in / to / from / than …",noteEn:"于 is strongly formal; its exact meaning depends on what it goes with.",typeEn:"Preposition"},{id:"HSK6.07.2",name:"动词/连词“致使”",pinyin:"zhìshǐ",type:"动词/连词",explainEn:"Use 致使 to mean “cause / lead to”, usually for a negative result.",structure:"原因 + 致使 + 不良结果",examples:[{zh:"大雨致使比赛取消。",en:"Heavy rain caused the game to be canceled.",py:"Dàyǔ zhìshǐ bǐsài qǔxiāo."},{zh:"操作错误致使系统停止工作。",en:"An operating error caused the system to stop working.",py:"Cāozuò cuòwù zhìshǐ xìtǒng tíngzhǐ gōngzuò."},{zh:"长期缺少睡眠可能致使身体出现问题。",en:"Long-term lack of sleep may lead to health problems.",py:"Chángqī quēshǎo shuìmián kěnéng zhìshǐ shēntǐ chūxiàn wèntí."}],exercises:[{kind:"choice",q:"司机疲劳驾驶，___三名乘客受伤。",instr:"辨析",instrEn:"Pick the right one",body:"司机疲劳驾驶，___三名乘客受伤。",options:["促使","迫使","以便","致使"],answer:3,explain:"“致使”引出原因造成的不良结果；“促使”多指推动向好的方向发展，“迫使”指强迫人去做某事，“以便”表示目的。",explainEn:"致使 introduces a bad result; 促使 pushes toward a (usually good) change, 迫使 means forcing someone, 以便 shows purpose."},{kind:"choice",q:"公司管理长期混乱，致使___。",instr:"完成",instrEn:"Complete the sentence",body:"公司管理长期混乱，致使___。",options:["公司损失了几百万元","公司的利润大幅增长","员工的工资提高了","产品更受欢迎了"],answer:0,explain:"“致使”后面一般是不希望发生的结果；其他选项都是好的结果，不能用“致使”。",explainEn:"致使 is followed by an unwanted result; the others are good results."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["连续的暴雨致使河水上涨。","一时疏忽致使数据全部丢失。","老师的鼓励致使他取得了很好的成绩。","工厂排放污水，致使附近的鱼大量死亡。"],answer:2,explain:"“致使”多用于不好的结果，好的结果应改用“使”，即“老师的鼓励使他取得了很好的成绩”。",explainEn:"致使 is for bad results; for a good one use 使: 老师的鼓励使他取得了很好的成绩."},{q:"翻译：The heavy snow caused the highway to be closed.",a:"大雪致使高速公路关闭。",instr:"翻译",instrEn:"Translate",body:"The heavy snow caused the highway to be closed."}],note:"较正式，后面的结果往往是不希望发生的。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Cause + zhìshǐ + bad result = … causes / leads to …",noteEn:"Fairly formal; the result that follows is usually unwanted.",typeEn:"Verb / Conjunction"},{id:"HSK6.07.3",name:"“并非”表示否定判断",pinyin:"bìngfēi",type:"否定结构",explainEn:"Use 并非 to mean “is not actually / not necessarily”.",structure:"并非 + 名词/形容词/小句",examples:[{zh:"事情并非你想的那么简单。",en:"The matter is not actually as simple as you think.",py:"Shìqing bìngfēi nǐ xiǎng de nàme jiǎndān."},{zh:"成功并非完全靠运气。",en:"Success does not depend entirely on luck.",py:"Chénggōng bìngfēi wánquán kào yùnqi."},{zh:"他并非不愿意，只是没有时间。",en:"It is not that he is unwilling; he just has no time.",py:"Tā bìngfēi bú yuànyì, zhǐshì méiyǒu shíjiān."}],exercises:[{kind:"choice",q:"他___坏人，只是脾气急了一点儿。",instr:"辨析",instrEn:"Pick the right one",body:"他___坏人，只是脾气急了一点儿。",options:["并不","无非","莫非","并非"],answer:3,explain:"“并非”相当于“并不是”，后面可以直接接名词；“并不”后面要接动词或形容词，“无非、莫非”意思不对。",explainEn:"并非 = 并不是 and can take a noun directly; 并不 needs a verb/adjective, and 无非/莫非 mean something else."},{kind:"choice",q:"这次失败并非因为能力不够，___。",instr:"完成",instrEn:"Complete the sentence",body:"这次失败并非因为能力不够，___。",options:["所以大家都很失望","因此我们决定放弃","而是准备得不够充分","于是他离开了公司"],answer:2,explain:"“并非A，而是B”先否定一个判断，再说出正确的情况；“所以、因此、于是”表示结果，不能纠正前面的判断。",explainEn:"并非A，而是B denies one claim and gives the real one; 所以/因此/于是 just state consequences."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他昨天并非来上课，老师很生气。","高价的东西并非都是好东西。","他这样做并非出于恶意。","学好外语并非一朝一夕的事。"],answer:0,explain:"“并非”用于否定判断，不能用来否定已经发生的动作，应改为“他昨天没来上课”。",explainEn:"并非 negates a judgment, not a past action; say 他昨天没来上课."},{q:"翻译：This decision was not made by me alone.",a:"这个决定并非我一个人做的。",instr:"翻译",instrEn:"Translate",body:"This decision was not made by me alone."}],note:"比“不是”更正式，常用于纠正判断或部分否定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bìngfēi + Noun/Adj/Clause = it is not (actually) …",noteEn:"More formal than 不是; often corrects a judgment or gives a partial negation.",typeEn:"Negation"}]},{num:8,title:"遇见原来的我",points:[{id:"HSK6.08.1",name:"固定格式“对……而言”",pinyin:"duì ... ér yán",type:"固定格式",explainEn:"Use 对…而言 to mean “for… / from the point of view of…”. It is formal.",structure:"对 + 人/事物 + 而言，……",examples:[{zh:"对我而言，健康最重要。",en:"For me, health is the most important.",py:"Duì wǒ ér yán, jiànkāng zuì zhòngyào."},{zh:"对初学者而言，这篇文章有点儿难。",en:"For beginners, this article is a little difficult.",py:"Duì chūxuézhě ér yán, zhè piān wénzhāng yǒudiǎnr nán."},{zh:"对公司而言，信誉非常重要。",en:"For a company, reputation is very important.",py:"Duì gōngsī ér yán, xìnyù fēicháng zhòngyào."}],exercises:[{kind:"choice",q:"对刚工作的年轻人___，买房的压力实在太大了。",instr:"辨析",instrEn:"Pick the right one",body:"对刚工作的年轻人___，买房的压力实在太大了。",options:["起见","而言","看来","说起"],answer:1,explain:"固定格式是“对……而言”；“起见”要和“为……”配合，“看来”要和“在……”配合，“说起”要和“从……”配合。",explainEn:"The set frame is 对…而言; 起见 pairs with 为…, 看来 with 在…, 说起 with 从…."},{kind:"choice",q:"对一个刚到中国的留学生而言，___。",instr:"完成",instrEn:"Complete the sentence",body:"对一个刚到中国的留学生而言，___。",options:["他昨天去了一趟银行","他下星期三要考试","用汉语打电话并不容易","他正在宿舍里做饭"],answer:2,explain:"“对……而言”表示从某人的角度看，后面应是一个评价或判断；其他选项只是叙述具体的事情。",explainEn:"对…而言 gives a viewpoint, so it needs an evaluation; the others just report events."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["对老年人而言，智能手机并不好用。","对企业而言，人才是最宝贵的资源。","就我个人而言，我更喜欢安静的生活。","在我而言，家庭比事业更重要。"],answer:3,explain:"“而言”只能和“对、就”配合，不能说“在……而言”，应改为“对我而言”。",explainEn:"而言 pairs with 对 or 就, not 在; say 对我而言."},{q:"翻译：For students, time is the most precious thing.",a:"对学生而言，时间是最宝贵的。",instr:"翻译",instrEn:"Translate",body:"For students, time is the most precious thing."}],note:"与“对……来说”接近，但更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"duì + person/thing + ér yán, … = for … / as far as … is concerned",noteEn:"Close to 对……来说, but more formal.",typeEn:"Fixed pattern"},{id:"HSK6.08.2",name:"“有关”表示相关/关于",pinyin:"yǒuguān",type:"动词/介词",explainEn:"Use 有关 to mean “related to / concerning”.",structure:"与 + N + 有关；有关 + N",examples:[{zh:"这个问题与安全有关。",en:"This issue is related to safety.",py:"Zhège wèntí yǔ ānquán yǒuguān."},{zh:"我想了解有关申请的规定。",en:"I want to learn about the rules concerning the application.",py:"Wǒ xiǎng liǎojiě yǒuguān shēnqǐng de guīdìng."},{zh:"有关情况我们以后再讨论。",en:"We will discuss the relevant situation later.",py:"Yǒuguān qíngkuàng wǒmen yǐhòu zài tǎolùn."}],exercises:[{kind:"choice",q:"专家认为，这种病与长期的饮食习惯___。",instr:"辨析",instrEn:"Pick the right one",body:"专家认为，这种病与长期的饮食习惯___。",options:["关于","有关","关系","对于"],answer:1,explain:"“与……有关”是固定格式，“有关”在这里作动词；“关于、对于”是介词，“关系”是名词，前面要加“有”。",explainEn:"与…有关 is a set frame with 有关 as the verb; 关于/对于 are prepositions and 关系 is a noun needing 有."},{kind:"choice",q:"警方调查后发现，这起交通事故与___有关。",instr:"完成",instrEn:"Complete the sentence",body:"警方调查后发现，这起交通事故与___有关。",options:["司机酒后开车","晚上十点左右","高速公路上面","一共三辆汽车"],answer:0,explain:"“与……有关”中间是和结果有联系的事情或原因；时间、地点、数量不能这样说。",explainEn:"与…有关 needs a related matter or cause, not a time, place or number."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个问题关于大家的切身利益。","警方正在调查与此案有关的人员。","有关这次考试的安排，下周再通知。","这些问题都和环境污染有关。"],answer:0,explain:"“关于”是介词，不能作谓语，应改为“这个问题与大家的切身利益有关”。",explainEn:"关于 is a preposition and can't be the verb; say 与大家的切身利益有关."},{q:"翻译：rules concerning the application",a:"有关申请的规定",instr:"翻译",instrEn:"Translate",body:"rules concerning the application"}],note:"可作动词“与……有关”，也可直接修饰名词“有关规定”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǔ + N + yǒuguān; yǒuguān + N = related to N; N concerned",noteEn:"Works as a verb (与……有关) or directly before a noun (有关规定).",typeEn:"Verb / Preposition"},{id:"HSK6.08.3",name:"插入语“不瞒你说”",pinyin:"bùmán nǐ shuō",type:"插入语",explainEn:"Use 不瞒你说 before saying something honestly or privately: “to tell you the truth”.",structure:"不瞒你说，+ 真心话/真实情况",examples:[{zh:"不瞒你说，我也有点儿紧张。",en:"To tell you the truth, I am a little nervous too.",py:"Bù mán nǐ shuō, wǒ yě yǒudiǎnr jǐnzhāng."},{zh:"不瞒你说，我以前想过放弃。",en:"To be honest, I once thought about giving up.",py:"Bù mán nǐ shuō, wǒ yǐqián xiǎngguo fàngqì."},{zh:"不瞒你说，这个决定我考虑了很久。",en:"To tell you the truth, I thought about this decision for a long time.",py:"Bù mán nǐ shuō, zhège juédìng wǒ kǎolǜle hěn jiǔ."}],exercises:[{kind:"choice",q:"___，我第一次上台演讲的时候，紧张得手都在发抖。",instr:"辨析",instrEn:"Pick the right one",body:"___，我第一次上台演讲的时候，紧张得手都在发抖。",options:["不用你说","依我看","不瞒你说","不是我说"],answer:2,explain:"“不瞒你说”用来引出自己真实、私人的情况；“不用你说”表示对方不必提醒，“依我看”引出看法，“不是我说”多用于批评别人。",explainEn:"不瞒你说 introduces an honest personal fact; 不用你说 = no need to tell me, 依我看 = in my opinion, 不是我说 precedes criticism."},{kind:"choice",q:"不瞒你说，___。",instr:"完成",instrEn:"Complete the sentence",body:"不瞒你说，___。",options:["这次考试我其实没及格","你明天几点出发呢","请你帮我把门关上","咱们一起去吃饭吧"],answer:0,explain:"“不瞒你说”用来引出说话人自己的真实情况或心里话，后面是陈述句；提问、请求、建议都不需要它引出。",explainEn:"不瞒你说 introduces a frank statement about yourself; it doesn't introduce questions, requests or suggestions."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["不瞒你说，我对这件事一点儿也不感兴趣。","不瞒你说，这套房子是我们借钱买的。","不瞒您说，我已经三年没回过老家了。","不瞒说你，我昨天根本没去上课。"],answer:3,explain:"固定说法是“不瞒你说”，“你”要放在“说”前面，应改为“不瞒你说”。",explainEn:"The set phrase is 不瞒你说, with 你 before 说."},{q:"翻译：To be honest, I have never been to Beijing.",a:"不瞒你说，我从来没去过北京。",instr:"翻译",instrEn:"Translate",body:"To be honest, I have never been to Beijing."}],note:"常用于口语，引出比较真诚、私人的内容。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bù mán nǐ shuō, + honest words / the real situation = to tell you the truth, …",noteEn:"Common in speech; introduces something sincere or personal.",typeEn:"Parenthetical"}]},{num:9,title:"不用手机的日子",points:[{id:"HSK6.09.1",name:"状态形容词“通红、雪白”等",pinyin:"tōnghóng, xuěbái děng",type:"状态形容词",explainEn:"Some fixed forms use a noun/adverb-like element to strongly describe color or state.",structure:"通/雪/冰/笔 + 单音节形容词",examples:[{zh:"她跑得脸通红。",en:"Her face turned bright red from running.",py:"Tā pǎo de liǎn tōnghóng."},{zh:"山顶的雪雪白雪白的。",en:"The snow on the mountaintop is pure white.",py:"Shāndǐng de xuě xuěbái xuěbái de."},{zh:"她穿着一件雪白的衬衫。",en:"She is wearing a snow-white shirt.",py:"Tā chuānzhe yí jiàn xuěbái de chènshān."}],exercises:[{kind:"choice",q:"她的牙齿___的，一笑起来特别好看。",instr:"辨析",instrEn:"Pick the right one",body:"她的牙齿___的，一笑起来特别好看。",options:["很雪白","雪雪白白","非常雪白","雪白雪白"],answer:3,explain:"“雪白”是状态形容词，本身已表示程度很高，不能加“很、非常”；加强时按ABAB式重叠成“雪白雪白”，不能像“干干净净”那样重叠成AABB式。",explainEn:"雪白 already expresses a high degree, so no 很/非常; to intensify it repeats as ABAB, 雪白雪白, not AABB like 干干净净."},{kind:"choice",q:"她身上那件衬衫雪白雪白的，___。",instr:"完成",instrEn:"Complete the sentence",body:"她身上那件衬衫雪白雪白的，___。",options:["上面沾满了油污","看上去非常干净","已经穿得发黄了","颜色有点儿发灰"],answer:1,explain:"“雪白”形容像雪一样白，状态非常鲜明；沾满油污、发黄、发灰都和“雪白”的意思矛盾。",explainEn:"雪白 means snow-white; stained, yellowed or greyish all contradict it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他的脸很通红，好像发烧了。","她的手冻得冰凉冰凉的。","停电以后，屋子里一片漆黑。","炉子里的火烧得通红。"],answer:0,explain:"“通红”是状态形容词，前面不能加“很”，应改为“他的脸通红”。",explainEn:"通红 is a state adjective and can't take 很; say 他的脸通红."},{q:"翻译：His face turned bright red with anger.",a:"他气得满脸通红。",instr:"翻译",instrEn:"Translate",body:"His face turned bright red with anger."}],note:"这类词强调状态很鲜明，很多是固定搭配，需要整体记忆。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"tōng/xuě/bīng/bǐ + one-syllable Adj = vividly … (bright red, snow-white, …)",noteEn:"These words paint a vivid state; many are set combinations best learned as whole words.",typeEn:"Vivid adjective"},{id:"HSK6.09.2",name:"固定格式“说A就A”",pinyin:"shuō A jiù A",type:"固定格式",explainEn:"Use 说A就A to show someone acts immediately once they decide or say it.",structure:"说 + 动词 + 就 + 同一动词",examples:[{zh:"他说走就走，一点儿也不犹豫。",en:"He left as soon as he decided to leave, without hesitation.",py:"Tā shuō zǒu jiù zǒu, yìdiǎnr yě bù yóuyù."},{zh:"她说做就做，当天就开始准备。",en:"She started as soon as she said she would.",py:"Tā shuō zuò jiù zuò, dàngtiān jiù kāishǐ zhǔnbèi."},{zh:"这个人说来就来，说走就走。",en:"This person comes and goes whenever he decides.",py:"Zhège rén shuō lái jiù lái, shuō zǒu jiù zǒu."}],exercises:[{kind:"choice",q:"他这个人说干___干，从来不拖拖拉拉。",instr:"辨析",instrEn:"Pick the right one",body:"他这个人说干___干，从来不拖拖拉拉。",options:["才","就","也","都"],answer:1,explain:"固定格式是“说A就A”，用“就”表示说完马上做；“才、也、都”不能进入这个格式。",explainEn:"The set pattern is 说A就A; only 就 shows the action follows at once."},{kind:"choice",q:"我们只是随便聊了聊去旅行的事，没想到他说去就去，___。",instr:"完成",instrEn:"Complete the sentence",body:"我们只是随便聊了聊去旅行的事，没想到他说去就去，___。",options:["犹豫了好几个月","第二天就买好了机票","到现在也没出发","一直拿不定主意"],answer:1,explain:"“说A就A”强调动作干脆、马上发生；其他选项都表示犹豫或没有行动。",explainEn:"说A就A stresses doing it right away; the others show hesitation or inaction."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这孩子的脾气说来就来。","这里的天气说变就变，刚才还是晴天。","她说做就做，当天晚上就写好了计划。","他说走就去，谁也拦不住。"],answer:3,explain:"“说A就A”前后必须是同一个动词，应改为“他说走就走”。",explainEn:"Both verbs in 说A就A must be the same: 他说走就走."},{q:"翻译：She started as soon as she decided.",a:"她说做就做。",instr:"翻译",instrEn:"Translate",body:"She started as soon as she decided."}],note:"强调动作干脆、立即发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shuō + Verb + jiù + same Verb = do it the moment you say so",noteEn:"Stresses that the action is done decisively and at once.",typeEn:"Fixed pattern"},{id:"HSK6.09.3",name:"“形容词/动词 + 得要命”",pinyin:"xíngróngcí/dòngcí + de yàomìng",type:"程度补语",explainEn:"Use 得要命 after an adjective or feeling/state verb to mean “extremely”.",structure:"形容词/状态动词 + 得要命",examples:[{zh:"今天热得要命。",en:"It is extremely hot today.",py:"Jīntiān rè de yàomìng."},{zh:"我困得要命。",en:"I am terribly sleepy.",py:"Wǒ kùn de yàomìng."},{zh:"他紧张得要命。",en:"He is extremely nervous.",py:"Tā jǐnzhāng de yàomìng."}],exercises:[{kind:"choice",q:"这几天我忙___，连饭都顾不上吃。",instr:"辨析",instrEn:"Pick the right one",body:"这几天我忙___，连饭都顾不上吃。",options:["得多","得了","得要命","得极"],answer:2,explain:"“形容词+得要命”表示程度极深；“得多”用于比较，“得了”表示可能，“极”要说“忙极了”。",explainEn:"Adj + 得要命 means “terribly”; 得多 is comparative, 得了 is potential, and 极 needs 忙极了."},{kind:"choice",q:"爬了一整天的山，我___得要命。",instr:"完成",instrEn:"Complete the sentence",body:"爬了一整天的山，我___得要命。",options:["走","看","玩","累"],answer:3,explain:"“得要命”前面要用形容词或表示状态的动词，如“累、困、热”；“走、看、玩”是动作动词，不能这样用。",explainEn:"得要命 follows an adjective or state verb like 累; action verbs like 走/看/玩 don't fit."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["昨晚没睡好，今天我很困得要命。","这家店的东西贵得要命。","听说要考试，他紧张得要命。","外面冷得要命，你多穿点儿。"],answer:0,explain:"“得要命”已经表示程度极深，前面不能再加“很”，应改为“今天我困得要命”。",explainEn:"得要命 already means “extremely”, so drop 很: 今天我困得要命."},{q:"翻译：This suitcase is terribly heavy.",a:"这个箱子重得要命。",instr:"翻译",instrEn:"Translate",body:"This suitcase is terribly heavy."}],note:"口语较强烈，常表达不舒服、紧张、累、热等状态。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Adj / state verb + de yàomìng = terribly … / extremely …",noteEn:"Strongly colloquial; often describes discomfort, nerves, tiredness, heat, etc.",typeEn:"Degree complement"}]},{num:10,title:"全球化视野中的中国饮食",points:[{id:"HSK6.10.1",name:"连词“以至”",pinyin:"yǐzhì",type:"连词",explainEn:"Use 以至 to introduce a result that develops from the previous situation: “so that / to the extent that”.",structure:"原因/发展 + 以至 + 结果",examples:[{zh:"他太专心了，以至忘了吃饭。",en:"He was so focused that he forgot to eat.",py:"Tā tài zhuānxīn le, yǐzhì wàngle chīfàn."},{zh:"道路结冰，以至很多车无法通行。",en:"The road froze, so many cars could not pass.",py:"Dàolù jiébīng, yǐzhì hěn duō chē wúfǎ tōngxíng."},{zh:"他长期熬夜，以至身体越来越差。",en:"He stayed up late for a long time, so his health became worse.",py:"Tā chángqī áoyè, yǐzhì shēntǐ yuèláiyuè chà."}],exercises:[{kind:"choice",q:"他的演讲十分精彩，___全场观众都站起来为他鼓掌。",instr:"辨析",instrEn:"Pick the right one",body:"他的演讲十分精彩，___全场观众都站起来为他鼓掌。",options:["以及","以便","以免","以至"],answer:3,explain:"“以至”表示前面的情况发展到某种程度，引出结果；“以及”是并列连词，“以便、以免”表示目的，都不能引出这种结果。",explainEn:'以至 introduces a result reached by the situation; 以及 just means "and", 以便/以免 show purpose.'},{kind:"choice",q:"他工作太投入了，以至___。",instr:"完成",instrEn:"Complete the sentence",body:"他工作太投入了，以至___。",options:["是为了早点儿升职","因为他喜欢这份工作","连女儿的生日都忘了","好让老板对他满意"],answer:2,explain:"“以至”后面是前面情况发展造成的结果；其他选项是目的或原因，不能放在“以至”后面。",explainEn:"以至 is followed by a resulting consequence; the others give a purpose or a reason."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["雨下得太大，以至很多航班被取消了。","他越说越激动，以至声音都发抖了。","我们早点儿出发，以至能赶上第一班车。","这个问题困扰了他很久，以至他晚上都睡不着。"],answer:2,explain:"“以至”表示结果，不表示目的；这里是目的，应改为“以便能赶上第一班车”。",explainEn:"以至 marks a result, not a purpose; use 以便 here."},{q:"翻译：He was so excited that he couldn't say a word.",a:"他太激动了，以至一句话也说不出来。",instr:"翻译",instrEn:"Translate",body:"He was so excited that he couldn't say a word."}],note:"较书面，后面多是前一情况发展导致的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Cause / development + yǐzhì + result = so much so that …",noteEn:"Fairly formal; what follows is usually a result that grew out of the previous situation.",typeEn:"Conjunction"},{id:"HSK6.10.2",name:"连词“即便”",pinyin:"jíbiàn",type:"连词",explainEn:"Use 即便 to mean “even if / even though”.",structure:"即便 + 条件，也/还 + 结果",examples:[{zh:"即便下雨，我们也会按时出发。",en:"Even if it rains, we will leave on time.",py:"Jíbiàn xià yǔ, wǒmen yě huì ànshí chūfā."},{zh:"即便失败了，也不要放弃。",en:"Even if you fail, do not give up.",py:"Jíbiàn shībài le, yě búyào fàngqì."},{zh:"即便很忙，他还是坚持读书。",en:"Even though he is busy, he still keeps reading.",py:"Jíbiàn hěn máng, tā háishi jiānchí dúshū."}],exercises:[{kind:"choice",q:"___明天下大雨，比赛也照常进行。",instr:"辨析",instrEn:"Pick the right one",body:"___明天下大雨，比赛也照常进行。",options:["虽然","即便","既然","只要"],answer:1,explain:"“即便……也……”用于假设的让步；“虽然”用于已经是事实的情况，“既然”后面不用“也”，“只要”要和“就”配合。",explainEn:`即便…也… is a hypothetical "even if"; 虽然 is for facts, 既然 doesn't take 也, 只要 pairs with 就.`},{kind:"choice",q:"即便你说的都是事实，___。",instr:"完成",instrEn:"Complete the sentence",body:"即便你说的都是事实，___。",options:["所以大家都相信你","因此我们都支持你","就应该马上公布出来","也不该用这种态度说话"],answer:3,explain:"“即便”后面要用“也、还”表示结果不变；“所以、因此、就”不能和“即便”配合。",explainEn:"即便 must be answered by 也/还; 所以/因此/就 don't pair with it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["即便是周末，他也很早起床。","即便明天下雨，我们也要去。","即便失败了，这也是一次宝贵的经历。","即便工作再忙，他就坚持每天锻炼。"],answer:3,explain:"“即便”要和“也、还”配合，不能用“就”，应改为“他也坚持每天锻炼”。",explainEn:"即便 pairs with 也/还, not 就: 他也坚持每天锻炼."},{q:"翻译：Even if you are busy, you should call your parents.",a:"即便再忙，你也应该给父母打个电话。",instr:"翻译",instrEn:"Translate",body:"Even if you are busy, you should call your parents."}],note:"和“即使”接近，书面语较常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jíbiàn + condition, yě/hái + result = even if …, still …",noteEn:"Close to 即使; more common in writing.",typeEn:"Conjunction"},{id:"HSK6.10.3",name:"名词“所在”",pinyin:"suǒzài",type:"名词",explainEn:"Use 所在 to mean “the place/key point where something lies”.",structure:"问题/原因/意义 + 所在；所在地",examples:[{zh:"这正是问题所在。",en:"This is exactly where the problem lies.",py:"Zhè zhèng shì wèntí suǒzài."},{zh:"我们终于找到了原因所在。",en:"We finally found where the cause lies.",py:"Wǒmen zhōngyú zhǎodàole yuányīn suǒzài."},{zh:"请填写公司所在地。",en:"Please fill in the location of the company.",py:"Qǐng tiánxiě gōngsī suǒzàidì."}],exercises:[{kind:"choice",q:"经过反复检查，工程师终于找到了故障___。",instr:"辨析",instrEn:"Pick the right one",body:"经过反复检查，工程师终于找到了故障___。",options:["所有","所在","在于","所以"],answer:1,explain:"“故障所在”指故障在什么地方，“所在”是名词；“所有”表示全部，“在于”是动词，后面要带宾语，“所以”是连词。",explainEn:"所在 is a noun meaning “where something lies”; 所有 means “all”, 在于 is a verb needing an object, 所以 is a conjunction."},{kind:"choice",q:"坚持和努力，正是他成功的___所在。",instr:"完成",instrEn:"Complete the sentence",body:"坚持和努力，正是他成功的___所在。",options:["日期","次数","关键","速度"],answer:2,explain:"“所在”常和“问题、原因、关键、意义”等抽象名词搭配，表示要点在哪里；“日期、次数、速度”不能这样用。",explainEn:"所在 combines with abstract nouns like 问题/原因/关键/意义, not with 日期/次数/速度."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这就是两国合作的意义所在。","找到原因所在，才能解决问题。","他的所在公司在上海。","请在表格上写明企业所在地。"],answer:2,explain:"“所在”修饰名词时要说“他所在的公司”，不能说“他的所在公司”。",explainEn:"Say 他所在的公司 (the company where he works), not 他的所在公司."},{q:"翻译：We found where the cause lies.",a:"我们找到了原因所在。",instr:"翻译",instrEn:"Translate",body:"We found where the cause lies."}],note:"常见“问题所在、原因所在、意义所在、所在地”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèntí/yuányīn/yìyì + suǒzài; suǒzàidì = where the problem/reason/meaning lies; location",noteEn:"Common in 问题所在, 原因所在, 意义所在, 所在地.",typeEn:"Noun"}]},{num:11,title:"我不在时，猫在干什么",points:[{id:"HSK6.11.1",name:"副词“统统”",pinyin:"tǒngtǒng",type:"副词",explainEn:"Use 统统 to mean “all / entirely”, with strong emphasis.",structure:"范围 + 统统 + 谓语",examples:[{zh:"这些问题我统统解决了。",en:"I solved all these problems.",py:"Zhèxiē wèntí wǒ tǒngtǒng jiějué le."},{zh:"他把旧东西统统扔掉了。",en:"He threw all the old things away.",py:"Tā bǎ jiù dōngxi tǒngtǒng rēngdiào le."},{zh:"不需要的文件统统删除。",en:"Delete all unnecessary files.",py:"Bù xūyào de wénjiàn tǒngtǒng shānchú."}],exercises:[{kind:"choice",q:"这些过期的药已经不能吃了，___扔掉吧。",instr:"辨析",instrEn:"Pick the right one",body:"这些过期的药已经不能吃了，___扔掉吧。",options:["统统","一共","总共","共同"],answer:0,explain:"“统统”表示全部、一个不剩；“一共、总共”用于计算数量，“共同”表示大家一起做。",explainEn:"统统 means “all of them”; 一共/总共 are for totals, 共同 means doing something together."},{kind:"choice",q:"___我统统都看过了，没有一本不喜欢的。",instr:"完成",instrEn:"Complete the sentence",body:"___我统统都看过了，没有一本不喜欢的。",options:["他写的那几本小说","他写的第一本小说","他昨天借的那本小说","桌上那一本小说"],answer:0,explain:"“统统”总括前面提到的全部人或事物，前面应该是复数；“第一本、那本、那一本”只有一本，不能用“统统”。",explainEn:"统统 sums up a plural set, so the topic must be several books, not one."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["书架上的书统统有三百多本。","抽屉里的旧信，她统统烧掉了。","这些菜你们统统吃完吧。","大家的意见我统统记下来了。"],answer:0,explain:"“统统”表示全部、一个不剩，不能用来计算总数，应改为“书架上的书一共有三百多本”。",explainEn:`统统 means "all, every one"; it can't total up a number, so say 一共有三百多本.`},{q:"翻译：Put all these books back on the shelf.",a:"把这些书统统放回书架上。",instr:"翻译",instrEn:"Translate",body:"Put all these books back on the shelf."}],note:"比“都”语气更强，常表示一个不剩。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Scope + tǒngtǒng + predicate = all of it / every last one",noteEn:'Stronger than 都; often means "every last one".',typeEn:"Adverb"},{id:"HSK6.11.2",name:"固定格式“以……为……”",pinyin:"yǐ ... wéi ...",type:"固定格式",explainEn:"Use 以…为… to mean “take/use…as…”. It is formal.",structure:"以 + A + 为 + B",examples:[{zh:"我们以安全为第一原则。",en:"We take safety as our first principle.",py:"Wǒmen yǐ ānquán wéi dì-yī yuánzé."},{zh:"这家公司以服务好而闻名。",en:"This company is famous for good service.",py:"Zhè jiā gōngsī yǐ fúwù hǎo ér wénmíng."},{zh:"文章以一个真实故事为例。",en:"The article uses a true story as an example.",py:"Wénzhāng yǐ yí ge zhēnshí gùshi wéi lì."}],exercises:[{kind:"choice",q:"这家餐厅以川菜___主，也做一些家常菜。",instr:"辨析",instrEn:"Pick the right one",body:"这家餐厅以川菜___主，也做一些家常菜。",options:["是","为","成","当"],answer:1,explain:"固定格式是“以……为主”，“为”是书面语，意思是“作为、是”；“是、成、当”不能放进这个格式。",explainEn:`The fixed pattern is 以…为主; 为 means "to be/as" here, and 是/成/当 can't replace it.`},{kind:"choice",q:"一家好的公司应该以客户的需求为___。",instr:"完成",instrEn:"Complete the sentence",body:"一家好的公司应该以客户的需求为___。",options:["原因","结果","中心","程度"],answer:2,explain:"“以……为中心”是常见搭配，表示把某事放在最重要的位置；“以……为原因、结果、程度”都不这么说。",explainEn:"以…为中心 is a common collocation; 以…为原因/结果/程度 are not used."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这部电影以真实事件为基础。","我们要以保护环境是首要任务。","他一直以老师为榜样，努力学习。","下面我们以北京为例来说明这个问题。"],answer:1,explain:"“以”要和“为”配合，不能用“是”，应改为“以保护环境为首要任务”。",explainEn:"以 must pair with 为, not 是: 以保护环境为首要任务."},{q:"翻译：Our course focuses mainly on speaking.",a:"我们的课程以口语为主。",instr:"翻译",instrEn:"Translate",body:"Our course focuses mainly on speaking."}],note:"常见“以……为主、以……为例、以……为目标、以……为基础”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǐ + A + wéi + B = take A as B",noteEn:"Common in 以……为主, 以……为例, 以……为目标, 以……为基础.",typeEn:"Fixed pattern"},{id:"HSK6.11.3",name:"固定格式“该干吗干吗”",pinyin:"gāi gànmá gànmá",type:"固定格式",explainEn:"Use 该干吗干吗 to mean “just do whatever you normally should do”.",structure:"该 + 动词/动宾 + 什么/吗 + 动词/动宾",examples:[{zh:"你别管我，该干吗干吗。",en:"Do not worry about me; just do what you normally do.",py:"Nǐ bié guǎn wǒ, gāi gànmá gànmá."},{zh:"放假也不用特别安排，该干吗干吗。",en:"You do not need special plans for the holiday; just do as usual.",py:"Fàngjià yě búyòng tèbié ānpái, gāi gànmá gànmá."},{zh:"医生说没事，让我该吃吃，该睡睡。",en:"The doctor said I was fine and told me to eat and sleep as usual.",py:"Yīshēng shuō méishì, ràng wǒ gāi chī chī, gāi shuì shuì."}],exercises:[{kind:"choice",q:"考完试了就别想那么多了，___。",instr:"辨析",instrEn:"Pick the right one",body:"考完试了就别想那么多了，___。",options:["干吗该干吗","该干吗干吗","该干吗吗干","干吗干吗该"],answer:1,explain:"固定格式是“该+动词+吗+同一动词”，即“该干吗干吗”；其他语序都不对。",explainEn:"The fixed order is 该 + V + 吗 + V: 该干吗干吗."},{kind:"choice",q:"虽然明天就要考试了，他还是该干吗干吗，___。",instr:"完成",instrEn:"Complete the sentence",body:"虽然明天就要考试了，他还是该干吗干吗，___。",options:["紧张得吃不下饭","把计划都取消了","一点儿也不紧张","整晚都熬夜复习"],answer:2,explain:"“该干吗干吗”表示不因某事改变平常的生活；紧张得吃不下饭、取消计划、熬夜复习都说明生活被打乱了。",explainEn:"该干吗干吗 means carrying on as normal; the others show life being disrupted."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["别管他们说什么，咱们该干吗干吗。","医生说没大问题，让我该吃吃，该睡觉睡。","老板出差了，大家还是该干什么干什么。","放假在家，他该吃吃，该玩玩，过得很轻松。"],answer:1,explain:"这个格式前后要用相同的部分，应改为“该睡觉睡觉”。",explainEn:"Both halves must repeat the same verb phrase: 该睡觉睡觉."},{q:"翻译：Just do as usual.",a:"该干吗干吗。",instr:"翻译",instrEn:"Translate",body:"Just do as usual."}],note:"口语固定格式，表示不必因某事改变正常生活。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gāi + Verb/V-O + shénme/má + Verb/V-O = just do whatever you'd normally do",noteEn:"A spoken set pattern: no need to change your normal life because of something.",typeEn:"Fixed pattern"}]},{num:12,title:"我们都爱白噪音",points:[{id:"HSK6.12.1",name:"副词“不妨”",pinyin:"bùfáng",type:"副词",explainEn:"Use 不妨 to make a mild suggestion: “you might as well / why not”.",structure:"不妨 + 动词",examples:[{zh:"累了不妨休息一会儿。",en:"If you are tired, you might as well rest for a while.",py:"Lèi le bùfáng xiūxi yíhuìr."},{zh:"这个办法不错，你不妨试试。",en:"This method is good; why not try it?",py:"Zhège bànfǎ búcuò, nǐ bùfáng shìshi."},{zh:"周末不妨出去走走。",en:"You might as well go out for a walk this weekend.",py:"Zhōumò bùfáng chūqu zǒuzou."}],exercises:[{kind:"choice",q:"这家小店的菜很有特色，你有空___去尝尝。",instr:"辨析",instrEn:"Pick the right one",body:"这家小店的菜很有特色，你有空___去尝尝。",options:["不必","不免","不得","不妨"],answer:3,explain:"“不妨”用来提出温和的建议，表示这样做也没什么不好；“不必”是没必要，“不免”表示免不了，“不得”是不许。",explainEn:"不妨 gently suggests “you might as well”; 不必 = no need, 不免 = can't help but, 不得 = must not."},{kind:"choice",q:"要是你对这个结果不满意，不妨___。",instr:"完成",instrEn:"Complete the sentence",body:"要是你对这个结果不满意，不妨___。",options:["必须马上辞职","千万别再试了","再换个方法试试","绝对不能改变"],answer:2,explain:"“不妨”后面是语气轻松的建议；“必须、千万别、绝对不能”是强烈的要求或禁止，与“不妨”的语气不合。",explainEn:"不妨 introduces a light suggestion; 必须/千万别/绝对不能 are strong orders or bans."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["有什么想法，你不妨直说。","既然来了，不妨多住几天。","考试时不妨带上身份证，否则不能进考场。","这本书写得不错，你不妨看看。"],answer:2,explain:"不带证件就不能进考场，是必须做的事，不能用语气很轻的“不妨”，应改为“务必带上身份证”。",explainEn:"This is a must, not a casual suggestion, so use 务必 instead of 不妨."},{q:"翻译：You might as well rest for a while.",a:"你不妨休息一会儿。",instr:"翻译",instrEn:"Translate",body:"You might as well rest for a while."}],note:"语气比“应该、必须”轻，常用于建议。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùfáng + Verb = you might as well … / why not …",noteEn:"Softer than 应该/必须; used for suggestions.",typeEn:"Adverb"},{id:"HSK6.12.2",name:"副词“务必”",pinyin:"wùbì",type:"副词",explainEn:"Use 务必 to mean “must / be sure to”. It is formal and strong.",structure:"务必 + 动词",examples:[{zh:"请务必按时到达。",en:"Please be sure to arrive on time.",py:"Qǐng wùbì ànshí dàodá."},{zh:"出门前务必关好门窗。",en:"Be sure to close the doors and windows before leaving.",py:"Chūmén qián wùbì guānhǎo ménchuāng."},{zh:"重要文件务必备份。",en:"Important files must be backed up.",py:"Zhòngyào wénjiàn wùbì bèifèn."}],exercises:[{kind:"choice",q:"明天的面试非常重要，请___带好身份证件。",instr:"辨析",instrEn:"Pick the right one",body:"明天的面试非常重要，请___带好身份证件。",options:["未必","何必","不妨","务必"],answer:3,explain:"“务必”表示一定要做，常用于正式提醒；“未必”是不一定，“何必”是没有必要，“不妨”语气太轻，不合“非常重要”。",explainEn:"务必 means “be sure to”; 未必 = not necessarily, 何必 = why bother, 不妨 is too light for something very important."},{kind:"choice",q:"明天早上的航班很早，请大家务必___。",instr:"完成",instrEn:"Complete the sentence",body:"明天早上的航班很早，请大家务必___。",options:["在六点前到大厅集合","昨天已经集合过了","随便什么时候来都行","不想来就别来了"],answer:0,explain:"“务必”用来提出必须做到的要求，后面是将要做的具体动作；其他选项不是要求，或者表示随便。",explainEn:"务必 introduces a firm requirement for a future action; the others are past events or say it doesn't matter."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他昨天务必按时到了公司。","此事关系重大，请务必保密。","请务必在月底前交齐材料。","离开实验室前务必关掉电源。"],answer:0,explain:"“务必”用于要求或提醒，不能叙述已经发生的事，应改为“他昨天按时到了公司”。",explainEn:"务必 is for requests, not for narrating past events; drop it: 他昨天按时到了公司."},{q:"翻译：Please be sure to bring your passport.",a:"请务必带好护照。",instr:"翻译",instrEn:"Translate",body:"Please be sure to bring your passport."}],note:"常见于通知、提醒、正式要求。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wùbì + Verb = be sure to … / must",noteEn:"Common in notices, reminders and formal requests.",typeEn:"Adverb"},{id:"HSK6.12.3",name:"连词“鉴于”",pinyin:"jiànyú",type:"连词/介词",explainEn:"Use 鉴于 to mean “in view of / considering”. It introduces a known reason.",structure:"鉴于 + 情况/原因，+ 决定/结果",examples:[{zh:"鉴于天气不好，活动改到室内。",en:"In view of the bad weather, the event was moved indoors.",py:"Jiànyú tiānqì bù hǎo, huódòng gǎidào shìnèi."},{zh:"鉴于时间有限，我们先讨论重点。",en:"Considering the limited time, let us discuss the key points first.",py:"Jiànyú shíjiān yǒuxiàn, wǒmen xiān tǎolùn zhòngdiǎn."},{zh:"鉴于他的表现，公司决定给他机会。",en:"In view of his performance, the company decided to give him a chance.",py:"Jiànyú tā de biǎoxiàn, gōngsī juédìng gěi tā jīhuì."}],exercises:[{kind:"choice",q:"___他多次违反公司规定，公司决定将其辞退。",instr:"辨析",instrEn:"Pick the right one",body:"___他多次违反公司规定，公司决定将其辞退。",options:["关于","至于","以至","鉴于"],answer:3,explain:"“鉴于”引出作出决定的原因或依据；“关于”引出话题，“至于”用来转换话题，“以至”引出结果。",explainEn:"鉴于 gives the reason for a decision; 关于 introduces a topic, 至于 switches topic, 以至 introduces a result."},{kind:"choice",q:"鉴于近期多次发生安全事故，___。",instr:"完成",instrEn:"Complete the sentence",body:"鉴于近期多次发生安全事故，___。",options:["很多员工因此受了伤","工厂的产量下降了不少","有几名工人住进了医院","公司决定全面检查设备"],answer:3,explain:"“鉴于”引出作出决定的依据，主句应是根据情况采取的措施；单纯说造成的后果要用“由于”。",explainEn:"鉴于 gives the grounds for a decision, so the main clause must be a measure taken; plain consequences go with 由于."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["鉴于以上情况，我们决定推迟会议。","天气越来越冷，鉴于大家都穿上了厚衣服。","鉴于他的出色表现，公司给他加了工资。","鉴于时间紧迫，请大家抓紧准备。"],answer:1,explain:"“鉴于”引出原因，不能引出结果，应改为“天气越来越冷，所以大家都穿上了厚衣服”。",explainEn:"鉴于 introduces a reason, not a result; use 所以 here."},{q:"翻译：In view of his age, the doctor suggested postponing the operation.",a:"鉴于他年纪大了，医生建议推迟手术。",instr:"翻译",instrEn:"Translate",body:"In view of his age, the doctor suggested postponing the operation."}],note:"较正式，常用于书面说明原因和决定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiànyú + situation/reason, + decision/result = in view of …, …",noteEn:"Fairly formal; used in writing to state a reason and the decision taken.",typeEn:"Conjunction / Prep."}]},{num:13,title:"从旅游指南看世事变迁",points:[{id:"HSK6.13.1",name:"动词“便于”",pinyin:"biànyú",type:"动词",explainEn:"Use 便于 to mean “be convenient for / make it easier to…”.",structure:"便于 + 动词/名词",examples:[{zh:"这个表格便于大家比较。",en:"This table makes comparison easier.",py:"Zhège biǎogé biànyú dàjiā bǐjiào."},{zh:"文件按日期分类，便于查找。",en:"The files are sorted by date for easier searching.",py:"Wénjiàn àn rìqī fēnlèi, biànyú cházhǎo."},{zh:"请留下电话，便于我们联系你。",en:"Please leave your phone number so we can contact you easily.",py:"Qǐng liúxià diànhuà, biànyú wǒmen liánxì nǐ."}],exercises:[{kind:"choice",q:"这种折叠伞又轻又小，十分___随身携带。",instr:"辨析",instrEn:"Pick the right one",body:"这种折叠伞又轻又小，十分___随身携带。",options:["便于","以便","随便","顺便"],answer:0,explain:"“便于”是动词，可以受“十分”修饰，直接带“随身携带”；“以便”是连词，只能放在后一分句开头，前面不能加“十分”；“随便、顺便”意思不对。",explainEn:"便于 is a verb (“easy to”), so it can take 十分 and the verb 携带; 以便 is a conjunction opening a purpose clause and can’t follow 十分; 随便/顺便 mean casually/on the way."},{kind:"choice",q:"楼道里每一层都贴了指示牌，便于___。",instr:"完成",instrEn:"Complete the sentence",body:"楼道里每一层都贴了指示牌，便于___。",options:["客人走错地方","客人都很满意","第一次来的客人找路","节省了不少时间"],answer:2,explain:"“便于”表示使某个动作容易进行，后面接要做的动作“找路”；“走错地方”是要避免的事，应该用“以免”；“很满意”是感受，“节省了时间”是已有的结果，都不能放在“便于”后面。",explainEn:"便于 makes an action easier to do, here finding the way; going the wrong way is something to prevent (以免), and being satisfied or having saved time are a feeling and a past result, not actions made easier."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["表格要简单明了，便于填写。","这个设计对老年人便于使用。","这种字体比较大，便于阅读。","这种药做成了小颗粒，便于儿童服用。"],answer:1,explain:"“便于”后面直接接使用的人和动作，应改为“这个设计便于老年人使用”。",explainEn:"便于 takes the user and action directly: 这个设计便于老年人使用."},{q:"翻译：Shorter sentences are easier to remember.",a:"句子短一些，便于记忆。",instr:"翻译",instrEn:"Translate",body:"Shorter sentences are easier to remember."}],note:"常用于说明某种安排带来的便利。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biànyú + Verb/Noun = make it easy to …",noteEn:"Often explains the convenience an arrangement brings.",typeEn:"Verb"},{id:"HSK6.13.2",name:"动词“犹如”",pinyin:"yóurú",type:"动词/比喻词",explainEn:"Use 犹如 to mean “be like / just like”. It is literary/formal.",structure:"A + 犹如 + B",examples:[{zh:"平静的湖面犹如一面镜子。",en:"The calm lake is like a mirror.",py:"Píngjìng de húmiàn yóurú yí miàn jìngzi."},{zh:"孩子的笑声犹如阳光一样温暖。",en:"The child's laughter is as warm as sunshine.",py:"Háizi de xiàoshēng yóurú yángguāng yíyàng wēnnuǎn."},{zh:"网络犹如一座巨大的图书馆。",en:"The internet is like a huge library.",py:"Wǎngluò yóurú yí zuò jùdà de túshūguǎn."}],exercises:[{kind:"choice",q:"清晨的大雾___一层白纱，轻轻地盖住了整个山村。",instr:"辨析",instrEn:"Pick the right one",body:"清晨的大雾___一层白纱，轻轻地盖住了整个山村。",options:["犹如","似乎","如果","犹豫"],answer:0,explain:"“犹如”是书面语的比喻词，意思是“好像”，后面接名词；“似乎”是副词，后面接动词或形容词，“如果、犹豫”意思不对。",explainEn:"犹如 means “like” and takes a noun; 似乎 is an adverb before verbs/adjectives, 如果 = if, 犹豫 = hesitate."},{kind:"choice",q:"在那段最困难的日子里，朋友的鼓励犹如___。",instr:"完成",instrEn:"Complete the sentence",body:"在那段最困难的日子里，朋友的鼓励犹如___。",options:["非常温暖，非常有力量","温暖了我那颗冰冷的心","冬日里的一缕温暖阳光","让我一下子充满了力量"],answer:2,explain:"“犹如”是比喻词，后面要接一个名词性的比喻对象；形容词短语或动词短语不能直接放在“犹如”后面。",explainEn:`犹如 ("just like") must be followed by a noun image; adjective or verb phrases can't follow it.`},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["时间犹如流水，一去不复返。","这个消息犹如一声春雷，震动了全城。","我的身高犹如我哥哥。","两人的感情犹如亲兄弟一般。"],answer:2,explain:"“犹如”用于比喻，不能用于比较两个人的实际高矮，应改为“我和我哥哥一样高”。",explainEn:"犹如 is for metaphors, not literal comparisons; say 我和我哥哥一样高."},{q:"翻译：Her voice is like a beautiful song.",a:"她的声音犹如一首动听的歌。",instr:"翻译",instrEn:"Translate",body:"Her voice is like a beautiful song."}],note:"比“像”更书面，常用于比喻。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + yóurú + B = A is just like B",noteEn:"More literary than 像; used in similes.",typeEn:"Verb / Simile word"},{id:"HSK6.13.3",name:"比较格式“和……相比”",pinyin:"hé ... xiāngbǐ",type:"比较结构",explainEn:"Use 和…相比 to mean “compared with…”.",structure:"A + 和 + B + 相比，……",examples:[{zh:"和去年相比，今年更忙。",en:"Compared with last year, this year is busier.",py:"Hé qùnián xiāngbǐ, jīnnián gèng máng."},{zh:"和开车相比，坐地铁更方便。",en:"Compared with driving, taking the subway is more convenient.",py:"Hé kāichē xiāngbǐ, zuò dìtiě gèng fāngbiàn."},{zh:"和以前相比，他成熟多了。",en:"Compared with before, he is much more mature.",py:"Hé yǐqián xiāngbǐ, tā chéngshú duō le."}],exercises:[{kind:"choice",q:"___过去相比，现在出门方便多了。",instr:"辨析",instrEn:"Pick the right one",body:"___过去相比，现在出门方便多了。",options:["比","对","把","和"],answer:3,explain:"固定格式是“和……相比”；“比”本身已表示比较，不能再和“相比”一起用，“对、把”也不能进入这个格式。",explainEn:"The frame is 和…相比; 比 already means “compared to” and can't combine with 相比."},{kind:"choice",q:"和十年前相比，这座城市___。",instr:"完成",instrEn:"Complete the sentence",body:"和十年前相比，这座城市___。",options:["一直都非常干净","以后会更加干净","十年前也很干净","干净了许多"],answer:3,explain:"“和……相比”要说出现在跟比较对象之间的差别，“干净了许多”正是现在和十年前的差别；“一直很干净”没有比较，“以后会更干净”比的是将来，“十年前也很干净”只说了比较对象本身。",explainEn:"和…相比 must state how now differs from the thing compared, i.e. much cleaner than ten years ago; “always clean” compares nothing, “will be cleaner” is about the future, and “was also clean then” only describes the past."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["和城市相比，农村的空气更新鲜。","和上个月相比，这个月的销售额增长了两成。","和别人相比，他的条件并不算好。","和他相比，我比他高一点儿。"],answer:3,explain:"用了“和……相比”后，后句不能再用“比他”，应改为“和他相比，我高一点儿”。",explainEn:"After 和…相比, don't repeat 比他; say 和他相比，我高一点儿."},{q:"翻译：Compared with his brother, he is more outgoing.",a:"和哥哥相比，他更外向。",instr:"翻译",instrEn:"Translate",body:"Compared with his brother, he is more outgoing."}],note:"比较对象常放在前面，后句说明差异。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + hé + B + xiāngbǐ, … = compared with B, A …",noteEn:"The thing compared usually comes first; the next clause says how they differ.",typeEn:"Comparison structure"}]},{num:14,title:"背着电饭锅拍北极",points:[{id:"HSK6.14.1",name:"数量短语的重叠",pinyin:"shùliàng duǎnyǔ de chóngdié",type:"数量结构",explainEn:"Repeat a number-measure phrase to mean “one by one / in groups / gradually”.",structure:"一A一A；两A两A；数量短语重叠 + 地/都",examples:[{zh:"大家一个一个地进去。",en:"Everyone went in one by one.",py:"Dàjiā yí ge yí ge de jìnqu."},{zh:"请一页一页地看。",en:"Please read page by page.",py:"Qǐng yí yè yí yè de kàn."},{zh:"学生两个人两个人地练习。",en:"The students practice in pairs.",py:"Xuésheng liǎng ge rén liǎng ge rén de liànxí."}],exercises:[{kind:"choice",q:"检票口很窄，请大家___地进，别挤。",instr:"辨析",instrEn:"Pick the right one",body:"检票口很窄，请大家___地进，别挤。",options:["每一个","一个一个","个个","一个比一个"],answer:1,explain:"“一个一个地”表示按顺序逐个进行，可用于提出要求；“每一个”不能重叠后加“地”作状语，“个个”表示每一个，要和“都”连用，“一个比一个”表示程度递进。",explainEn:"“一个一个地” = one at a time, fine in a request; “每一个” can’t take 地 as an adverbial, “个个” means “every one” (with 都), and “一个比一个” means “each more … than the last”."},{kind:"choice",q:"他把那些旧照片一张一张地___。",instr:"完成",instrEn:"Complete the sentence",body:"他把那些旧照片一张一张地___。",options:["一下子全倒在桌上","同时塞进了箱子","一起摊开在桌上","拿起来仔细看"],answer:3,explain:"数量重叠表示逐个依次进行，只能接逐张进行的动作；“一下子、同时、一起”都表示一次完成，和它矛盾。",explainEn:"The repeated measure phrase means one at a time, so it can’t go with “all at once / at the same time / together”."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他一本一本书地把这些小说看完了。","他把衣服一件一件地叠好放进箱子。","队员们两个人两个人地进行训练。","孩子们一个一个地走过小桥。"],answer:0,explain:"重叠要成对完整：应说“一本一本地”或“一本书一本书地”，不能只在后一个加名词。",explainEn:"Both halves must match: say “一本一本地” or “一本书一本书地”, not “一本一本书地”."},{q:"翻译：The guests walked in one by one and found their seats.",a:"客人们一个一个地走进来，找到了自己的座位。",instr:"翻译",instrEn:"Translate",body:"The guests walked in one by one and found their seats."}],note:"表示按相同数量依次、分组或逐步进行。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yī A yī A; liǎng A liǎng A; repeated num-measure + de/dōu = one by one / two by two",noteEn:"Means doing something in equal amounts, in turn, in groups or step by step.",typeEn:"Quantity structure"},{id:"HSK6.14.2",name:"动词“难以”",pinyin:"nányǐ",type:"动词",explainEn:"Use 难以 before a verb to mean “be difficult to / hard to”.",structure:"难以 + 动词",examples:[{zh:"这个问题难以解决。",en:"This problem is difficult to solve.",py:"Zhège wèntí nányǐ jiějué."},{zh:"他的心情难以用语言表达。",en:"His feelings are hard to express in words.",py:"Tā de xīnqíng nányǐ yòng yǔyán biǎodá."},{zh:"这个变化短期内难以看出来。",en:"This change is hard to see in the short term.",py:"Zhège biànhuà duǎnqī nèi nányǐ kàn chulai."}],exercises:[{kind:"choice",q:"他的说法前后矛盾，令人___相信。",instr:"辨析",instrEn:"Pick the right one",body:"他的说法前后矛盾，令人___相信。",options:["未免","难免","难以","不禁"],answer:2,explain:"“难以 + 动词”表示很难做到，“令人难以相信”是固定说法；“难免”表示不可避免，“未免”表示评价过分，“不禁”表示控制不住，都不能接“相信”这样用。",explainEn:"“难以相信” = hard to believe; 难免 = unavoidably, 未免 = rather too, 不禁 = can’t help — none fit here."},{kind:"choice",q:"这样苛刻的条件，我们实在难以___。",instr:"完成",instrEn:"Complete the sentence",body:"这样苛刻的条件，我们实在难以___。",options:["不接受","接受","接受了","接受得了"],answer:1,explain:"“难以”后直接接动词原形，不带“了”、否定或可能补语；“难以接受得了”语义重复。",explainEn:"“难以” takes a bare verb — no 了, no negation, no potential complement."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这种损失是用金钱难以衡量的。","两国的文化差异一时难以消除。","他的字写得太乱，难以辨认。","这道数学题太难以了，谁都做不出来。"],answer:3,explain:"“难以”是动词，后面必须接动词，不能单独作形容词谓语；应改为“这道数学题太难了”。",explainEn:"“难以” must be followed by a verb; say “太难了”, not “太难以了”."},{q:"翻译：His feelings are hard to express.",a:"他的心情难以表达。",instr:"翻译",instrEn:"Translate",body:"His feelings are hard to express."}],note:"较书面，后面直接接动词。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nányǐ + Verb = hard to …",noteEn:"Fairly formal; followed directly by a verb.",typeEn:"Verb"},{id:"HSK6.14.3",name:"连词“免得”",pinyin:"miǎnde",type:"连词",explainEn:"Use 免得 to mean “so as to avoid / lest”.",structure:"动作1，免得 + 不好的结果",examples:[{zh:"早点儿出发，免得堵车。",en:"Leave early to avoid traffic.",py:"Zǎo diǎnr chūfā, miǎnde dǔchē."},{zh:"把地址记下来，免得忘了。",en:"Write down the address so you do not forget it.",py:"Bǎ dìzhǐ jì xialai, miǎnde wàng le."},{zh:"多带一件衣服，免得晚上冷。",en:"Bring an extra piece of clothing in case it gets cold at night.",py:"Duō dài yí jiàn yīfu, miǎnde wǎnshang lěng."}],exercises:[{kind:"choice",q:"你最好先给他打个电话，___白跑一趟。",instr:"辨析",instrEn:"Pick the right one",body:"你最好先给他打个电话，___白跑一趟。",options:["以便","难免","免得","不免"],answer:2,explain:"“免得”引出想避免的结果；“以便”引出希望达到的目的，“不免、难免”表示不可避免，都不对。",explainEn:"“免得” introduces what you want to avoid; “以便” introduces a goal you want."},{kind:"choice",q:"出门前把窗户关好，免得___。",instr:"完成",instrEn:"Complete the sentence",body:"出门前把窗户关好，免得___。",options:["雨水打进屋里","房间更加凉快","阳光照得进来","屋里能通通风"],answer:0,explain:"“免得”后面是不希望发生的事；其他选项都是人们希望的好结果。",explainEn:"After “免得” comes an unwanted result; the other options are things people want."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["多复习几遍，免得考出好成绩。","路上滑，慢点儿开，免得出事。","你把药放高一点儿，免得孩子拿到。","有话当面说清楚，免得大家误会。"],answer:0,explain:"“免得”后应是不好的结果，“考出好成绩”是好结果；应改为“免得考试时出错”。",explainEn:"“免得” needs a bad result; change to “免得考试时出错”."},{q:"翻译：Lock the door when you leave so that nobody gets in.",a:"走的时候把门锁上，免得有人进来。",instr:"翻译",instrEn:"Translate",body:"Lock the door when you leave so that nobody gets in."}],note:"后面通常是不希望发生的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action 1, miǎnde + bad result = so as not to … / lest …",noteEn:"What follows is usually an unwanted result.",typeEn:"Conjunction"}]},{num:15,title:"山脉上的雕刻",points:[{id:"HSK6.15.1",name:"副词“时而”",pinyin:"shí’ér",type:"副词",explainEn:"Use 时而 to mean “from time to time / sometimes”, often with changing states.",structure:"时而 + A，时而 + B",examples:[{zh:"天气时而晴，时而下雨。",en:"The weather is sunny at times and rainy at times.",py:"Tiānqì shí'ér qíng, shí'ér xià yǔ."},{zh:"他时而认真，时而开玩笑。",en:"Sometimes he is serious, sometimes he jokes.",py:"Tā shí'ér rènzhēn, shí'ér kāi wánxiào."},{zh:"音乐时而轻柔，时而激烈。",en:"The music is sometimes soft and sometimes intense.",py:"Yīnyuè shí'ér qīngróu, shí'ér jīliè."}],exercises:[{kind:"choice",q:"他的情绪很不稳定，时而兴奋，___低落。",instr:"辨析",instrEn:"Pick the right one",body:"他的情绪很不稳定，时而兴奋，___低落。",options:["一会儿","时而","有时","时常"],answer:1,explain:"“时而……时而……”要成对使用，前面用了“时而”，后面也必须用“时而”；“有时、一会儿”各有自己的成对格式，不能混搭。",explainEn:"“时而…时而…” is a fixed pair: once the first half uses 时而, the second must too; 有时/一会儿 pair only with themselves."},{kind:"choice",q:"这条山路时而平坦，时而___。",instr:"完成",instrEn:"Complete the sentence",body:"这条山路时而平坦，时而___。",options:["崎岖难行","平坦好走","平整宽阔","平缓易行"],answer:0,explain:"“时而A，时而B”表示两种不同状态交替出现，B要和A不同；其他三项都和“平坦”意思相同，构不成交替。",explainEn:"“时而A，时而B” alternates two different states, so B must contrast with “flat”; the others all mean flat."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她时而望着窗外，时而低头写字。","远处时而传来几声狗叫。","他昨天时而去了一趟超市。","比赛中我队时而领先，时而落后。"],answer:2,explain:"“时而”表示不时、反复出现，不能用于一次性的动作；应去掉“时而”。",explainEn:"“时而” means “now and then”, not for a single past action; delete it."},{q:"翻译：The road is sometimes wide and sometimes narrow.",a:"这条路时而宽，时而窄。",instr:"翻译",instrEn:"Translate",body:"The road is sometimes wide and sometimes narrow."}],note:"常用于两个或多个状态交替出现，书面感较强。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shí'ér + A, shí'ér + B = now A, now B",noteEn:"Used when two or more states keep alternating; fairly literary.",typeEn:"Adverb"},{id:"HSK6.15.2",name:"副词“不禁”",pinyin:"bùjīn",type:"副词",explainEn:"Use 不禁 to mean “cannot help / involuntarily”.",structure:"不禁 + 动词",examples:[{zh:"看到这张照片，我不禁笑了。",en:"Seeing this photo, I could not help laughing.",py:"Kàndào zhè zhāng zhàopiàn, wǒ bùjīn xiào le."},{zh:"听到这个消息，她不禁流下眼泪。",en:"Hearing the news, she could not help crying.",py:"Tīngdào zhège xiāoxi, tā bùjīn liúxià yǎnlèi."},{zh:"看到家乡的变化，我不禁感到惊讶。",en:"Seeing the changes in my hometown, I could not help feeling surprised.",py:"Kàndào jiāxiāng de biànhuà, wǒ bùjīn gǎndào jīngyà."}],exercises:[{kind:"choice",q:"想起小时候和奶奶在一起的日子，他___哭了起来。",instr:"辨析",instrEn:"Pick the right one",body:"想起小时候和奶奶在一起的日子，他___哭了起来。",options:["以免","未免","不禁","难以"],answer:2,explain:"“不禁”表示控制不住地产生某种反应；“未免”表示评价过分，“以免”表示避免，“难以”表示很难做到，都不合语境。",explainEn:"“不禁” = couldn’t help (doing); the others mean “rather too / so as to avoid / hard to”."},{kind:"choice",q:"听到这个好消息，大家不禁___。",instr:"完成",instrEn:"Complete the sentence",body:"听到这个好消息，大家不禁___。",options:["安排晚会","决定庆祝","商量计划","欢呼起来"],answer:3,explain:"“不禁”后接不由自主的反应，“决定、安排、商量”都是有意识的行为，不能用。",explainEn:"“不禁” goes with spontaneous reactions, not deliberate acts like deciding or planning."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["看到他狼狈的样子，不禁我笑了出来。","想到明天的考试，他不禁紧张起来。","读完这封信，她不禁流下了眼泪。","站在山顶上，我不禁感叹大自然的神奇。"],answer:0,explain:"“不禁”是副词，要放在主语后、动词前；应改为“我不禁笑了出来”。",explainEn:"“不禁” is an adverb and goes after the subject: “我不禁笑了出来”."},{q:"翻译：She could not help crying.",a:"她不禁流下眼泪。",instr:"翻译",instrEn:"Translate",body:"She could not help crying."}],note:"和“不由得”接近，较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùjīn + Verb = can't help … / involuntarily …",noteEn:"Close to 不由得; more formal.",typeEn:"Adverb"},{id:"HSK6.15.3",name:"副词“无不”",pinyin:"wúbù",type:"副词",explainEn:"Use 无不 to mean “without exception / all…”.",structure:"范围 + 无不 + 谓语",examples:[{zh:"听到这个消息，大家无不高兴。",en:"Everyone was happy to hear the news.",py:"Tīngdào zhège xiāoxi, dàjiā wúbù gāoxìng."},{zh:"来过这里的人无不喜欢这里的风景。",en:"Everyone who has been here likes the scenery.",py:"Láiguo zhèlǐ de rén wúbù xǐhuan zhèlǐ de fēngjǐng."},{zh:"观众无不为他的表现鼓掌。",en:"Every audience member applauded his performance.",py:"Guānzhòng wúbù wèi tā de biǎoxiàn gǔzhǎng."}],exercises:[{kind:"choice",q:"参观过故宫的游客，___被它的宏伟所震撼。",instr:"辨析",instrEn:"Pick the right one",body:"参观过故宫的游客，___被它的宏伟所震撼。",options:["无从","无不","无非","不无"],answer:1,explain:"“无不”等于“没有一个不”，强调全都如此；“无非”表示“只不过”，“不无”表示“多少有些”，“无从”表示没有办法。",explainEn:"“无不” = all without exception; “无非” = merely, “不无” = not without, “无从” = no way to."},{kind:"choice",q:"___无不称赞他的勇气。",instr:"完成",instrEn:"Complete the sentence",body:"___无不称赞他的勇气。",options:["在场的人","我的同桌","这位记者","他的母亲"],answer:0,explain:"“无不”前面必须是一个范围、多个对象，单个的人不能说“无不”。",explainEn:"“无不” needs a group as its subject, not one single person."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["村里的人无不知道这个故事。","他写的书无不受到读者欢迎。","听了他的演讲，同学们无不深受感动。","这位老人无不喜欢这个孩子。"],answer:3,explain:"“无不”要求主语是一个范围，“这位老人”只是一个人；应改为“这位老人非常喜欢这个孩子”。",explainEn:"“无不” can’t be used with a single person; say “非常喜欢”."},{q:"翻译：Everyone who tasted this dish praised it.",a:"尝过这道菜的人无不称赞。",instr:"翻译",instrEn:"Translate",body:"Everyone who tasted this dish praised it."}],note:"“无不”相当于“没有一个不……”，书面语常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Scope + wúbù + predicate = all … without exception",noteEn:`无不 means "there is none that doesn't…"; common in writing.`,typeEn:"Adverb"}]},{num:16,title:"徐健和他的野生动物摄影师们",points:[{id:"HSK6.16.1",name:"插入语“换句话说”",pinyin:"huàn jù huà shuō",type:"插入语",explainEn:"Use 换句话说 to restate an idea more clearly: “in other words”.",structure:"前句，换句话说，+ 另一种解释",examples:[{zh:"他没有拒绝，换句话说，他可能同意了。",en:"He did not refuse; in other words, he may have agreed.",py:"Tā méiyǒu jùjué, huàn jù huà shuō, tā kěnéng tóngyì le."},{zh:"成本下降了，换句话说，我们可以卖得更便宜。",en:"Costs fell; in other words, we can sell more cheaply.",py:"Chéngběn xiàjiàng le, huàn jù huà shuō, wǒmen kěyǐ mài de gèng piányi."},{zh:"这个办法风险很小，换句话说，比较安全。",en:"This method has little risk; in other words, it is relatively safe.",py:"Zhège bànfǎ fēngxiǎn hěn xiǎo, huàn jù huà shuō, bǐjiào ānquán."}],exercises:[{kind:"choice",q:"他只完成了一半的工作，___，任务还没有结束。",instr:"辨析",instrEn:"Pick the right one",body:"他只完成了一半的工作，___，任务还没有结束。",options:["相反","话说回来","换句话说","除此之外"],answer:2,explain:"后句是用另一种说法解释前句，用“换句话说”；“相反”要引出相反的情况，“话说回来”表示转折，“除此之外”表示补充别的内容。",explainEn:"The second clause restates the first, so “in other words”; “相反” needs an opposite situation, “话说回来” turns to a contrast, “除此之外” adds something else."},{kind:"choice",q:"这家公司今年的收入还不够支付成本，换句话说，___。",instr:"完成",instrEn:"Complete the sentence",body:"这家公司今年的收入还不够支付成本，换句话说，___。",options:["它的员工非常努力","它今年是亏本的","它明年会扩大规模","它的产品很受欢迎"],answer:1,explain:"“换句话说”后面必须是对前句意思的重新表述；收入不够成本，就是亏本。",explainEn:"After “in other words” you must restate the same idea: income below cost = losing money."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这台机器能自己发现故障，换句话说，基本不需要人看管。","他很聪明，换句话说，他不太努力。","这里四季气温变化不大，换句话说，冬暖夏凉。","他的提议没被通过，换句话说，我们得重新想办法。"],answer:1,explain:"“换句话说”用来换个说法解释前面的意思，不能引出转折；应改为“他很聪明，可是不太努力”。",explainEn:"“换句话说” restates, it can’t introduce a contrast; use “可是”."},{q:"翻译：In other words, it is relatively safe.",a:"换句话说，它比较安全。",instr:"翻译",instrEn:"Translate",body:"In other words, it is relatively safe."}],note:"用于解释、总结或用更容易理解的话重说前面内容。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Previous point, huàn jù huà shuō, + another way of putting it = in other words, …",noteEn:"Used to explain, sum up, or restate the previous point in easier words.",typeEn:"Parenthetical"},{id:"HSK6.16.2",name:"被动句“为……所……”",pinyin:"wéi ... suǒ ...",type:"被动句",explainEn:"Use 为…所… as a formal passive structure: “be…by…”.",structure:"受事 + 为 + 动作者 + 所 + 动词",examples:[{zh:"这个故事为很多人所熟悉。",en:"This story is familiar to many people.",py:"Zhège gùshi wéi hěn duō rén suǒ shúxī."},{zh:"他的作品为读者所喜爱。",en:"His works are loved by readers.",py:"Tā de zuòpǐn wéi dúzhě suǒ xǐ'ài."},{zh:"这种方法已为大家所接受。",en:"This method has been accepted by everyone.",py:"Zhè zhǒng fāngfǎ yǐ wéi dàjiā suǒ jiēshòu."}],exercises:[{kind:"choice",q:"这一观点逐渐为大多数学者___接受。",instr:"辨析",instrEn:"Pick the right one",body:"这一观点逐渐为大多数学者___接受。",options:["就","而","所","被"],answer:2,explain:"“为……所……”是固定的书面被动格式，“为”后接施事，再用“所”引出动词。",explainEn:"The fixed written passive is “为 + doer + 所 + verb”; only “所” completes it."},{kind:"choice",q:"那次失败的教训，至今仍为人们所___。",instr:"完成",instrEn:"Complete the sentence",body:"那次失败的教训，至今仍为人们所___。",options:["铭记","记一记","记住了","记得住"],answer:0,explain:"“所”后面接光杆的双音节动词，不能带“了”、补语或重叠形式。",explainEn:"After “所” use a bare two-syllable verb, with no 了, complement or reduplication."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这一理论已为实验所证实。","这位歌手的名字为年轻人所熟悉。","他的善良为邻居们所称道。","大家为这种方法所接受。"],answer:3,explain:"“为……所……”句的主语是受事，“为”后是施事；应改为“这种方法为大家所接受”。",explainEn:"The subject must be what is acted on: “这种方法为大家所接受”."},{q:"翻译：This book is loved by children all over the world.",a:"这本书为世界各地的孩子所喜爱。",instr:"翻译",instrEn:"Translate",body:"This book is loved by children all over the world."}],note:"非常书面，多用于正式文章。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Receiver + wéi + doer + suǒ + Verb = be …-ed by … (formal passive)",noteEn:"Very formal; mostly in formal writing.",typeEn:"Passive"},{id:"HSK6.16.3",name:"动词“足以”",pinyin:"zúyǐ",type:"动词",explainEn:"Use 足以 to mean “be enough to / be sufficient to”.",structure:"足以 + 动词",examples:[{zh:"这些证据足以说明问题。",en:"This evidence is enough to explain the problem.",py:"Zhèxiē zhèngjù zúyǐ shuōmíng wèntí."},{zh:"一次失败不足以证明你不行。",en:"One failure is not enough to prove you cannot do it.",py:"Yí cì shībài bùzúyǐ zhèngmíng nǐ bù xíng."},{zh:"这段时间足以完成任务。",en:"This amount of time is enough to complete the task.",py:"Zhè duàn shíjiān zúyǐ wánchéng rènwu."}],exercises:[{kind:"choice",q:"一次小小的疏忽，就___造成严重的后果。",instr:"辨析",instrEn:"Pick the right one",body:"一次小小的疏忽，就___造成严重的后果。",options:["得以","足以","予以","以致"],answer:1,explain:"“足以”表示条件足够引起某种结果；“得以”表示因有条件而终于实现好事，“以致”是连词，不能放在“就”后。",explainEn:"“足以” = enough to (cause); “得以” is for a positive result achieved, “以致” is a conjunction."},{kind:"choice",q:"___，足以说明他是真心想帮忙。",instr:"完成",instrEn:"Complete the sentence",body:"___，足以说明他是真心想帮忙。",options:["他说过一句客气话","他偶尔会问候一句","他曾经打听过消息","他连夜赶了三百公里路"],answer:3,explain:"“足以”表示前面的事实分量足够；只有连夜赶三百公里路才足够说明真心，其他都太轻。",explainEn:"“足以” needs strong enough evidence; only driving 300 km overnight is enough."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他的成绩足以说明他下了很大功夫。","这点儿雨还不足以缓解旱情。","这些钱足以一个月的生活费。","仓库里的粮食足以维持半年。"],answer:2,explain:"“足以”后面要接动词，不能直接接名词；应改为“足以支付一个月的生活费”。",explainEn:"“足以” must be followed by a verb: “足以支付一个月的生活费”."},{q:"翻译：His explanation is not enough to convince everyone.",a:"他的解释不足以说服大家。",instr:"翻译",instrEn:"Translate",body:"His explanation is not enough to convince everyone."}],note:"常见“足以/不足以 + 动词”，较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zúyǐ + Verb = be enough to …",noteEn:"Common as 足以 / 不足以 + verb; fairly formal.",typeEn:"Verb"}]},{num:17,title:"小动物眼中的慢世界",points:[{id:"HSK6.17.1",name:"固定格式“东A西B”",pinyin:"dōng A xī B",type:"固定格式",explainEn:"Use 东A西B to mean doing similar actions here and there in different directions.",structure:"东 + 动词A + 西 + 动词B",examples:[{zh:"他在房间里东找西找，还是没找到钥匙。",en:"He searched here and there in the room but still did not find the key.",py:"Tā zài fángjiān li dōng zhǎo xī zhǎo, háishi méi zhǎodào yàoshi."},{zh:"孩子们东跑西跑，一刻也不停。",en:"The children ran here and there without stopping.",py:"Háizimen dōng pǎo xī pǎo, yíkè yě bù tíng."},{zh:"她买东西时总爱东挑西选。",en:"She always picks and chooses when shopping.",py:"Tā mǎi dōngxi shí zǒng ài dōng tiāo xī xuǎn."}],exercises:[{kind:"choice",q:"这篇文章是从网上___出来的，没有一点儿自己的观点。",instr:"辨析",instrEn:"Pick the right one",body:"这篇文章是从网上___出来的，没有一点儿自己的观点。",options:["东张西望","东奔西走","东拼西凑","东倒西歪"],answer:2,explain:"“东拼西凑”指从各处零散地拼凑起来，正合抄文章的语境；“东张西望”是四处看，“东奔西走”是到处奔波，“东倒西歪”是站不稳。",explainEn:"“东拼西凑” = patched together from bits everywhere; the others mean looking around, rushing about, and tottering."},{kind:"choice",q:"他说话总是东一句西一句，___。",instr:"完成",instrEn:"Complete the sentence",body:"他说话总是东一句西一句，___。",options:["逻辑十分严密","条理特别清楚","重点非常突出","让人抓不住重点"],answer:3,explain:"“东一句西一句”表示零散、没有中心，所以后面应是“抓不住重点”，不会条理清楚。",explainEn:"“东一句西一句” means scattered talk, so it goes with “hard to get the point”."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["小狗在院子里东闻西闻，像在找什么。","别东想西想了，早点儿睡吧。","孩子们在草地上东跑东跳，玩得满头大汗。","为了筹钱，他东奔西走了好几个月。"],answer:2,explain:"格式是“东A西B”，后一个应是“西”；应改为“东跑西跳”。",explainEn:"The second half needs 西: “东跑西跳”."},{q:"翻译：The children ran here and there.",a:"孩子们东跑西跑。",instr:"翻译",instrEn:"Translate",body:"The children ran here and there."}],note:"A、B通常意义相近，表达动作反复、方向不定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dōng + Verb A + xī + Verb B = A here, B there (all over the place)",noteEn:"A and B are usually similar in meaning; shows repeated actions in no fixed direction.",typeEn:"Fixed pattern"},{id:"HSK6.17.2",name:"动词“中（zhòng）”",pinyin:"zhòng",type:"动词",explainEn:"中 (zhòng) means “hit / be affected / win”, as in 中奖、中暑、中毒.",structure:"中 + 宾语/固定词",examples:[{zh:"他买了一张彩票，没想到中奖了。",en:"He bought a lottery ticket and unexpectedly won.",py:"Tā mǎile yì zhāng cǎipiào, méi xiǎngdào zhòngjiǎng le."},{zh:"天气太热，小心中暑。",en:"It is very hot; be careful not to get heatstroke.",py:"Tiānqì tài rè, xiǎoxīn zhòngshǔ."},{zh:"这些食物可能让人中毒。",en:"This food may cause poisoning.",py:"Zhèxiē shíwù kěnéng ràng rén zhòngdú."}],exercises:[{kind:"choice",q:"他们一时疏忽，___了对手的圈套。",instr:"辨析",instrEn:"Pick the right one",body:"他们一时疏忽，___了对手的圈套。",options:["落","中","得","受"],answer:1,explain:"“中（zhòng）”表示遭受、正好碰上，固定搭配“中圈套”；“受”“得”不和“圈套”搭配，“落”要说“落入”。",explainEn:"“中 (zhòng) 圈套” = fall into a trap; the other verbs don’t collocate with 圈套 this way."},{kind:"choice",q:"公司年会抽奖，他竟然中了___，高兴得跳了起来。",instr:"完成",instrEn:"Complete the sentence",body:"公司年会抽奖，他竟然中了___，高兴得跳了起来。",options:["一等奖","第一名","满分","冠军"],answer:0,explain:"“中（zhòng）”表示抽中、碰上，只能说“中奖、中了一等奖”；“第一名、满分、冠军”是凭成绩得到的，要说“得了/拿了”。",explainEn:"中 (zhòng) means to win by drawing/luck, as in 中奖 / 中了一等奖; first place, full marks and the championship are earned, so they take 得/拿."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他昨天中了感冒，没来上课。","他第一次买彩票就中了奖。","吃了不干净的东西，他中毒住院了。","这一枪正好打中了目标。"],answer:0,explain:"“中”只用于“中暑、中毒、中奖”等固定搭配，感冒不能说“中”；应改为“他昨天感冒了”。",explainEn:"中 only works in set phrases like 中暑/中毒/中奖; say “他昨天感冒了”."},{q:"翻译：Be careful not to get heatstroke.",a:"小心中暑。",instr:"翻译",instrEn:"Translate",body:"Be careful not to get heatstroke."}],note:"注意读 zhòng，不读 zhōng；常见于固定搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zhòng + object / set word = hit / be struck by / win",noteEn:"Read zhòng, not zhōng; common in set combinations.",typeEn:"Verb"},{id:"HSK6.17.3",name:"副词“姑且”",pinyin:"gūqiě",type:"副词",explainEn:"Use 姑且 to mean “for the time being / tentatively”.",structure:"姑且 + 动词/判断",examples:[{zh:"这个问题我们姑且放一放。",en:"Let us put this issue aside for the time being.",py:"Zhège wèntí wǒmen gūqiě fàng yi fàng."},{zh:"没有更好的办法，就姑且试试这个吧。",en:"Since there is no better way, let us try this for now.",py:"Méiyǒu gèng hǎo de bànfǎ, jiù gūqiě shìshi zhège ba."},{zh:"这件事是真是假，姑且不论。",en:"Whether this is true or false, let us not discuss it for now.",py:"Zhè jiàn shì shì zhēn shì jiǎ, gūqiě bú lùn."}],exercises:[{kind:"choice",q:"你的计划虽然不完美，但我们___按这个做吧，以后再改。",instr:"辨析",instrEn:"Pick the right one",body:"你的计划虽然不完美，但我们___按这个做吧，以后再改。",options:["尚且","况且","并且","姑且"],answer:3,explain:"“姑且”表示暂时先这样做；“尚且”用于递进比较，“况且、并且”是连词，不能放在这里。",explainEn:"“姑且” = for the time being; “尚且” is for “even…”, and 况且/并且 are conjunctions."},{kind:"choice",q:"这家旅馆条件一般，我们姑且住一晚，___。",instr:"完成",instrEn:"Complete the sentence",body:"这家旅馆条件一般，我们姑且住一晚，___。",options:["准备长期住下去","明天再找更好的","打算买下这里","以后每年都来住"],answer:1,explain:"“姑且”表示暂时将就，后面通常说以后再换或再说，不能是长期打算。",explainEn:"“姑且” means a temporary stopgap, so it can’t go with long-term plans."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["没有雨伞，姑且用报纸挡一挡吧。","他的话姑且信一次，看看再说。","这箱书大人姑且搬不动，何况孩子呢？","这件事的对错姑且不说，你的态度就有问题。"],answer:2,explain:"“姑且”表示暂时先这样，不能和“何况”构成递进；应改为“这箱书大人尚且搬不动，何况孩子呢”。",explainEn:"姑且 means “for now”; the “even…let alone” pattern needs 尚且: “大人尚且搬不动，何况孩子呢”."},{q:"翻译：Let us try this for now.",a:"我们姑且试试这个。",instr:"翻译",instrEn:"Translate",body:"Let us try this for now."}],note:"有“暂时先这样”的意思，书面语较常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gūqiě + Verb/judgment = for the time being / tentatively",noteEn:'Means "let it be this way for now"; common in writing.',typeEn:"Adverb"}]},{num:18,title:"神奇的丝瓜",points:[{id:"HSK6.18.1",name:"副词“随即”",pinyin:"suíjí",type:"副词",explainEn:"Use 随即 to mean “immediately afterward / right then”.",structure:"动作1，随即 + 动作2",examples:[{zh:"他看完邮件，随即回复了。",en:"He read the email and replied immediately.",py:"Tā kànwán yóujiàn, suíjí huífù le."},{zh:"会议结束后，大家随即离开。",en:"After the meeting ended, everyone left right away.",py:"Huìyì jiéshù hòu, dàjiā suíjí líkāi."},{zh:"他发现问题，随即采取了措施。",en:"He found the problem and immediately took action.",py:"Tā fāxiàn wèntí, suíjí cǎiqǔle cuòshī."}],exercises:[{kind:"choice",q:"警察接到报警电话，___赶到了现场。",instr:"辨析",instrEn:"Pick the right one",body:"警察接到报警电话，___赶到了现场。",options:["随意","随即","随时","随便"],answer:1,explain:"“随即”表示紧接着前一个动作发生；“随时”指任何时候，“随便、随意”指不加限制，都不合语境。",explainEn:"“随即” = right after that; “随时” = at any time, “随便/随意” = casually."},{kind:"choice",q:"主持人宣布比赛结束，观众随即___。",instr:"完成",instrEn:"Complete the sentence",body:"主持人宣布比赛结束，观众随即___。",options:["三天后才离开","第二年又来看","半天没有反应","起立热烈鼓掌"],answer:3,explain:"“随即”表示马上接着发生，不能和“三天后、第二年、半天没反应”这样隔很久的事连用。",explainEn:"“随即” means immediately after, so it can’t go with a long delay."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你吃完饭随即去写作业吧。","他接过信看了一眼，随即放进了口袋。","灯光暗了下来，音乐随即响起。","大雨过后，天空随即出现了一道彩虹。"],answer:0,explain:"“随即”用于叙述已发生的事，不用于命令、要求；应改为“你吃完饭马上去写作业吧”。",explainEn:"“随即” narrates events and isn’t used in commands; use “马上”."},{q:"翻译：As soon as she put the phone down, she left the office.",a:"她放下电话，随即离开了办公室。",instr:"翻译",instrEn:"Translate",body:"As soon as she put the phone down, she left the office."}],note:"比“马上”更书面，强调前后动作紧接发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action 1, suíjí + Action 2 = then immediately …",noteEn:"More formal than 马上; stresses that the second action follows right after the first.",typeEn:"Adverb"},{id:"HSK6.18.2",name:"副词/能愿结构“宁愿”",pinyin:"nìngyuàn",type:"副词/能愿用法",explainEn:"Use 宁愿 to mean “would rather / prefer to”.",structure:"宁愿 + A，也不/也要 + B",examples:[{zh:"我宁愿走路，也不坐这么挤的车。",en:"I would rather walk than take such a crowded bus.",py:"Wǒ nìngyuàn zǒulù, yě bú zuò zhème jǐ de chē."},{zh:"他宁愿多花时间，也要把事情做好。",en:"He would rather spend more time to do the job well.",py:"Tā nìngyuàn duō huā shíjiān, yě yào bǎ shìqing zuòhǎo."},{zh:"我宁愿自己做，也不麻烦别人。",en:"I would rather do it myself than trouble others.",py:"Wǒ nìngyuàn zìjǐ zuò, yě bù máfan biéren."}],exercises:[{kind:"choice",q:"他___饿着肚子，也不愿意吃别人剩下的饭。",instr:"辨析",instrEn:"Pick the right one",body:"他___饿着肚子，也不愿意吃别人剩下的饭。",options:["何况","与其","宁愿","不如"],answer:2,explain:"“宁愿A，也不B”表示两害相权后的选择；“与其”要和“不如”配对，“何况”“不如”都不能和“也不”搭配。",explainEn:"“宁愿…也不…” = would rather…than; “与其” pairs with “不如”, not “也不”."},{kind:"choice",q:"我宁愿少睡一会儿，___。",instr:"完成",instrEn:"Complete the sentence",body:"我宁愿少睡一会儿，___。",options:["但是今天报告没写完","也要今天把报告写完","所以今天报告写完了","而且今天报告写完了"],answer:1,explain:"“宁愿A，也要B”表示为了做到B，宁可付出A的代价；“但是、所以、而且”都不能和“宁愿”呼应。",explainEn:"“宁愿A，也要B” = I’d rather pay A in order to do B; 但是/所以/而且 can’t complete 宁愿."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他宁愿自己吃亏，也不让朋友为难。","我宁愿少挣点儿钱，也要多陪陪家人。","她宁愿走着去，也不打车。","他宁愿熬夜，还不肯把工作留到明天。"],answer:3,explain:"“宁愿”应和“也”呼应，不能用“还”；应改为“也不肯把工作留到明天”。",explainEn:"“宁愿” pairs with “也”, not “还”: “也不肯…”."},{q:"翻译：I would rather get up early than be late.",a:"我宁愿早点儿起床，也不想迟到。",instr:"翻译",instrEn:"Translate",body:"I would rather get up early than be late."}],note:"常和“也不、也要”搭配，表达主动选择。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nìngyuàn + A, yě bù/yě yào + B = would rather A than B / would rather A to get B",noteEn:"Often paired with 也不 / 也要 to express a deliberate choice.",typeEn:"Adverb / Modal use"},{id:"HSK6.18.3",name:"让步格式“A归A”",pinyin:"A guī A",type:"让步结构",explainEn:"Use A归A to admit one fact, then add another different point: “A is A, but…”.",structure:"A + 归 + A，(但/可是) + B",examples:[{zh:"贵归贵，质量确实不错。",en:"It is expensive, but the quality is really good.",py:"Guì guī guì, zhìliàng quèshí búcuò."},{zh:"忙归忙，他每天还是会运动。",en:"Busy as he is, he still exercises every day.",py:"Máng guī máng, tā měi tiān háishi huì yùndòng."},{zh:"喜欢归喜欢，我不会买这么贵的。",en:"I like it, but I will not buy something this expensive.",py:"Xǐhuan guī xǐhuan, wǒ bú huì mǎi zhème guì de."}],exercises:[{kind:"choice",q:"说___说，他还是没有动手去做。",instr:"辨析",instrEn:"Pick the right one",body:"说___说，他还是没有动手去做。",options:["还","也","归","就"],answer:2,explain:"“A归A”先承认一个事实，再转折说明另一情况；“说就说”是表示无所谓，不能接转折。",explainEn:"“A归A” concedes a fact before a contrast; “说就说” means “so what, say it”."},{kind:"choice",q:"朋友归朋友，___。",instr:"完成",instrEn:"Complete the sentence",body:"朋友归朋友，___。",options:["账还是要算清楚","所以账就不用算了","账当然可以不算","因此我们不计较"],answer:0,explain:"“A归A”先承认A，后面要转折，说明A不影响另一判断；把它当成“因为是朋友，所以不算账”是常见误解。",explainEn:"“A归A” concedes A and then contrasts; it doesn’t mean “since we’re friends, so…”."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["好吃归好吃，所以我又点了一份。","便宜归便宜，这东西质量不行。","说归说，真做起来可不容易。","批评归批评，他心里还是关心你的。"],answer:0,explain:"“A归A”后面应是转折，不能用“所以”顺接；可改为“好吃归好吃，我可不能再吃了”。",explainEn:"“A归A” must be followed by a contrast, not 所以; e.g. “好吃归好吃，我可不能再吃了”."},{q:"翻译：Busy as he is, he still exercises.",a:"忙归忙，他还是会运动。",instr:"翻译",instrEn:"Translate",body:"Busy as he is, he still exercises."}],note:"前面承认一个事实，后面说明这个事实并不影响另一判断。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + guī + A, (dàn/kěshì) + B = A is A, but B",noteEn:"Admits one fact first, then says it doesn't change another judgment.",typeEn:"Concessive structure"}]},{num:19,title:"无阳光的深海世界",points:[{id:"HSK6.19.1",name:"连词“进而”",pinyin:"jìn’ér",type:"连词",explainEn:"Use 进而 to mean “and then / further”, showing a deeper next step.",structure:"A，进而 + 更进一步的B",examples:[{zh:"先了解问题，进而寻找解决办法。",en:"First understand the problem, then go further to find a solution.",py:"Xiān liǎojiě wèntí, jìn'ér xúnzhǎo jiějué bànfǎ."},{zh:"技术不断进步，进而改变了生活方式。",en:"Technology keeps improving and further changes lifestyles.",py:"Jìshù búduàn jìnbù, jìn'ér gǎibiànle shēnghuó fāngshì."},{zh:"学习语言可以了解文化，进而理解一个社会。",en:"Learning a language can help you understand culture and then society.",py:"Xuéxí yǔyán kěyǐ liǎojiě wénhuà, jìn'ér lǐjiě yí ge shèhuì."}],exercises:[{kind:"choice",q:"我们先在一个城市试点，取得经验后___推广到全国。",instr:"辨析",instrEn:"Pick the right one",body:"我们先在一个城市试点，取得经验后___推广到全国。",options:["反而","因而","然而","进而"],answer:3,explain:"“进而”表示在前一步的基础上再进一步；“反而、然而”表示转折，“因而”表示结果，都不合语境。",explainEn:"“进而” = then go a step further; “反而/然而” are contrastive, “因而” marks a result."},{kind:"choice",q:"他先是对中国书法产生了兴趣，进而___。",instr:"完成",instrEn:"Complete the sentence",body:"他先是对中国书法产生了兴趣，进而___。",options:["再也不想练字了","开始研究传统文化","把毛笔都扔掉了","觉得书法很无聊"],answer:1,explain:"“进而”后面是更进一步、方向一致的发展，不能是相反的变化。",explainEn:"After “进而” comes a further step in the same direction, not a reversal."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["读者先认识作者，进而喜欢上他的作品。","两国先恢复了贸易，进而开展文化交流。","他学了三年钢琴，进而放弃了。","降低成本可以提高利润，进而扩大生产。"],answer:2,explain:"“进而”表示进一步发展，放弃是相反的结果；应改为“他学了三年钢琴，后来却放弃了”。",explainEn:"Giving up isn’t a further step; use “后来却放弃了”."},{q:"翻译：Technology improved and further changed life.",a:"技术进步，进而改变了生活。",instr:"翻译",instrEn:"Translate",body:"Technology improved and further changed life."}],note:"强调在前一步基础上进一步发展。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A, jìn'ér + a further B = and then, going further, B",noteEn:"Stresses a further step built on the previous one.",typeEn:"Conjunction"},{id:"HSK6.19.2",name:"动词“得以”",pinyin:"déyǐ",type:"动词",explainEn:"Use 得以 before a verb to mean “be able to / get the chance to”, usually because conditions allow it.",structure:"得以 + 动词",examples:[{zh:"问题终于得以解决。",en:"The problem was finally able to be solved.",py:"Wèntí zhōngyú déyǐ jiějué."},{zh:"在大家帮助下，项目得以顺利完成。",en:"With everyone's help, the project was completed successfully.",py:"Zài dàjiā bāngzhù xià, xiàngmù déyǐ shùnlì wánchéng."},{zh:"新技术让更多人得以接受教育。",en:"New technology enables more people to receive education.",py:"Xīn jìshù ràng gèng duō rén déyǐ jiēshòu jiàoyù."}],exercises:[{kind:"choice",q:"由于资金及时到位，这项研究___继续进行。",instr:"辨析",instrEn:"Pick the right one",body:"由于资金及时到位，这项研究___继续进行。",options:["得以","难以","足以","予以"],answer:0,explain:"“得以”表示因为有了条件而能够实现；“难以”意思相反，“足以”的主语应是条件本身，“予以”后接给予的对象。",explainEn:"“得以” = was able to, thanks to the conditions; “难以” is the opposite, “足以” needs the cause as subject."},{kind:"choice",q:"___，这座古桥才得以保存下来。",instr:"完成",instrEn:"Complete the sentence",body:"___，这座古桥才得以保存下来。",options:["因为经常遭到破坏","多亏村民们多年的保护","由于多年无人管理","尽管村民努力保护"],answer:1,explain:"“得以”前面是使好结果成为可能的条件，所以要用“多亏……”；“尽管”不能和“才”配合。",explainEn:"“得以” needs an enabling condition before it, like “thanks to the villagers”."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["在医生的努力下，病人的生命得以挽救。","有了这笔奖学金，他得以完成学业。","通过这次调整，交通拥堵问题得以缓解。","因为他的疏忽，公司得以损失了一大笔钱。"],answer:3,explain:"“得以”用于有条件实现的好结果，不能用于损失；应改为“公司损失了一大笔钱”。",explainEn:"“得以” is for positive outcomes, not losses; delete it."},{q:"翻译：Thanks to the volunteers, the old library was able to reopen.",a:"在志愿者的帮助下，老图书馆得以重新开放。",instr:"翻译",instrEn:"Translate",body:"Thanks to the volunteers, the old library was able to reopen."}],note:"较正式，常用于积极结果或机会获得。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"déyǐ + Verb = be able to … (thanks to conditions)",noteEn:"Fairly formal; usually for a positive result or a chance gained.",typeEn:"Verb"},{id:"HSK6.19.3",name:"副词“偏偏”",pinyin:"piānpiān",type:"副词",explainEn:"Use 偏偏 when reality goes against expectation or desire: “just / unfortunately / contrary to expectation”.",structure:"想/希望A，偏偏 + B",examples:[{zh:"我最忙的时候，他偏偏来找我。",en:"He came to see me at exactly the time I was busiest.",py:"Wǒ zuì máng de shíhou, tā piānpiān lái zhǎo wǒ."},{zh:"大家都同意，偏偏他反对。",en:"Everyone agreed, but he alone objected.",py:"Dàjiā dōu tóngyì, piānpiān tā fǎnduì."},{zh:"今天想早点儿回家，偏偏下起了大雨。",en:"I wanted to go home early, but it just started pouring.",py:"Jīntiān xiǎng zǎo diǎnr huíjiā, piānpiān xiàqǐle dàyǔ."}],exercises:[{kind:"choice",q:"大家都劝他别去，他___要去。",instr:"辨析",instrEn:"Pick the right one",body:"大家都劝他别去，他___要去。",options:["恰好","幸亏","偏偏","总算"],answer:2,explain:"“偏偏”表示故意跟别人的意愿相反；“恰好”是碰巧，“总算”“幸亏”表示庆幸，都不合语境。",explainEn:"“偏偏” = insist on doing the opposite; “恰好” = happen to, “总算/幸亏” = luckily."},{kind:"choice",q:"我今天特意早起想去看日出，偏偏___。",instr:"完成",instrEn:"Complete the sentence",body:"我今天特意早起想去看日出，偏偏___。",options:["天阴得什么也看不见","天气晴得特别好","风景比想象中漂亮","太阳升得特别美"],answer:0,explain:"“偏偏”引出和愿望相反、令人无奈的情况，不能是如愿的好结果。",explainEn:"“偏偏” introduces something against your wish, not a happy outcome."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["别的菜都好吃，偏偏这道太咸了。","我正想喝水，他偏偏给我倒了一杯水。","我急着赶车，公交车偏偏迟迟不来。","那么多人都可以去，为什么偏偏派我去？"],answer:1,explain:"“偏偏”表示与愿望相反，正合心意应该用“正好”；应改为“他正好给我倒了一杯水”。",explainEn:"When it matches your wish, use “正好”, not “偏偏”."},{q:"翻译：I wanted to sleep in today, but the neighbors just had to start renovating early in the morning.",a:"今天我想睡个懒觉，偏偏邻居一大早就开始装修。",instr:"翻译",instrEn:"Translate",body:"I wanted to sleep in today, but the neighbors just had to start renovating early in the morning."}],note:"常带无奈、不满或出乎意料的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xiǎng/xīwàng A, piānpiān + B = wanted A, but B just had to happen",noteEn:"Often carries helplessness, annoyance, or surprise.",typeEn:"Adverb"}]},{num:20,title:"金鸡窝",points:[{id:"HSK6.20.1",name:"连词“况且”",pinyin:"kuàngqiě",type:"连词",explainEn:"Use 况且 to add a stronger supporting reason: “besides / moreover”.",structure:"理由1，况且 + 理由2",examples:[{zh:"今天太晚了，况且外面还下雨，别出去了。",en:"It is late, and besides, it is raining; do not go out.",py:"Jīntiān tài wǎn le, kuàngqiě wàimiàn hái xià yǔ, bié chūqu le."},{zh:"这件事不急，况且我们还需要更多信息。",en:"This matter is not urgent; moreover, we need more information.",py:"Zhè jiàn shì bù jí, kuàngqiě wǒmen hái xūyào gèng duō xìnxī."},{zh:"他经验丰富，况且准备得很充分，应该没问题。",en:"He is experienced, and besides, he is well prepared, so it should be fine.",py:"Tā jīngyàn fēngfù, kuàngqiě zhǔnbèi de hěn chōngfèn, yīnggāi méi wèntí."}],exercises:[{kind:"choice",q:"这家餐厅太远了，___价格也不便宜，我们换一家吧。",instr:"辨析",instrEn:"Pick the right one",body:"这家餐厅太远了，___价格也不便宜，我们换一家吧。",options:["不过","并非","尚且","况且"],answer:3,explain:"“况且”引出进一步的理由，和前一个理由方向一致；“不过”表示转折，“尚且”“并非”不能连接两个理由。",explainEn:"“况且” adds another reason in the same direction; “不过” would mark a contrast."},{kind:"choice",q:"这份工作我不打算接受，工资太低，况且___。",instr:"完成",instrEn:"Complete the sentence",body:"这份工作我不打算接受，工资太低，况且___。",options:["发展前景很不错","同事们都很友好","离我家也很远","工作时间很灵活"],answer:2,explain:"“况且”补充的理由要支持同一结论（不接受），其他选项都是接受的理由。",explainEn:"“况且” must add a reason for the same conclusion; the others argue the opposite."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个房子很漂亮，况且价格太贵了，我不买。","你身体不好，况且天又这么冷，就别出门了。","他年纪还小，况且又是第一次犯错，原谅他吧。","时间来不及了，况且我们也没有准备好。"],answer:0,explain:"“况且”前后理由应方向一致，这里是转折；应改为“这个房子很漂亮，可是价格太贵了”。",explainEn:"Here the clauses contrast, so use “可是”, not “况且”."},{q:"翻译：Moreover, we need more information.",a:"况且我们还需要更多信息。",instr:"翻译",instrEn:"Translate",body:"Moreover, we need more information."}],note:"常用于第二个理由，使论证更充分。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Reason 1, kuàngqiě + Reason 2 = besides / moreover",noteEn:"Usually introduces a second reason, making the argument stronger.",typeEn:"Conjunction"},{id:"HSK6.20.2",name:"“大 + 时间词”表示特殊时段",pinyin:"dà + shíjiāncí",type:"时间表达",explainEn:"Use 大 + a time word in fixed expressions to strongly mark an unusual time, such as 大清早、大白天、大半夜.",structure:"大清早 / 大白天 / 大半夜",examples:[{zh:"大清早他就出门了。",en:"He went out very early in the morning.",py:"Dà qīngzǎo tā jiù chūmén le."},{zh:"大白天的，你怕什么？",en:"It is broad daylight; what are you afraid of?",py:"Dà báitiān de, nǐ pà shénme?"},{zh:"大半夜别给别人打电话。",en:"Do not call people in the middle of the night.",py:"Dà bànyè bié gěi biéren dǎ diànhuà."}],exercises:[{kind:"choice",q:"天刚蒙蒙亮，你怎么___就来敲门？",instr:"辨析",instrEn:"Pick the right one",body:"天刚蒙蒙亮，你怎么___就来敲门？",options:["大白天","大清早","大半夜","大晚上"],answer:1,explain:"天刚亮是清早，“大清早”带有嫌太早、不满的语气；“大白天、大半夜、大晚上”说的时间都和“天刚亮”不符。",explainEn:"Just after dawn is 大清早, said with annoyance; 大白天/大半夜/大晚上 name the wrong time of day."},{kind:"choice",q:"大半夜的，楼上___。",instr:"完成",instrEn:"Complete the sentence",body:"大半夜的，楼上___。",options:["灯全部关了","大家都睡了","已经安静下来","还在大声唱歌"],answer:3,explain:"“大半夜的”常带不满或惊讶，后面应是不该在这时发生的事；半夜安静、睡觉是正常的。",explainEn:"“大半夜的” signals complaint, so it goes with something that shouldn’t happen at that hour."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["大热天的，别在太阳底下站着。","大冬天的，他只穿了一件衬衫。","大明天我们一起去爬山吧。","大清早的，谁在外面吵？"],answer:2,explain:"“大”只和“清早、白天、半夜、冬天”等少数时间词固定搭配，不能说“大明天”；应改为“明天我们一起去爬山吧”。",explainEn:"Only set time words take 大; “大明天” doesn’t exist."},{q:"翻译：It's the middle of the night—why are you still playing games?",a:"大半夜的，你怎么还在玩游戏？",instr:"翻译",instrEn:"Translate",body:"It's the middle of the night—why are you still playing games?"}],note:"多为固定搭配，常带强调、惊讶或不满。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dà qīngzǎo / dà báitiān / dà bànyè = so early in the morning / in broad daylight / in the dead of night",noteEn:"Mostly set combinations; often adds emphasis, surprise or annoyance.",typeEn:"Time"},{id:"HSK6.20.3",name:"选择格式“与其……倒不如……”",pinyin:"yǔqí ... dào bùrú ...",type:"选择复句",explainEn:"Use 与其…倒不如… to mean “rather than…, it would be better to…”.",structure:"与其 + A，倒不如 + B",examples:[{zh:"与其一直担心，倒不如马上行动。",en:"Rather than keep worrying, it is better to act now.",py:"Yǔqí yìzhí dānxīn, dào bùrú mǎshàng xíngdòng."},{zh:"与其开车堵在路上，倒不如坐地铁。",en:"Rather than get stuck driving, it is better to take the subway.",py:"Yǔqí kāichē dǔ zài lù shang, dào bùrú zuò dìtiě."},{zh:"与其勉强答应，倒不如直接说明。",en:"Rather than agree unwillingly, it is better to explain directly.",py:"Yǔqí miǎnqiǎng dāying, dào bùrú zhíjiē shuōmíng."}],exercises:[{kind:"choice",q:"与其在这儿抱怨，___想想怎么解决问题。",instr:"辨析",instrEn:"Pick the right one",body:"与其在这儿抱怨，___想想怎么解决问题。",options:["何况","倒不如","也不","并且"],answer:1,explain:"“与其A，倒不如B”表示B比A好；“何况”“也不”“并且”都不能和“与其”呼应。",explainEn:"与其A，倒不如B means B is better than A; 何况, 也不 and 并且 can't complete 与其."},{kind:"choice",q:"与其花大价钱修这台旧电脑，倒不如___。",instr:"完成",instrEn:"Complete the sentence",body:"与其花大价钱修这台旧电脑，倒不如___。",options:["直接买一台新的","请更贵的师傅修","去更贵的店里修","再花钱多修几次"],answer:0,explain:"“倒不如”后面是比前者更好的另一种选择，其他选项还是花钱修，比前者更差。",explainEn:"After “倒不如” comes a better alternative; the others are just costlier repairs."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["与其等别人来帮忙，倒不如自己动手。","与其一个人生闷气，倒不如把话说出来。","与其在家闲着，倒不如出去找份工作。","倒不如直接问老师，与其自己在这里瞎猜。"],answer:3,explain:"顺序必须是“与其A，倒不如B”，不能把“与其”分句放后面；应改为“与其自己在这里瞎猜，倒不如直接问老师”。",explainEn:"The order must be “与其A，倒不如B”; put the 与其 clause first."},{q:"翻译：Rather than drive, it is better to take the subway.",a:"与其开车，倒不如坐地铁。",instr:"翻译",instrEn:"Translate",body:"Rather than drive, it is better to take the subway."}],note:"“倒不如”比“不如”更有“反而选择这个更好”的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǔqí + A, dào bùrú + B = rather than A, it'd be better to B",noteEn:'倒不如 adds more of a "better to choose this instead" tone than 不如.',typeEn:"Alternative clause"}]},{num:21,title:"未来商店",points:[{id:"HSK6.21.1",name:"连词“以免”",pinyin:"yǐmiǎn",type:"目的连词",explainEn:"Use 以免 to mean “so as to avoid / lest”, usually before an unwanted result.",structure:"动作/措施 + 以免 + 不好的结果",examples:[{zh:"请提前出发，以免迟到。",en:"Please leave early so as not to be late.",py:"Qǐng tíqián chūfā, yǐmiǎn chídào."},{zh:"重要文件要备份，以免丢失。",en:"Back up important files to avoid losing them.",py:"Zhòngyào wénjiàn yào bèifèn, yǐmiǎn diūshī."},{zh:"出门带把伞，以免下雨。",en:"Take an umbrella in case it rains.",py:"Chūmén dài bǎ sǎn, yǐmiǎn xià yǔ."}],exercises:[{kind:"choice",q:"药品要放在孩子拿不到的地方，___发生意外。",instr:"辨析",instrEn:"Pick the right one",body:"药品要放在孩子拿不到的地方，___发生意外。",options:["以至","以便","以免","以致"],answer:2,explain:"“以免”引出要避免的结果；“以便”引出希望达到的目的，“以致”“以至”表示已经造成的结果。",explainEn:"“以免” = so as to avoid; “以便” = in order to, “以致/以至” = resulting in."},{kind:"choice",q:"开车时请系好安全带，以免___。",instr:"完成",instrEn:"Complete the sentence",body:"开车时请系好安全带，以免___。",options:["坐得更加舒服","看得更加清楚","开得更加平稳","紧急刹车时受伤"],answer:3,explain:"“以免”后面应是要防止的不好结果，其他都是好结果。",explainEn:"“以免” must be followed by a bad result to prevent."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["离开房间时请关好门窗，以免发生盗窃。","请大家认真复习，以免顺利通过考试。","文件请及时保存，以免数据丢失。","说话要注意分寸，以免引起误会。"],answer:1,explain:"“以免”后要接不希望发生的事；应改为“以便顺利通过考试”或“以免考试不及格”。",explainEn:"After “以免” comes something unwanted; use “以便顺利通过考试”."},{q:"翻译：Please speak quietly in the library so as not to disturb others.",a:"在图书馆请小声说话，以免打扰别人。",instr:"翻译",instrEn:"Translate",body:"Please speak quietly in the library so as not to disturb others."}],note:"较书面；和“免得”接近，常用于提醒和说明预防措施。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action / measure + yǐmiǎn + bad result = so as to avoid …",noteEn:"Fairly formal; close to 免得; used in reminders and to explain precautions.",typeEn:"Purpose conjunction"},{id:"HSK6.21.2",name:"动词“嫌”引出评价",pinyin:"xián",type:"兼语/动词",explainEn:"Use 嫌 to mean “dislike / think something is too…”.",structure:"嫌 + 名词 + 形容词/小句；嫌 + 形容词",examples:[{zh:"我嫌这个房间太小。",en:"I think this room is too small.",py:"Wǒ xián zhège fángjiān tài xiǎo."},{zh:"他嫌路远，不想去。",en:"He thinks the road is too far and does not want to go.",py:"Tā xián lù yuǎn, bù xiǎng qù."},{zh:"别嫌麻烦，再检查一遍。",en:"Do not think it is too troublesome; check it again.",py:"Bié xián máfan, zài jiǎnchá yí biàn."}],exercises:[{kind:"choice",q:"她___这件衣服颜色太老气，一直没穿过。",instr:"辨析",instrEn:"Pick the right one",body:"她___这件衣服颜色太老气，一直没穿过。",options:["嫌","怪","恨","怨"],answer:0,explain:"“嫌 + 宾语 + 形容词”表示对宾语的某方面不满意；“怪、怨”是责备人，“恨”程度太重，都不这样用。",explainEn:"“嫌 + thing + adj” = dislike it for being…; 怪/怨 blame people, 恨 is hate."},{kind:"choice",q:"他嫌这家饭馆___，再也没去过。",instr:"完成",instrEn:"Complete the sentence",body:"他嫌这家饭馆___，再也没去过。",options:["菜量很足","环境干净","服务太慢","价格公道"],answer:2,explain:"“嫌”表示不满，后面应是负面评价，其他选项都是优点。",explainEn:"“嫌” expresses dissatisfaction, so a negative point must follow."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["老板嫌他经验不够，没有录用他。","别嫌路远，那家店真的值得去。","她总嫌我说话太直。","我嫌这个房子很宽敞，所以租下了它。"],answer:3,explain:"“嫌”后面应是不满意的地方，“宽敞”是优点；应改为“我觉得这个房子很宽敞”。",explainEn:"“嫌” needs a negative quality; say “我觉得…很宽敞”."},{q:"翻译：He thinks the road is too far.",a:"他嫌路远。",instr:"翻译",instrEn:"Translate",body:"He thinks the road is too far."}],note:"“嫌 + 宾语 + 形容词”中，宾语也是后面状态的主体。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xián + Noun + Adj/Clause; xián + Adj = find (sb/sth) too … / dislike that …",noteEn:"In 嫌 + object + adjective, the object is also the one who has that state.",typeEn:"Pivot verb"}]},{num:22,title:"2050年的汽车什么样",points:[{id:"HSK6.22.1",name:"固定用法“动不动”",pinyin:"dòngbudòng",type:"固定用法",explainEn:"Use 动不动 to mean “at the slightest thing / often and easily”.",structure:"动不动 + 就 + 动词",examples:[{zh:"他动不动就生气。",en:"He gets angry at the slightest thing.",py:"Tā dòngbudòng jiù shēngqì."},{zh:"这台旧电脑动不动就死机。",en:"This old computer crashes all the time.",py:"Zhè tái jiù diànnǎo dòngbudòng jiù sǐjī."},{zh:"孩子动不动就说不想上学。",en:"The child often says he does not want to go to school.",py:"Háizi dòngbudòng jiù shuō bù xiǎng shàngxué."}],exercises:[{kind:"choice",q:"这孩子身体弱，___就感冒发烧。",instr:"辨析",instrEn:"Pick the right one",body:"这孩子身体弱，___就感冒发烧。",options:["动不动","总算","一向","好不容易"],answer:0,explain:"“动不动就”表示很容易、很频繁地发生（多为不好的事）；“好不容易、总算”表示经过努力才实现，“一向”不和“就”这样搭配。",explainEn:"“动不动就” = at the slightest thing; the others mean “finally” or “always” and don’t fit."},{kind:"choice",q:"现在有些年轻人动不动就___，一点儿压力都受不了。",instr:"完成",instrEn:"Complete the sentence",body:"现在有些年轻人动不动就___，一点儿压力都受不了。",options:["主动承担","认真反思","辞职不干","坚持到底"],answer:2,explain:"“动不动就”带负面评价，后面是不好的、太轻易发生的行为。",explainEn:"“动不动就” criticizes something done too easily, so it needs a negative action."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他动不动就拿辞职来威胁老板。","他动不动就帮助别人，大家都很感动。","这条路动不动就堵车。","你别动不动就发脾气。"],answer:1,explain:"“动不动就”常带不满，不用于称赞的行为；应改为“他经常帮助别人”。",explainEn:"“动不动就” is critical, not for praise; use “经常”."},{q:"翻译：My little brother cries at the slightest thing.",a:"我弟弟动不动就哭。",instr:"翻译",instrEn:"Translate",body:"My little brother cries at the slightest thing."}],note:"常带负面评价，表示某事太容易或太频繁发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dòngbudòng + jiù + Verb = at the slightest thing …",noteEn:"Often negative; says something happens too easily or too often.",typeEn:"Set usage"},{id:"HSK6.22.2",name:"列举用“甲乙丙丁……”",pinyin:"jiǎ yǐ bǐng dīng ...",type:"列举/代称",explainEn:"Use 甲、乙、丙、丁 as neutral labels like A, B, C, D when listing people, plans, groups, etc.",structure:"甲、乙、丙、丁……",examples:[{zh:"我们把方案分成甲、乙、丙三种。",en:"We divide the plans into A, B, and C.",py:"Wǒmen bǎ fāng'àn fēnchéng jiǎ, yǐ, bǐng sān zhǒng."},{zh:"甲方负责提供材料，乙方负责施工。",en:"Party A provides the materials; Party B handles construction.",py:"Jiǎfāng fùzé tígōng cáiliào, yǐfāng fùzé shīgōng."},{zh:"比赛分甲、乙两个小组。",en:"The competition is divided into Group A and Group B.",py:"Bǐsài fēn jiǎ, yǐ liǎng ge xiǎozǔ."}],exercises:[{kind:"choice",q:"这支球队今年从乙级联赛升入了___级联赛，球迷们都很兴奋。",instr:"辨析",instrEn:"Pick the right one",body:"这支球队今年从乙级联赛升入了___级联赛，球迷们都很兴奋。",options:["甲","丙","丁","戊"],answer:0,explain:"用“甲乙丙丁”分等级时，“甲”最高；从乙级“升入”只能是更高的甲级，“丙、丁、戊”都比乙级低。",explainEn:"In 甲乙丙丁 rankings 甲 is the top, so moving up from 乙 can only mean 甲; the others are lower."},{kind:"choice",q:"考试成绩分甲、乙、丙、丁四等，他得了丁等，说明他的成绩___。",instr:"完成",instrEn:"Complete the sentence",body:"考试成绩分甲、乙、丙、丁四等，他得了丁等，说明他的成绩___。",options:["是最好的一等","排在第二等","正好在中间","排在最后一等"],answer:3,explain:"“甲、乙、丙、丁”按顺序排列，四等中“丁”排在最后，所以是最后一等。",explainEn:"甲, 乙, 丙, 丁 go in order, so out of four grades 丁 is the last."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["本次比赛共分甲、乙、丙、丁四个组。","合同一式两份，甲乙双方各执一份。","这些产品按质量分为甲、乙、丁三级。","请从甲、乙两个方案中选出一个。"],answer:2,explain:"列举要按顺序，不能跳过“丙”；应改为“甲、乙、丙三级”。",explainEn:"The list must go in order without skipping: “甲、乙、丙”."},{q:"翻译：The plans are divided into A, B, and C.",a:"方案分成甲、乙、丙三种。",instr:"翻译",instrEn:"Translate",body:"The plans are divided into A, B, and C."}],note:"多用于编号、合同、比赛分组或抽象列举。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiǎ, yǐ, bǐng, dīng … = A, B, C, D … (as labels)",noteEn:"Used for numbering, contracts, competition groups, or abstract lists.",typeEn:"Listing labels"}]},{num:23,title:"大数据时代",points:[{id:"HSK6.23.1",name:"形式动词“加以”",pinyin:"jiāyǐ",type:"形式动词",explainEn:"Use 加以 before a two-syllable verb to mean “carry out / give…to”, in formal writing.",structure:"加以 + 双音节动词",examples:[{zh:"这个问题需要加以解决。",en:"This problem needs to be solved.",py:"Zhège wèntí xūyào jiāyǐ jiějué."},{zh:"我们会认真研究并加以改进。",en:"We will study it carefully and improve it.",py:"Wǒmen huì rènzhēn yánjiū bìng jiāyǐ gǎijìn."},{zh:"这些文化遗产应该加以保护。",en:"These cultural heritage sites should be protected.",py:"Zhèxiē wénhuà yíchǎn yīnggāi jiāyǐ bǎohù."}],exercises:[{kind:"choice",q:"对于群众反映的问题，有关部门应该认真___研究。",instr:"辨析",instrEn:"Pick the right one",body:"对于群众反映的问题，有关部门应该认真___研究。",options:["加以","加上","加入","给以"],answer:0,explain:"“加以 + 双音节动词”表示对前面的问题进行某种处理；“给以”后接“帮助、支持”等名词性宾语，“加上、加入”不能带“研究”。",explainEn:"“加以 + verb” = to apply (study) to something; 给以 takes help/support-type objects, and 加上/加入 can’t take 研究."},{kind:"choice",q:"对于这些新出现的情况，我们必须及时加以___。",instr:"完成",instrEn:"Complete the sentence",body:"对于这些新出现的情况，我们必须及时加以___。",options:["处理","处理一下","处理了","处理它们"],answer:0,explain:"“加以”后面只接光杆双音节动词，不带宾语、“一下”或“了”，处理的对象放在前面。",explainEn:"“加以” takes a bare two-syllable verb, no object, 一下 or 了."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他的经验很有价值，值得加以推广。","对不合理的规定应当加以修改。","我们要加以保护这些古建筑。","这些数据需要进一步加以分析。"],answer:2,explain:"“加以”后的动词不能再带宾语，对象要提前；应改为“对这些古建筑要加以保护”。",explainEn:"The object can’t follow; move it forward: “对这些古建筑要加以保护”."},{q:"翻译：The teacher explained the difficult points of the text in detail.",a:"老师对课文中的难点加以详细说明。",instr:"翻译",instrEn:"Translate",body:"The teacher explained the difficult points of the text in detail."}],note:"后面多接双音节动词，如“说明、分析、保护、处理、改进”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiāyǐ + two-syllable Verb = give … / carry out … (formal)",noteEn:"Usually followed by a two-syllable verb such as 说明, 分析, 保护, 处理, 改进.",typeEn:"Dummy verb"},{id:"HSK6.23.2",name:"重叠形式“大大、远远”",pinyin:"dàdà, yuǎnyuǎn",type:"程度副词",explainEn:"Use 大大 or 远远 before a verb/adjective to strongly increase degree or difference.",structure:"大大 + 提高/降低/超过；远远 + 高于/低于/超过",examples:[{zh:"这个办法大大提高了效率。",en:"This method greatly improved efficiency.",py:"Zhège bànfǎ dàdà tígāole xiàolǜ."},{zh:"结果远远超过了我们的预期。",en:"The result far exceeded our expectations.",py:"Jiéguǒ yuǎnyuǎn chāoguòle wǒmen de yùqī."},{zh:"新设备使成本大大降低。",en:"The new equipment greatly reduced costs.",py:"Xīn shèbèi shǐ chéngběn dàdà jiàngdī."}],exercises:[{kind:"choice",q:"只靠这点儿工资养活一家人，___不够。",instr:"辨析",instrEn:"Pick the right one",body:"只靠这点儿工资养活一家人，___不够。",options:["多多","很多","大大","远远"],answer:3,explain:"“远远不够”强调差距很大，是固定搭配；“大大”修饰变化（提高、降低），不说“大大不够”。",explainEn:"“远远不够” = far from enough; 大大 modifies changes, not “不够”."},{kind:"choice",q:"地铁开通以后，人们上班路上的时间大大___了。",instr:"完成",instrEn:"Complete the sentence",body:"地铁开通以后，人们上班路上的时间大大___了。",options:["短暂","缩短","简短","短小"],answer:1,explain:"“大大”后面接表示变化的动词，如“提高、降低、缩短”；“短暂、简短、短小”都是形容词，不表示变化。",explainEn:"“大大” goes with a verb of change like 缩短; 短暂/简短/短小 are adjectives, not changes."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["实际费用远远超出了预算。","新方法大大减少了浪费。","这次的成绩远远好，大家都很满意。","这里的空气质量远远好于市区。"],answer:2,explain:"“远远”后面要接“超过、高于、好于”等比较说法，不能只接形容词；应改为“远远好于上次”。",explainEn:"“远远” needs a comparison like 好于/超过; say “远远好于上次”."},{q:"翻译：The new policy has greatly reduced traffic accidents.",a:"新政策大大减少了交通事故。",instr:"翻译",instrEn:"Translate",body:"The new policy has greatly reduced traffic accidents."}],note:"这类重叠形式常作程度副词，强调变化大或差距远。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dàdà + tígāo/jiàngdī/chāoguò; yuǎnyuǎn + gāoyú/dīyú/chāoguò = greatly …; far …",noteEn:"These reduplicated forms work as degree adverbs, stressing a big change or a wide gap.",typeEn:"Degree adverb"}]},{num:24,title:"体育明星们的离奇遭遇",points:[{id:"HSK6.24.1",name:"紧缩句",pinyin:"jǐnsuō jù",type:"复句结构",explainEn:"A 紧缩句 compresses a complex sentence into a short form, often without a pause or full conjunction pair.",structure:"压缩条件/让步等关系：A + B（如“不喜欢就不买”）",examples:[{zh:"不喜欢就别买。",en:"If you do not like it, do not buy it.",py:"Bù xǐhuan jiù bié mǎi."},{zh:"她一回来我就告诉你。",en:"As soon as she comes back, I will tell you.",py:"Tā yì huílai wǒ jiù gàosu nǐ."},{zh:"想赢也不能违反规则。",en:"Even if you want to win, you cannot break the rules.",py:"Xiǎng yíng yě bù néng wéifǎn guīzé."}],exercises:[{kind:"choice",q:"你___说我也知道是怎么回事。",instr:"辨析",instrEn:"Pick the right one",body:"你___说我也知道是怎么回事。",options:["一","不","越","就"],answer:1,explain:"“不A也B”是紧缩的让步关系，意思是“即使你不说，我也知道”；“一”要配“就”，“越”要配“越”。",explainEn:"“不…也…” = even if you don’t…; “一” needs “就”, “越” needs “越”."},{kind:"choice",q:"天再冷他也___。",instr:"完成",instrEn:"Complete the sentence",body:"天再冷他也___。",options:["不出门了","只好在家","就不跑了","坚持晨跑"],answer:3,explain:"“再A也B”表示让步，B应是不受A影响、照样做的事；“不出门、在家、不跑了”都是顺着天冷说的，不是让步。",explainEn:"“再…也…” = no matter how…still, so B must go against expectation; the others just follow from the cold."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你不去也我去。","有问题就找我。","他越说越激动。","再忙也要吃早饭。"],answer:0,explain:"紧缩句中“也”是副词，要放在后一主语后面；应改为“你不去我也去”。",explainEn:"“也” must follow the second subject: “你不去我也去”."},{q:"翻译：If you're tired, take a rest; don't push yourself.",a:"累了就休息，别勉强自己。",instr:"翻译",instrEn:"Translate",body:"If you're tired, take a rest; don't push yourself."}],note:"看起来像单句，但实际包含条件、让步、承接等复句关系。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Compressed condition / concession: A + B (e.g. bù xǐhuan jiù bù mǎi) = if/even if A, B",noteEn:"Looks like a simple sentence but actually contains a conditional, concessive or sequential relation.",typeEn:"Complex sentence"},{id:"HSK6.24.2",name:"副词“特意”",pinyin:"tèyì",type:"副词",explainEn:"Use 特意 to mean “specially / intentionally for a good or specific purpose”.",structure:"特意 + 动词",examples:[{zh:"我特意来看看你。",en:"I came specially to see you.",py:"Wǒ tèyì lái kànkan nǐ."},{zh:"为了这次会议，他特意准备了资料。",en:"He specially prepared materials for this meeting.",py:"Wèile zhè cì huìyì, tā tèyì zhǔnbèile zīliào."},{zh:"妈妈特意做了我最喜欢的菜。",en:"Mom specially cooked my favorite dish.",py:"Māma tèyì zuòle wǒ zuì xǐhuan de cài."}],exercises:[{kind:"choice",q:"为了给你过生日，奶奶___做了一桌你爱吃的菜。",instr:"辨析",instrEn:"Pick the right one",body:"为了给你过生日，奶奶___做了一桌你爱吃的菜。",options:["故意","专程","特意","随意"],answer:2,explain:"“特意”表示为了某个目的专门去做，多含好意；“故意”常指存心做不好的事，“专程”只用于专为某事去某地。",explainEn:"“特意” = specially, with good intent; “故意” = on purpose (usually bad), and “专程” is only for making a special trip."},{kind:"choice",q:"他特意从上海赶回来，___。",instr:"完成",instrEn:"Complete the sentence",body:"他特意从上海赶回来，___。",options:["就是为了参加女儿的婚礼","只是因为航班取消了","其实只是顺路经过","自己也不知道为什么"],answer:0,explain:"“特意”表示有明确目的，后面应说明这个目的；“顺路、没有原因”与“特意”矛盾。",explainEn:"“特意” implies a clear purpose, so the follow-up should state it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这件礼物是我特意为你挑的。","老师特意放慢语速，让大家听清楚。","为了见你，她特意请了一天假。","他特意把我的杯子打碎了，真让人生气。"],answer:3,explain:"存心做坏事应该用“故意”，“特意”多用于好意；应改为“他故意把我的杯子打碎了”。",explainEn:"For doing harm on purpose use “故意”, not “特意”."},{q:"翻译：He specially prepared materials for the meeting.",a:"他特意准备了资料。",instr:"翻译",instrEn:"Translate",body:"He specially prepared materials for the meeting."}],note:"通常有明确目的，感情色彩中性或积极；不要和常带贬义的“故意”混淆。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"tèyì + Verb = do … specially (for a purpose)",noteEn:"Usually has a clear purpose, neutral or positive; don't confuse it with 故意, which is often negative.",typeEn:"Adverb"}]},{num:25,title:"草船借箭",points:[{id:"HSK6.25.1",name:"副词“即将”",pinyin:"jíjiāng",type:"副词",explainEn:"Use 即将 to mean “be about to / soon will”. It is formal.",structure:"即将 + 动词/变化",examples:[{zh:"会议即将开始。",en:"The meeting is about to begin.",py:"Huìyì jíjiāng kāishǐ."},{zh:"我们即将进入考试周。",en:"We are about to enter exam week.",py:"Wǒmen jíjiāng jìnrù kǎoshì zhōu."},{zh:"新产品即将上市。",en:"The new product will be launched soon.",py:"Xīn chǎnpǐn jíjiāng shàngshì."}],exercises:[{kind:"choice",q:"本次列车___到达终点站，请乘客们做好下车准备。",instr:"辨析",instrEn:"Pick the right one",body:"本次列车___到达终点站，请乘客们做好下车准备。",options:["即使","即将","将近","立即"],answer:1,explain:"“即将”表示很快就要发生，常用于通知；“立即”多用于要求马上做，“将近”接数量，“即使”是连词。",explainEn:"“即将” = about to, used in announcements; “立即” = at once, “将近” = nearly, “即使” = even if."},{kind:"choice",q:"即将毕业的学生们___。",instr:"完成",instrEn:"Complete the sentence",body:"即将毕业的学生们___。",options:["刚参加了入学考试","已经工作了五年","正忙着找工作","去年就离开了学校"],answer:2,explain:"“即将毕业”表示还没毕业、很快毕业，所以只能是正在找工作；其他都与“还没毕业”矛盾。",explainEn:"“即将毕业” means about to graduate, so they’re job-hunting now."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这座大桥即将在去年建成。","这部电影即将在全国上映。","新的学期即将开始。","比赛即将结束，比分仍是一比一。"],answer:0,explain:"“即将”指将来很快发生，不能和过去时间“去年”连用；应改为“这座大桥即将建成”。",explainEn:"“即将” is future and can’t go with “去年”."},{q:"翻译：The museum will soon close for repairs.",a:"博物馆即将闭馆维修。",instr:"翻译",instrEn:"Translate",body:"The museum will soon close for repairs."}],note:"常见于新闻、通知、正式说明。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jíjiāng + Verb / change = be about to …",noteEn:"Common in news, notices and formal statements.",typeEn:"Adverb"},{id:"HSK6.25.2",name:"固定格式“能A就A”",pinyin:"néng A jiù A",type:"固定格式",explainEn:"Use 能A就A to mean “do as much/as soon/as well as you can”.",structure:"能 + 动词/形容词 + 就 + 同一动词/形容词",examples:[{zh:"能早点儿走就早点儿走。",en:"Leave as early as you can.",py:"Néng zǎo diǎnr zǒu jiù zǎo diǎnr zǒu."},{zh:"能帮一点儿就帮一点儿。",en:"Help as much as you can.",py:"Néng bāng yìdiǎnr jiù bāng yìdiǎnr."},{zh:"能省就省，别乱花钱。",en:"Save as much as you can; do not waste money.",py:"Néng shěng jiù shěng, bié luàn huā qián."}],exercises:[{kind:"choice",q:"这种事能不管___不管，免得惹麻烦。",instr:"辨析",instrEn:"Pick the right one",body:"这种事能不管___不管，免得惹麻烦。",options:["都","就","才","也"],answer:1,explain:"格式是“能A就A”，中间用“就”连接前后相同的部分。",explainEn:"The pattern is “能A就A”, linked by “就”."},{kind:"choice",q:"这次聚会你能来就来，___。",instr:"完成",instrEn:"Complete the sentence",body:"这次聚会你能来就来，___。",options:["不来就别再找我了","必须提前一天到","无论如何都得来","实在来不了也没关系"],answer:3,explain:"“能A就A”表示在条件允许的范围内尽量做到，并不强求，所以后面说“来不了也没关系”；其他选项都是强迫对方来。",explainEn:"“能A就A” = do it if you can, without forcing it, so “it’s fine if you really can’t come” fits."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["能简单就简单，别搞得太复杂。","能走路就走路，少开车。","能自己做的事就自己做。","能省就花，别乱买东西。"],answer:3,explain:"“能A就A”前后要重复同一个词；应改为“能省就省”。",explainEn:"Both halves must repeat the same word: “能省就省”."},{q:"翻译：Rest whenever you can; don't tire yourself out.",a:"能休息就休息，别把自己累坏了。",instr:"翻译",instrEn:"Translate",body:"Rest whenever you can; don't tire yourself out."}],note:"强调在条件允许的范围内尽量做到。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"néng + Verb/Adj + jiù + same Verb/Adj = … as much as you can",noteEn:"Stresses doing as much as conditions allow.",typeEn:"Fixed pattern"}]},{num:26,title:"奇异的灯光",points:[{id:"HSK6.26.1",name:"连词“别说”",pinyin:"biéshuō",type:"连词",explainEn:"Use 别说 to introduce a stronger comparison: “let alone / not to mention”.",structure:"别说 + 较难情况，连/就是 + 较容易情况 + 都/也……",examples:[{zh:"别说跑十公里了，跑一公里我都累。",en:"Let alone running ten kilometers; even one kilometer tires me.",py:"Biéshuō pǎo shí gōnglǐ le, pǎo yì gōnglǐ wǒ dōu lèi."},{zh:"别说外国人，有些中国人也不认识这个字。",en:"Not to mention foreigners; even some Chinese people do not know this character.",py:"Biéshuō wàiguórén, yǒuxiē Zhōngguórén yě bú rènshi zhège zì."},{zh:"别说买房了，现在连房租都很贵。",en:"Let alone buying a home; even rent is expensive now.",py:"Biéshuō mǎi fáng le, xiànzài lián fángzū dōu hěn guì."}],exercises:[{kind:"choice",q:"___出国旅行了，他连省都没出过。",instr:"辨析",instrEn:"Pick the right one",body:"___出国旅行了，他连省都没出过。",options:["别说","不但","即使","何况"],answer:0,explain:"“别说A，连B都……”用更难的A衬托连较容易的B都做不到；“不但”要配“而且”，“何况”“即使”不能放在句首这样用。",explainEn:"“别说A，连B都…” = let alone A, not even B; “不但” needs “而且”."},{kind:"choice",q:"这个错误太明显了，别说是专家，___。",instr:"完成",instrEn:"Complete the sentence",body:"这个错误太明显了，别说是专家，___。",options:["专家也会犯这样的错","就连小孩子也能看出来","只有专家才能看出来","普通人肯定看不出来"],answer:1,explain:"“别说”后的情况更容易做到，后面要说连更难的人（小孩子）都能做到，这样才能形成对比。",explainEn:"After “别说 experts”, the next part must say even a child could see it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["别说吃饭了，我连喝水的时间都没有。","这道题别说学生，老师也得想半天。","别说一公里了，十公里我都跑不了。","别说你了，连我都不知道这件事。"],answer:2,explain:"“别说”后应是更难的情况，这里大小颠倒了；应改为“别说十公里了，一公里我都跑不了”。",explainEn:"The harder case goes after 别说: “别说十公里了，一公里我都跑不了”."},{q:"翻译：Let alone buying a home; even rent is expensive.",a:"别说买房了，连房租都很贵。",instr:"翻译",instrEn:"Translate",body:"Let alone buying a home; even rent is expensive."}],note:"通过较极端情况来强调连较普通情况都难以达到。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biéshuō + harder case, lián/jiùshì + easier case + dōu/yě … = let alone … , even … not …",noteEn:"Uses an extreme case to stress that even the ordinary case is hard to reach.",typeEn:"Conjunction"},{id:"HSK6.26.2",name:"AABB式重叠“来来回回”等",pinyin:"AABB shì chóngdié",type:"重叠结构",explainEn:"Some two-syllable words can repeat as AABB to stress repeated, continuous, or distributed action/state.",structure:"AB → AABB",examples:[{zh:"他在门口来来回回走了半天。",en:"He walked back and forth at the door for a long time.",py:"Tā zài ménkǒu láiláihuíhuí zǒule bàntiān."},{zh:"大家说说笑笑地吃完了饭。",en:"Everyone ate while chatting and laughing.",py:"Dàjiā shuōshuōxiàoxiào de chīwánle fàn."},{zh:"她认认真真地检查了一遍。",en:"She checked it very carefully.",py:"Tā rènrènzhēnzhēn de jiǎnchále yí biàn."}],exercises:[{kind:"choice",q:"她把房间收拾得___，一点儿灰尘都没有。",instr:"辨析",instrEn:"Pick the right one",body:"她把房间收拾得___，一点儿灰尘都没有。",options:["很干干净净","干净干净的","干干净净地","干干净净的"],answer:3,explain:"形容词AB的生动形式是AABB，作补语时常说“干干净净的”；AABB本身已表示程度深，前面不能加“很”；“干净干净”是动词的ABAB式；补语后面用“的”，不用“地”。",explainEn:"Adjective AB becomes AABB, and as a complement it is “干干净净的”; AABB already shows degree so no 很, ABAB is a verb pattern, and a complement ends in 的, not 地."},{kind:"choice",q:"他们一路上说说笑笑，___。",instr:"完成",instrEn:"Complete the sentence",body:"他们一路上说说笑笑，___。",options:["一点儿也不觉得累","谁也不理谁","气氛十分紧张","一句话也没说"],answer:0,explain:"“说说笑笑”描写边说边笑、气氛轻松，所以不会觉得累；其他选项都与此矛盾。",explainEn:"“说说笑笑” means chatting and laughing, so they didn’t feel tired."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他们安安静静地坐在角落里。","孩子们高兴高兴地跑回了家。","他把事情的经过清清楚楚地讲了一遍。","门口的人来来往往，非常热闹。"],answer:1,explain:"形容词要用AABB式重叠，不能用ABAB式；应改为“孩子们高高兴兴地跑回了家”。",explainEn:"Adjectives reduplicate as AABB, not ABAB: “孩子们高高兴兴地跑回了家”."},{q:"翻译：The children happily went to school.",a:"孩子们高高兴兴地去上学了。",instr:"翻译",instrEn:"Translate",body:"The children happily went to school."}],note:"不同词重叠后的意义不同，常强调反复、程度或生动感。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"AB → AABB = repeated / vivid form (láiláihuíhuí = back and forth)",noteEn:"Different words mean different things when reduplicated; often stresses repetition, degree or vividness.",typeEn:"Reduplication"}]},{num:27,title:"完璧归赵",points:[{id:"HSK6.27.1",name:"固定格式“左……右……”",pinyin:"zuǒ ... yòu ...",type:"固定格式",explainEn:"Use 左…右… with verbs to show repeated action in different directions or repeated attempts.",structure:"左 + 动词A + 右 + 动词B",examples:[{zh:"我左想右想，还是决定去。",en:"I thought it over again and again and still decided to go.",py:"Wǒ zuǒ xiǎng yòu xiǎng, háishi juédìng qù."},{zh:"他左看右看，没找到出口。",en:"He looked left and right but did not find the exit.",py:"Tā zuǒ kàn yòu kàn, méi zhǎodào chūkǒu."},{zh:"大家左等右等，他还是没来。",en:"Everyone waited and waited, but he still did not come.",py:"Dàjiā zuǒ děng yòu děng, tā háishi méi lái."}],exercises:[{kind:"choice",q:"辞职这件事，他___了一整夜，还是拿不定主意。",instr:"辨析",instrEn:"Pick the right one",body:"辞职这件事，他___了一整夜，还是拿不定主意。",options:["左顾右盼","左思右想","左躲右闪","左推右挡"],answer:1,explain:"“左思右想”表示反复考虑，正合“拿不定主意”；“左顾右盼”是向四周张望，“左躲右闪”“左推右挡”是身体躲避、推挡的动作，都不表示思考。",explainEn:"左思右想 means thinking something over and over, which fits being unable to decide; the others describe looking around or dodging, not thinking."},{kind:"choice",q:"钥匙不见了，他左找右找，___。",instr:"完成",instrEn:"Complete the sentence",body:"钥匙不见了，他左找右找，___。",options:["最后才发现就在自己口袋里","一眼就看见它放在桌上","顺手就从抽屉里拿了出来","刚进门就随手找到了"],answer:0,explain:"“左找右找”表示反复找了很久，后面应是费了很大劲才有的结果；“一眼就看见”等表示很快找到，与之矛盾。",explainEn:"左找右找 means searching again and again for a long time, so the result must come late; finding it at once contradicts it."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我左劝右劝，他总算答应去看医生了。","他左想右想，马上就做出了决定。","她左挑右挑，最后还是选了第一件。","她对着镜子左看右看，总觉得这件衣服不太合适。"],answer:1,explain:"“左想右想”表示反复考虑，不能和“马上”连用，应改为“他左想右想，最后才做出了决定”。",explainEn:"左想右想 means thinking it over many times, which clashes with 马上; say 他左想右想，最后才做出了决定."},{q:"翻译：She thought it over again and again, but still couldn't decide which university to choose.",a:"她左思右想，还是拿不定主意选哪所大学。",instr:"翻译",instrEn:"Translate",body:"She thought it over again and again, but still couldn't decide which university to choose."}],note:"A、B多为相同或相关动词，表示反复、到处或多次尝试。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zuǒ + Verb A + yòu + Verb B = A again and again",noteEn:"A and B are usually the same or related verbs; shows repeated action, everywhere, or many attempts.",typeEn:"Fixed pattern"},{id:"HSK6.27.2",name:"句末“……不成？”",pinyin:"... bùchéng?",type:"反问/推测结构",explainEn:"Use 不成 at the end of a question to show doubt or rhetorical surprise: “could it be that…?”.",structure:"难道/莫非 + 小句 + 不成？；小句 + 不成？",examples:[{zh:"难道你想一个人去不成？",en:"Could it be that you want to go alone?",py:"Nándào nǐ xiǎng yí ge rén qù bùchéng?"},{zh:"他这么久没来，出什么事了不成？",en:"He has not come for so long; could something have happened?",py:"Tā zhème jiǔ méi lái, chū shénme shì le bùchéng?"},{zh:"你还真打算放弃不成？",en:"Are you really planning to give up?",py:"Nǐ hái zhēn dǎsuàn fàngqì bùchéng?"}],exercises:[{kind:"choice",q:"难道你还要我亲自送到你家门口___？",instr:"辨析",instrEn:"Pick the right one",body:"难道你还要我亲自送到你家门口___？",options:["不成","不行","不可","罢了"],answer:0,explain:"“难道……不成”是固定的反问格式，表示不相信或不同意；“罢了”表示“仅此而已”，“不行、不可”不能放在句末构成这种反问。",explainEn:`难道…不成 is a fixed rhetorical pattern showing disbelief; 罢了 means "that's all", and 不行/不可 cannot close the question this way.`},{kind:"choice",q:"他平时连一公里都跑不下来，难道___不成？",instr:"完成",instrEn:"Complete the sentence",body:"他平时连一公里都跑不下来，难道___不成？",options:["今天也只能跑一小段","今天还是会中途停下来","今天照样会觉得很吃力","今天能跑完全程马拉松"],answer:3,explain:"“难道……不成”用来对出乎意料、难以相信的事表示怀疑；只有“跑完全程马拉松”与他平时的情况相反，其他都是意料之中的事。",explainEn:"难道…不成 questions something hard to believe; only finishing a marathon is unexpected, the others are what one would expect."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["都这么晚了他还没到，莫非路上出事了不成？","我相信他一定能做到不成。","你一句话不说，难道是生我的气了不成？","他天天这么拼命，莫非想把自己累垮不成？"],answer:1,explain:"“不成”只用在反问句末尾表示怀疑，不能用在陈述句里，应改为“我相信他一定能做到”。",explainEn:"不成 only ends a rhetorical question of doubt, not a statement; say 我相信他一定能做到."},{q:"翻译：Could something have happened?",a:"出什么事了不成？",instr:"翻译",instrEn:"Translate",body:"Could something have happened?"}],note:"多用于反问或猜测，语气较强，常带惊讶或不同意。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nándào/mòfēi + Clause + bùchéng? ; Clause + bùchéng? = could it be that …?",noteEn:"Mostly in rhetorical questions or guesses; a strong tone, often surprise or disagreement.",typeEn:"Rhetorical / Guessing"}]},{num:28,title:"高山流水遇知音",points:[{id:"HSK6.28.1",name:"与“个”相关的格式",pinyin:"yǔ “gè” xiāngguān de géshì",type:"结构",explainEn:"Two useful patterns with 个: “一个 + noun/verb phrase” can show a sudden action; “V + (了)个 + result” introduces a result vividly.",structure:"一个 + 名词/动词结构 + V；V +（了）个 + 形容词/动词结果",examples:[{zh:"他一个不小心，把杯子打碎了。",en:"He accidentally broke the cup in one careless moment.",py:"Tā yí ge bù xiǎoxīn, bǎ bēizi dǎsuì le."},{zh:"孩子一个跟头摔倒了。",en:"The child fell over in a sudden tumble.",py:"Háizi yí ge gēntou shuāidǎo le."},{zh:"他把房间收拾了个干干净净。",en:"He cleaned the room completely.",py:"Tā bǎ fángjiān shōushile ge gāngānjìngjìng."}],exercises:[{kind:"choice",q:"他不放心，又打电话把这件事问了个___。",instr:"辨析",instrEn:"Pick the right one",body:"他不放心，又打电话把这件事问了个___。",options:["明白明白","明白了","明明白白","很明白"],answer:2,explain:"“V了个”后面的结果要用生动的形式，如形容词重叠“明明白白”；“明白明白”是动词式重叠，表示试一试，不能作结果；“个”后面也不能再加“了”或“很”。",explainEn:'After V了个 the result must be a vivid form such as the reduplicated 明明白白; 明白明白 is a verb-style "try" reduplication, and 个 cannot be followed by 了 or 很.'},{kind:"choice",q:"他一个不留神，___。",instr:"完成",instrEn:"Complete the sentence",body:"他一个不留神，___。",options:["身体一年比一年差了","脚下一滑摔倒了","成绩渐渐落到了后面","慢慢养成了熬夜的习惯"],answer:1,explain:"“一个+动词结构”表示动作突然发生，后面接一下子出现的意外结果；“一年比一年、渐渐、慢慢”都是逐渐变化，不合这种格式。",explainEn:"一个 + verb phrase marks a sudden moment followed by an instant mishap; gradual changes like 一年比一年 or 渐渐 do not fit."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他一个没注意，把咖啡洒在了文件上。","孩子一个翻身，从床上滚了下来。","听完这个笑话，大家笑了个痛快。","他把衣服洗了个很干净。"],answer:3,explain:"“V了个”后不能用“很+形容词”，应改为“洗了个干干净净”或“洗得很干净”。",explainEn:"After V了个 you cannot use 很 + adjective; say 洗了个干干净净 or 洗得很干净."},{q:"翻译：After the game, the kids played to their heart's content.",a:"比赛结束后，孩子们玩了个痛快。",instr:"翻译",instrEn:"Translate",body:"After the game, the kids played to their heart's content."}],note:"教材把两类“个”格式放在一起：一类突出突然发生，一类生动引出动作结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yí ge + Noun/verb phrase + V; V + (le) ge + Adj/Verb result = suddenly …; V till it ends up …",noteEn:"The textbook groups two 个 patterns: one shows something happening suddenly, the other vividly introduces a result.",typeEn:"Structure"},{id:"HSK6.28.2",name:"副词“向来”",pinyin:"xiànglái",type:"副词",explainEn:"Use 向来 to mean “always / all along” from the past until now.",structure:"向来 + 谓语",examples:[{zh:"他做事向来认真。",en:"He has always been serious about his work.",py:"Tā zuòshì xiànglái rènzhēn."},{zh:"这里向来很安静。",en:"This place has always been quiet.",py:"Zhèlǐ xiànglái hěn ānjìng."},{zh:"我向来不喜欢迟到。",en:"I have never liked being late.",py:"Wǒ xiànglái bù xǐhuan chídào."}],exercises:[{kind:"choice",q:"他说话___很直接，你别往心里去。",instr:"辨析",instrEn:"Pick the right one",body:"他说话___很直接，你别往心里去。",options:["一度","一时","偶然","向来"],answer:3,explain:"“向来”表示从过去到现在一直如此，正好解释现在说话直；“一度”指过去有过一段时间，“一时”指短时间，“偶然”不能修饰“很直接”这种状态。",explainEn:"向来 means it has always been so, which explains his present directness; 一度 is a past period, 一时 a short moment, and 偶然 cannot modify a state like 很直接."},{kind:"choice",q:"他向来___，这次却当众发了火，大家都很吃惊。",instr:"完成",instrEn:"Complete the sentence",body:"他向来___，这次却当众发了火，大家都很吃惊。",options:["今天心情不错","这两天比较累","脾气温和","刚刚喝了点酒"],answer:2,explain:"“向来”后面要接一贯的性格或习惯，“脾气温和”才能和“这次却发了火”形成对比；今天、这两天、刚刚都是一时的情况，不能和“向来”连用。",explainEn:"向来 must be followed by a long-standing trait; only 脾气温和 works and contrasts with this time; 今天/这两天/刚刚 are temporary."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这家店的服务向来很周到。","他昨天向来没来上班。","他向来不喝酒，今天却喝了两杯。","南方的冬天向来比较潮湿。"],answer:1,explain:"“向来”表示一贯如此，不能和“昨天”这种具体时间连用，应改为“他昨天没来上班”。",explainEn:'向来 means "always", so it cannot go with a single day like 昨天; say 他昨天没来上班.'},{q:"翻译：Grandpa has always gone to bed early.",a:"爷爷向来睡得很早。",instr:"翻译",instrEn:"Translate",body:"Grandpa has always gone to bed early."}],note:"强调从过去到现在一贯如此。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xiànglái + predicate = always (has been) …",noteEn:"Stresses that something has always been so, from the past until now.",typeEn:"Adverb"}]},{num:29,title:"“笑”的备忘录",points:[{id:"HSK6.29.1",name:"副词“预先”",pinyin:"yùxiān",type:"副词",explainEn:"Use 预先 to mean “in advance / beforehand”.",structure:"预先 + 动词",examples:[{zh:"请预先准备好材料。",en:"Please prepare the materials in advance.",py:"Qǐng yùxiān zhǔnbèi hǎo cáiliào."},{zh:"我们已经预先订好了房间。",en:"We booked the room in advance.",py:"Wǒmen yǐjīng yùxiān dìnghǎole fángjiān."},{zh:"重要情况要预先说明。",en:"Important circumstances should be explained beforehand.",py:"Zhòngyào qíngkuàng yào yùxiān shuōmíng."}],exercises:[{kind:"choice",q:"会议的议程需要___通知所有参加者。",instr:"辨析",instrEn:"Pick the right one",body:"会议的议程需要___通知所有参加者。",options:["预计","预先","预料","预防"],answer:1,explain:"“预先”是副词，修饰动词“通知”，表示事前；“预计、预料、预防”都是动词，不能这样修饰“通知”。",explainEn:'预先 is an adverb meaning "beforehand" and can modify 通知; 预计, 预料 and 预防 are verbs and cannot.'},{kind:"choice",q:"这次演出，主办方预先___。",instr:"完成",instrEn:"Complete the sentence",body:"这次演出，主办方预先___。",options:["对这场演出做了总结","收拾好了散场后的垃圾","把节目单发给了观众","公布了观众的评分结果"],answer:2,explain:"“预先”指在事情发生以前做；总结、散场后收拾、公布评分都只能在演出以后进行。",explainEn:"预先 means doing something before the event; summing up, cleaning up and posting ratings can only happen after the show."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["去之前最好预先打个电话问问。","这些问题我们已经预先考虑到了。","预先我们应该做好准备。","参观博物馆需要预先在网上预约。"],answer:2,explain:"“预先”是副词，要放在主语后、动词前，应改为“我们应该预先做好准备”。",explainEn:"预先 is an adverb and goes after the subject, before the verb: 我们应该预先做好准备."},{q:"翻译：We booked the room in advance.",a:"我们预先订好了房间。",instr:"翻译",instrEn:"Translate",body:"We booked the room in advance."}],note:"比“提前”更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yùxiān + Verb = do … in advance",noteEn:"More formal than 提前.",typeEn:"Adverb"},{id:"HSK6.29.2",name:"让步列举“……也好，……也罢”",pinyin:"... yě hǎo, ... yě bà",type:"让步/列举结构",explainEn:"Use …也好，…也罢 to mean “whether…or… / be it…or…”, showing the result is the same.",structure:"A + 也好，B + 也罢，+ 不变结果",examples:[{zh:"成功也好，失败也罢，我们都要认真总结。",en:"Whether we succeed or fail, we should summarize carefully.",py:"Chénggōng yě hǎo, shībài yě bà, wǒmen dōu yào rènzhēn zǒngjié."},{zh:"你去也好，不去也罢，都要早点儿决定。",en:"Whether you go or not, decide early.",py:"Nǐ qù yě hǎo, bú qù yě bà, dōu yào zǎo diǎnr juédìng."},{zh:"工作也好，学习也罢，态度都很重要。",en:"Whether at work or study, attitude is important.",py:"Gōngzuò yě hǎo, xuéxí yě bà, tàidu dōu hěn zhòngyào."}],exercises:[{kind:"choice",q:"你同意___，反对也罢，这件事都已经定下来了。",instr:"辨析",instrEn:"Pick the right one",body:"你同意___，反对也罢，这件事都已经定下来了。",options:["罢了","也许","也是","也好"],answer:3,explain:"固定格式是“A也好，B也罢”，表示不管哪种情况结果都不变；“罢了”用在句末表示“仅此而已”，不能这样搭配。",explainEn:`The fixed pair is A也好，B也罢 ("whether A or B"); 罢了 means "that's all" and does not pair this way.`},{kind:"choice",q:"喜欢也好，不喜欢也罢，___。",instr:"完成",instrEn:"Complete the sentence",body:"喜欢也好，不喜欢也罢，___。",options:["你得看自己喜不喜欢再决定","这门课你都得认真上完","只有喜欢的人才需要去上","不喜欢的话就可以不来了"],answer:1,explain:"“也好……也罢”后面的结果不随前面的情况改变；其他选项都让结果取决于喜不喜欢。",explainEn:"After 也好…也罢 the result stays the same in every case; the other options make it depend on liking the course."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["晴天也好，雨天也罢，他每天都坚持跑步。","贵也好，便宜也罢，这件衣服我是一定要买的。","赢也好，输也罢，只有赢了才算成功。","说中文也好，说英文也罢，只要能交流就行。"],answer:2,explain:"“也好……也罢”表示两种情况结果一样，后面不能再只认一种情况，可改为“赢也好，输也罢，重要的是尽了全力”。",explainEn:"也好…也罢 means the outcome is the same either way, so the result cannot favour one case; e.g. 重要的是尽了全力."},{q:"翻译：Rich or poor, everyone deserves respect.",a:"富有也好，贫穷也罢，每个人都应该受到尊重。",instr:"翻译",instrEn:"Translate",body:"Rich or poor, everyone deserves respect."}],note:"A、B通常是两种可能，后面的态度或结果不变。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + yě hǎo, B + yě bà, + unchanged result = whether A or B, …",noteEn:"A and B are usually two possibilities; the attitude or result after them stays the same.",typeEn:"Concessive / Listing"}]},{num:30,title:"你睡好了吗",points:[{id:"HSK6.30.1",name:"副词“不时”",pinyin:"bùshí",type:"副词",explainEn:"Use 不时 to mean “from time to time / now and then”.",structure:"不时 + 动词",examples:[{zh:"他工作的时候不时看看手机。",en:"He looks at his phone from time to time while working.",py:"Tā gōngzuò de shíhou bùshí kànkan shǒujī."},{zh:"外面不时传来汽车声。",en:"Car sounds come from outside from time to time.",py:"Wàimiàn bùshí chuánlái qìchē shēng."},{zh:"她说话时不时笑一笑。",en:"She smiles now and then while speaking.",py:"Tā shuōhuà shí bùshí xiào yi xiào."}],exercises:[{kind:"choice",q:"他一边开车，一边___看一眼后视镜。",instr:"辨析",instrEn:"Pick the right one",body:"他一边开车，一边___看一眼后视镜。",options:["不禁","不免","不料","不时"],answer:3,explain:"“不时”表示隔一会儿就做一次，正合开车时反复看后视镜；“不禁”指情不自禁，“不免”指难免，“不料”指没想到，都不合语境。",explainEn:`不时 means "every now and then", fitting a repeated glance; 不禁 is "can't help", 不免 "unavoidably", 不料 "unexpectedly".`},{kind:"choice",q:"复习的时候，他不时___。",instr:"完成",instrEn:"Complete the sentence",body:"复习的时候，他不时___。",options:["一口气看完了整本书","已经连续熬了三个通宵","抬头看看墙上的钟","从来没有看过一次手机"],answer:2,explain:"“不时”表示一段时间里断断续续地多次发生，后面常接短暂、可重复的动作；“一口气、连续、从来没有”都与此矛盾。",explainEn:'不时 marks a short action repeated off and on; "in one go", "for three nights straight" and "never once" contradict it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他不时没来上课，老师很生气。","窗外不时传来几声鸟叫。","开会时，老板不时皱一下眉头。","她一边听，一边不时点点头。"],answer:0,explain:"“不时”后面要接实际发生的动作，不能接否定，应改为“他时常不来上课”。",explainEn:"不时 must be followed by an action that happens, not a negative; say 他时常不来上课."},{q:"翻译：During the film, laughter came from the audience every now and then.",a:"电影放映时，观众席上不时传来笑声。",instr:"翻译",instrEn:"Translate",body:"During the film, laughter came from the audience every now and then."}],note:"比“偶尔”更强调在一段时间里间歇性地多次发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùshí + Verb = from time to time …",noteEn:"Stresses repeated, intermittent happenings over a period, more than 偶尔.",typeEn:"Adverb"},{id:"HSK6.30.2",name:"副词“多多少少”",pinyin:"duōduōshǎoshǎo",type:"副词",explainEn:"Use 多多少少 to mean “more or less / to some extent”.",structure:"多多少少 + 谓语",examples:[{zh:"这件事对他多多少少有些影响。",en:"This matter affected him to some extent.",py:"Zhè jiàn shì duì tā duōduōshǎoshǎo yǒuxiē yǐngxiǎng."},{zh:"学过一年中文的人多多少少能听懂一点儿。",en:"Someone who studied Chinese for a year can understand a little to some extent.",py:"Xuéguo yì nián Zhōngwén de rén duōduōshǎoshǎo néng tīngdǒng yìdiǎnr."},{zh:"每个人多多少少都会遇到压力。",en:"Everyone experiences some pressure to some extent.",py:"Měi ge rén duōduōshǎoshǎo dōu huì yùdào yālì."}],exercises:[{kind:"choice",q:"出国留学一年，他的口语___有了一些进步。",instr:"辨析",instrEn:"Pick the right one",body:"出国留学一年，他的口语___有了一些进步。",options:["大大小小","前前后后","许许多多","多多少少"],answer:3,explain:"“多多少少”表示或多或少有一些，常和“一些、一点儿”搭配；其他重叠词不能表示这种不精确的程度。",explainEn:'多多少少 means "more or less, to some extent" and goes with 一些; the other reduplications do not have this meaning.'},{kind:"choice",q:"这次比赛虽然输了，但大家多多少少___。",instr:"完成",instrEn:"Complete the sentence",body:"这次比赛虽然输了，但大家多多少少___。",options:["学到了全部的技巧","学到了一些经验","什么也没有学到","完全掌握了比赛规则"],answer:1,explain:"“多多少少”表示有一些但不多，不能和“全部、完全”或“什么也没有”这种极端说法搭配。",explainEn:'多多少少 means "some, though not much"; it cannot go with "all", "completely" or "nothing at all".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["第一次上台演讲，谁都多多少少会有点紧张。","这次调整对我们的计划多多少少有些影响。","他多多少少完全听懂了老师的话。","他在中国住了五年，多多少少了解一些当地文化。"],answer:2,explain:"“多多少少”表示有一部分，和“完全”矛盾，应改为“他多多少少听懂了一些”。",explainEn:"多多少少 (partly) contradicts 完全 (fully); say 他多多少少听懂了一些."},{q:"翻译：Anyone who has lived abroad has felt homesick to some extent.",a:"在国外生活过的人，多多少少都有过想家的感觉。",instr:"翻译",instrEn:"Translate",body:"Anyone who has lived abroad has felt homesick to some extent."}],note:"表示程度或数量不是很精确，但多少有一点。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"duōduōshǎoshǎo + predicate = more or less …",noteEn:"The degree or amount isn't exact, but there is at least some.",typeEn:"Adverb"}]},{num:31,title:"运动的学问",points:[{id:"HSK6.31.1",name:"介词/构词成分“逐”",pinyin:"zhú",type:"介词/构词成分",explainEn:"Use 逐 to mean “one by one / each / step by step”, mostly in formal expressions.",structure:"逐 + 个/项/年/日/步 + 动词/变化",examples:[{zh:"请逐项检查这些内容。",en:"Please check these items one by one.",py:"Qǐng zhúxiàng jiǎnchá zhèxiē nèiróng."},{zh:"公司的收入逐年增加。",en:"The company's income increases year by year.",py:"Gōngsī de shōurù zhúnián zēngjiā."},{zh:"问题正在逐步解决。",en:"The problem is being solved step by step.",py:"Wèntí zhèngzài zhúbù jiějué."}],exercises:[{kind:"choice",q:"请大家排好队，工作人员会___检查证件。",instr:"辨析",instrEn:"Pick the right one",body:"请大家排好队，工作人员会___检查证件。",options:["逐渐","逐个","逐年","逐日"],answer:1,explain:"排队检查证件是一个一个地查，应用“逐个”；“逐渐”指慢慢变化，“逐年、逐日”指按年、按天，都不合语境。",explainEn:'Checking a queue means one by one, so 逐个; 逐渐 is "gradually", 逐年/逐日 "yearly/daily".'},{kind:"choice",q:"近十年来，这个地区的森林面积逐年___。",instr:"完成",instrEn:"Complete the sentence",body:"近十年来，这个地区的森林面积逐年___。",options:["保持不变","完全一样","停止变化","有所扩大"],answer:3,explain:"“逐年”表示一年比一年有变化，后面要接变化的结果；“保持不变、完全一样、停止变化”都表示没有变化。",explainEn:"逐年 means changing year after year, so it needs a change; the other options all mean no change."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["专家对这些数据进行了逐项分析。","我们逐年去了一次北京。","这几年学生的成绩逐步提高了。","主持人逐一介绍了每位来宾。"],answer:1,explain:"“逐年”表示一年一年地变化或进行，不能和“一次”这种单次动作连用，应改为“我们每年都去一次北京”。",explainEn:"逐年 describes year-by-year change, not a single trip; say 我们每年都去一次北京."},{q:"翻译：The teacher checked our homework one by one.",a:"老师逐个检查了我们的作业。",instr:"翻译",instrEn:"Translate",body:"The teacher checked our homework one by one."}],note:"常见固定搭配：逐个、逐项、逐年、逐日、逐步。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zhú + gè/xiàng/nián/rì/bù + Verb/change = one by one / item by item / year by year / step by step",noteEn:"Common set combinations: 逐个, 逐项, 逐年, 逐日, 逐步.",typeEn:"Preposition / Word-forming element"},{id:"HSK6.31.2",name:"插入语“归根到底”",pinyin:"guīgēn dàodǐ",type:"插入语",explainEn:"Use 归根到底 to mean “in the final analysis / fundamentally”.",structure:"归根到底，+ 最根本的原因/结论",examples:[{zh:"归根到底，健康最重要。",en:"In the final analysis, health is the most important.",py:"Guīgēn dàodǐ, jiànkāng zuì zhòngyào."},{zh:"这个问题归根到底还是沟通不够。",en:"Fundamentally, this problem is still caused by poor communication.",py:"Zhège wèntí guīgēn dàodǐ háishi gōutōng bú gòu."},{zh:"方法很多，归根到底还是要坚持。",en:"There are many methods, but in the end you still need persistence.",py:"Fāngfǎ hěn duō, guīgēn dàodǐ háishi yào jiānchí."}],exercises:[{kind:"choice",q:"他屡次失败，___还是因为准备不足。",instr:"辨析",instrEn:"Pick the right one",body:"他屡次失败，___还是因为准备不足。",options:["一般来说","与此同时","归根到底","相比之下"],answer:2,explain:"“归根到底”用来指出最根本的原因，和“还是因为”正好搭配；“一般来说、与此同时、相比之下”都不是追究原因的说法。",explainEn:"归根到底 points to the root cause and fits 还是因为; the others do not introduce a basic cause."},{kind:"choice",q:"他们俩吵来吵去，归根到底___。",instr:"完成",instrEn:"Complete the sentence",body:"他们俩吵来吵去，归根到底___。",options:["昨天晚上又吵了一次","还是谁都不肯先让一步","吵架的声音越来越大","邻居们都听见了"],answer:1,explain:"“归根到底”后面要说出最根本的原因或本质；其他选项只是吵架的经过或表面情况。",explainEn:"归根到底 must lead to the root cause; the other options only describe the quarrel itself."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["归根到底，我明天早上八点出发。","归根到底，这是一个管理问题。","公司亏损的原因很多，归根到底是产品没有竞争力。","学外语没有捷径，归根到底要靠多练。"],answer:0,explain:"“归根到底”用于总结根本原因或结论，不能用来说一般的行程安排，应直接说“我明天早上八点出发”。",explainEn:"归根到底 sums up a root cause or conclusion, not a travel plan; just say 我明天早上八点出发."},{q:"翻译：In the final analysis, success depends on your own effort.",a:"归根到底，成功要靠自己的努力。",instr:"翻译",instrEn:"Translate",body:"In the final analysis, success depends on your own effort."}],note:"用于总结最根本的原因、本质或结论。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"guīgēn dàodǐ, + root cause / conclusion = in the final analysis, …",noteEn:"Sums up the most basic cause, nature or conclusion.",typeEn:"Parenthetical"}]},{num:32,title:"有时，不妨悲伤",points:[{id:"HSK6.32.1",name:"连词“哪怕”",pinyin:"nǎpà",type:"连词",explainEn:"Use 哪怕 to mean “even if”, often for an extreme or unfavorable condition.",structure:"哪怕 + 条件，也/还 + 结果",examples:[{zh:"哪怕只有一分钟，我也想见他。",en:"Even if it is only one minute, I still want to see him.",py:"Nǎpà zhǐyǒu yì fēnzhōng, wǒ yě xiǎng jiàn tā."},{zh:"哪怕失败，也要试一试。",en:"Even if we fail, we should try.",py:"Nǎpà shībài, yě yào shì yi shì."},{zh:"哪怕很忙，他也会给家里打电话。",en:"Even if he is very busy, he still calls home.",py:"Nǎpà hěn máng, tā yě huì gěi jiāli dǎ diànhuà."}],exercises:[{kind:"choice",q:"___明天真的下大雨，比赛也会照常进行。",instr:"辨析",instrEn:"Pick the right one",body:"___明天真的下大雨，比赛也会照常进行。",options:["尽管","只要","哪怕","既然"],answer:2,explain:"“哪怕……也”表示假设的极端条件，结果不变；“真的下大雨”只是假设，“尽管”说的是已经存在的事实，所以不能用。",explainEn:"哪怕…也 sets up a hypothetical extreme condition; 尽管 is for facts, and tomorrow's rain is only a supposition."},{kind:"choice",q:"哪怕___，我也要把这部电影看完。",instr:"完成",instrEn:"Complete the sentence",body:"哪怕___，我也要把这部电影看完。",options:["这部电影非常好看","明天正好放假","朋友推荐了很多次","要熬到凌晨两点"],answer:3,explain:"“哪怕”后面接让步的条件，即不利的情况；其他选项都是看电影的理由，不是让步。",explainEn:"哪怕 introduces an unfavourable condition one accepts; the other options are reasons, not concessions."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["哪怕再忙，他每天也要陪孩子读书。","哪怕路再远，我们就一定要赶到。","哪怕只有一线希望，我们也不会放弃。","哪怕别人都反对，她还是坚持自己的选择。"],answer:1,explain:"“哪怕”后面要用“也”呼应，不能用“就”，应改为“哪怕路再远，我们也一定要赶到”。",explainEn:"哪怕 pairs with 也, not 就; say 哪怕路再远，我们也一定要赶到."},{q:"翻译：Even if it takes ten years, I will finish writing this book.",a:"哪怕要花十年时间，我也要写完这本书。",instr:"翻译",instrEn:"Translate",body:"Even if it takes ten years, I will finish writing this book."}],note:"和“即使、即便”接近，口语和书面语都常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nǎpà + condition, yě/hái + result = even if …, still …",noteEn:"Close to 即使/即便; common in both speech and writing.",typeEn:"Conjunction"},{id:"HSK6.32.2",name:"转折连接语“反之”",pinyin:"fǎnzhī",type:"连接语",explainEn:"Use 反之 to mean “conversely / the opposite is also true”.",structure:"A；反之，B（与A相反）",examples:[{zh:"运动有助于健康；反之，长期不运动会带来问题。",en:"Exercise helps health; conversely, long-term inactivity causes problems.",py:"Yùndòng yǒuzhùyú jiànkāng; fǎnzhī, chángqī bú yùndòng huì dàilái wèntí."},{zh:"信任能改善关系，反之，不信任会让关系更差。",en:"Trust can improve a relationship; conversely, distrust makes it worse.",py:"Xìnrèn néng gǎishàn guānxi, fǎnzhī, bú xìnrèn huì ràng guānxi gèng chà."},{zh:"准备充分更容易成功；反之，准备不足风险更大。",en:"Good preparation makes success more likely; conversely, poor preparation increases risk.",py:"Zhǔnbèi chōngfèn gèng róngyì chénggōng; fǎnzhī, zhǔnbèi bùzú fēngxiǎn gèng dà."}],exercises:[{kind:"choice",q:"经常阅读能提高写作水平；___，很少阅读的人写起文章来往往比较吃力。",instr:"辨析",instrEn:"Pick the right one",body:"经常阅读能提高写作水平；___，很少阅读的人写起文章来往往比较吃力。",options:["总之","否则","反之","何况"],answer:2,explain:"后一句说的是与前一句相反的情况，应用“反之”；“否则”后面要直接说结果，“总之”是总结，“何况”是递进。",explainEn:"The second clause is the opposite case, so 反之; 否则 leads to a consequence, 总之 sums up, 何况 adds a stronger point."},{kind:"choice",q:"价格降低，需求通常会增加；反之，___。",instr:"完成",instrEn:"Complete the sentence",body:"价格降低，需求通常会增加；反之，___。",options:["价格上涨，需求往往会减少","价格降低，销量也会随之上升","需求增加，价格也就降低了","降价能吸引更多的顾客"],answer:0,explain:"“反之”后面要说与前文相反的情况，即涨价、需求减少；其他选项都是在重复同一方向。",explainEn:"反之 introduces the reverse case (prices up, demand down); the other options repeat the same direction."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["坚持锻炼的人身体更好；反之，缺少运动容易生病。","态度积极，事情往往更顺利；反之，则容易处处碰壁。","用心倾听能拉近距离；反之，随意打断别人会引起反感。","他学习很努力；反之，他的成绩也很好。"],answer:3,explain:"后一句是前一句的结果，不是相反情况，不能用“反之”，应改为“因此，他的成绩也很好”。",explainEn:"The second clause is a result, not the opposite case; use 因此 instead of 反之."},{q:"翻译：Conversely, poor preparation increases risk.",a:"反之，准备不足风险更大。",instr:"翻译",instrEn:"Translate",body:"Conversely, poor preparation increases risk."}],note:"“反之”连接与前文相反的情况，后面常有停顿。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A; fǎnzhī, B (the opposite of A) = A; conversely, B",noteEn:"反之 introduces the opposite of the previous situation and is usually followed by a pause.",typeEn:"Linking phrase"}]},{num:33,title:"怀念慢生活",points:[{id:"HSK6.33.1",name:"固定格式“A的A，B的B”",pinyin:"A de A, B de B",type:"列举结构",explainEn:"Use A的A，B的B to list different people/things doing or showing different things.",structure:"动词/形容词 + 的 + 同一动词/形容词，……",examples:[{zh:"下课以后，看书的看书，聊天的聊天。",en:"After class, some read and some chat.",py:"Xiàkè yǐhòu, kàn shū de kàn shū, liáotiān de liáotiān."},{zh:"进了果园，红的红，绿的绿，漂亮极了。",en:"In the orchard, some fruit is red and some green; it is beautiful.",py:"Jìnle guǒyuán, hóng de hóng, lǜ de lǜ, piàoliang jí le."},{zh:"周末大家忙自己的，运动的运动，休息的休息。",en:"On weekends, everyone does their own thing: some exercise, some rest.",py:"Zhōumò dàjiā máng zìjǐ de, yùndòng de yùndòng, xiūxi de xiūxi."}],exercises:[{kind:"choice",q:"广场上___，热闹极了。",instr:"辨析",instrEn:"Pick the right one",body:"广场上___，热闹极了。",options:["跳舞跳舞的，唱歌唱歌的","跳舞地跳舞，唱歌地唱歌","跳舞的跳舞，唱歌的唱歌","跳舞得跳舞，唱歌得唱歌"],answer:2,explain:"格式是“A的A，B的B”：前一个A加“的”指做这件事的人，后一个A是动作；不能用“地、得”，也不能把“的”放到最后。",explainEn:`The pattern is A的A: "those who A, A"; 的 sits between the two A's, not 地/得 and not at the end.`},{kind:"choice",q:"一放假，同学们走的走，___，宿舍一下子就空了。",instr:"完成",instrEn:"Complete the sentence",body:"一放假，同学们走的走，___，宿舍一下子就空了。",options:["学习的学习","睡觉的睡觉","回家的回家","聊天的聊天"],answer:2,explain:"“A的A，B的B”列出同时发生的不同情况，这里要和“宿舍空了”一致，只有“回家”会让人离开宿舍。",explainEn:"A的A，B的B lists what different people do; only going home fits the dorm becoming empty."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["放学后，操场上跑步的跑步，下棋的，热闹得很。","年夜饭桌上，喝酒的喝酒，聊天的聊天，热闹得很。","下了课，打球的打球，看书的看书。","市场里卖菜的卖菜，买菜的买菜，人来人往。"],answer:0,explain:"格式中的每一项都要重复动词，“下棋的”后面缺了“下棋”，应改为“下棋的下棋”。",explainEn:"Each item must repeat its verb; 下棋的 is missing the second 下棋: 下棋的下棋."},{q:"翻译：Some exercise and some rest.",a:"运动的运动，休息的休息。",instr:"翻译",instrEn:"Translate",body:"Some exercise and some rest."}],note:"常用于口语，把同一场景中的不同情况并列列出来。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Verb/Adj + de + same Verb/Adj, … = some …, some … (listing what everyone is doing)",noteEn:"Common in speech; lists the different things going on in the same scene side by side.",typeEn:"Enumeration"},{id:"HSK6.33.2",name:"副词“一时”",pinyin:"yīshí",type:"副词",explainEn:"Use 一时 to mean “for a short time / temporarily”; repeated 一时…一时… can show alternating states.",structure:"一时 + 动词/状态；一时A，一时B",examples:[{zh:"这个名字我一时想不起来。",en:"I cannot remember this name for the moment.",py:"Zhège míngzi wǒ yìshí xiǎng bu qǐlái."},{zh:"听到这个消息，他一时不知道说什么。",en:"Hearing the news, he did not know what to say for a moment.",py:"Tīngdào zhège xiāoxi, tā yìshí bù zhīdào shuō shénme."},{zh:"天气一时晴，一时雨。",en:"The weather is sunny one moment and rainy the next.",py:"Tiānqì yìshí qíng, yìshí yǔ."}],exercises:[{kind:"choice",q:"他___糊涂，签了那份合同，后悔了好多年。",instr:"辨析",instrEn:"Pick the right one",body:"他___糊涂，签了那份合同，后悔了好多年。",options:["暂时","顿时","一时","同时"],answer:2,explain:"“一时糊涂”指短时间判断失误，常带来后悔的结果；“暂时”表示有意先这样以后会变，“顿时”要接在某个诱因之后表示立刻，“同时”表示并列。",explainEn:'一时糊涂 is a momentary lapse that leads to regret; 暂时 means "for the time being", 顿时 needs a trigger before it, and 同时 means "at the same time".'},{kind:"choice",q:"这只是一时的困难，___。",instr:"完成",instrEn:"Complete the sentence",body:"这只是一时的困难，___。",options:["恐怕一辈子都解决不了","熬过去就好了","已经持续了好多年","以后会越来越严重"],answer:1,explain:"“一时的”表示时间很短、不会长久，后面应该说很快会过去；其他选项都表示长期存在。",explainEn:"一时的 means short-lived, so the trouble should pass; the other options describe something long-lasting."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["面对记者的提问，他一时不知道怎么回答。","这只是一时的冲动，你别当真。","这个地址我一时想不起来，等会儿告诉你。","我在这家公司一时工作了十年。"],answer:3,explain:"“一时”表示短时间，不能和“十年”这样的长时段连用，应改为“我在这家公司工作了十年”。",explainEn:'一时 means "for a moment" and clashes with ten years; say 我在这家公司工作了十年.'},{q:"翻译：He did not know what to say for a moment.",a:"他一时不知道说什么。",instr:"翻译",instrEn:"Translate",body:"He did not know what to say for a moment."}],note:"既可表示短时间，也可重复使用表示状态交替。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yìshí + Verb/state; yìshí A, yìshí B = for a moment …; now A, now B",noteEn:"Can mean a short time, or, repeated, alternating states.",typeEn:"Adverb"}]},{num:34,title:"为文物而生的人",points:[{id:"HSK6.34.1",name:"连词“尚且”",pinyin:"shàngqiě",type:"连词",explainEn:"Use 尚且 in the first clause to say “even…”, then show that another case is even more obvious.",structure:"A + 尚且 + 谓语，何况/更 + B",examples:[{zh:"这么简单的问题他尚且不会，何况更难的呢？",en:"He cannot even do such an easy question, let alone a harder one.",py:"Zhème jiǎndān de wèntí tā shàngqiě bú huì, hékuàng gèng nán de ne?"},{zh:"成年人尚且会紧张，孩子就更不用说了。",en:"Even adults get nervous, let alone children.",py:"Chéngniánrén shàngqiě huì jǐnzhāng, háizi jiù gèng búyòng shuō le."},{zh:"经济好的时候公司尚且困难，现在就更难了。",en:"The company struggled even in good times; now it is even harder.",py:"Jīngjì hǎo de shíhou gōngsī shàngqiě kùnnan, xiànzài jiù gèng nán le."}],exercises:[{kind:"choice",q:"这么重的箱子，两个大人___搬不动，一个孩子怎么可能搬得动？",instr:"辨析",instrEn:"Pick the right one",body:"这么重的箱子，两个大人___搬不动，一个孩子怎么可能搬得动？",options:["况且","何况","而且","尚且"],answer:3,explain:"“尚且”放在前一分句的谓语前，先举一个明显的例子，后面再推出更进一层的结论；“况且、何况、而且”都不能用在这个位置。",explainEn:"尚且 goes before the predicate of the first clause to give the obvious case; 况且, 何况 and 而且 cannot sit here."},{kind:"choice",q:"专业人士尚且会出错，___？",instr:"完成",instrEn:"Complete the sentence",body:"专业人士尚且会出错，___？",options:["何况那些资深专家呢","何况是经验丰富的老师呢","何况是行业里的权威呢","何况我们这些新手呢"],answer:3,explain:"“A尚且……，何况B”中，B要比A更容易出现这种情况；比专业人士更容易出错的是新手，而不是专家或权威。",explainEn:"In A尚且…，何况B, B must be an even likelier case; beginners, not experts, are more likely to make mistakes."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["孩子尚且能做到，何况大人更做不到。","他自己的事尚且处理不好，哪有精力管别人？","在城市里找工作尚且不容易，在小镇上就更难了。","平时尚且堵车，节假日就更不用说了。"],answer:0,explain:"“尚且”后面推出的结论要和前面同一方向而且更进一步，应改为“孩子尚且能做到，大人就更应该能做到了”。",explainEn:"The conclusion after 尚且 must go further in the same direction: 大人就更应该能做到了."},{q:"翻译：He cannot even do this easy question, let alone a harder one.",a:"这个简单问题他尚且不会，何况更难的。",instr:"翻译",instrEn:"Translate",body:"He cannot even do this easy question, let alone a harder one."}],note:"前句提出一个已经很明显的例子，后句进一步推出更强结论。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + shàngqiě + predicate, hékuàng/gèng + B = even A …, let alone B",noteEn:"The first clause gives an already obvious example; the second draws an even stronger conclusion.",typeEn:"Conjunction"},{id:"HSK6.34.2",name:"介词/构词成分“当”",pinyin:"dāng",type:"介词/构词成分",explainEn:"Use 当 in words such as 当时、当地、当今、当场 to mean “at that time/place / present / on the spot”.",structure:"当 + 时/地/今/场……",examples:[{zh:"我至今还记得当时的情况。",en:"I still remember the situation at that time.",py:"Wǒ zhìjīn hái jìde dāngshí de qíngkuàng."},{zh:"这件事在当地很有名。",en:"This matter is well known locally.",py:"Zhè jiàn shì zài dāngdì hěn yǒumíng."},{zh:"他当场承认了错误。",en:"He admitted his mistake on the spot.",py:"Tā dāngchǎng chéngrènle cuòwù."}],exercises:[{kind:"choice",q:"这家餐馆用的蔬菜都是从___农民那里买来的。",instr:"辨析",instrEn:"Pick the right one",body:"这家餐馆用的蔬菜都是从___农民那里买来的。",options:["当时","当地","当场","当今"],answer:1,explain:"“当地”指事情发生的那个地方，修饰“农民”最合适；“当时”指时间，“当场”指就在现场，“当今”指现在这个时代。",explainEn:'当地 means "local", fitting 农民; 当时 is "at that time", 当场 "on the spot", 当今 "nowadays".'},{kind:"choice",q:"记者问他是否知情，他当场___。",instr:"完成",instrEn:"Complete the sentence",body:"记者问他是否知情，他当场___。",options:["事后否认了这种说法","一口否认了这种说法","第二天否认了这种说法","几天后否认了这种说法"],answer:1,explain:"“当场”表示就在那个场合、那个时候，不能再和“事后、第二天、几天后”这类晚一些的时间连用。",explainEn:'当场 means right there and then, so it cannot go with "afterwards", "the next day" or "a few days later".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他是当今最有名的作家之一。","当时我还小，什么都不懂。","我们明天当时出发。","这道菜在当地很受欢迎。"],answer:2,explain:"“当时”指过去某个时候，不能用于将来，应改为“我们明天出发”或“我们明天准时出发”。",explainEn:"当时 refers to a past moment and cannot be used for the future; say 我们明天准时出发."},{q:"翻译：I was too young at the time to understand what my father said.",a:"当时我年纪太小，听不懂父亲的话。",instr:"翻译",instrEn:"Translate",body:"I was too young at the time to understand what my father said."}],note:"教材重点是“当+时间/地点成分”的用法，如当时、当地、当今、当场。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dāng + shí/dì/jīn/chǎng … = at that time / local / nowadays / on the spot",noteEn:"The textbook focuses on 当 + time/place elements, as in 当时, 当地, 当今, 当场.",typeEn:"Preposition / Word-forming element"}]},{num:35,title:"走近木版年画",points:[{id:"HSK6.35.1",name:"副词“终究”",pinyin:"zhōngjiū",type:"副词",explainEn:"Use 终究 to mean “after all / in the end”; it stresses that the final result or nature will not change.",structure:"主语 + 终究 + 结果/判断",examples:[{zh:"问题终究会解决。",en:"The problem will be solved in the end.",py:"Wèntí zhōngjiū huì jiějué."},{zh:"假的终究是假的。",en:"What is false is false after all.",py:"Jiǎ de zhōngjiū shì jiǎ de."},{zh:"再困难的阶段终究会过去。",en:"Even a very difficult period will eventually pass.",py:"Zài kùnnan de jiēduàn zhōngjiū huì guòqu."}],exercises:[{kind:"choice",q:"不管他编得多么圆，谎言___会被揭穿。",instr:"辨析",instrEn:"Pick the right one",body:"不管他编得多么圆，谎言___会被揭穿。",options:["究竟","终于","竟然","终究"],answer:3,explain:"“终究”表示最终必然如此，正和“不管……”配合说将来的结果；“终于”用于已经实现的结果，“究竟”多用于追问，“竟然”表示出乎意料，都不合语境。",explainEn:'终究 means "in the end, inevitably" and works with 会; 终于 is for results already reached, 究竟 is for questions, 竟然 for surprise.'},{kind:"choice",q:"不管他现在多么风光，靠作弊得来的成绩终究___。",instr:"完成",instrEn:"Complete the sentence",body:"不管他现在多么风光，靠作弊得来的成绩终究___。",options:["是靠不住的","让人十分羡慕","会越来越好","值得大家学习"],answer:0,explain:"“终究”强调最后必然的结果或本质；前面“不管……多么风光”是让步，后面应说出不可改变的负面结局。",explainEn:'终究 stresses an inevitable final outcome; after "however glorious now", it must state the unavoidable bad end.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他终究还是个孩子，别对他太严格。","纸终究包不住火。","你骗得了别人，终究骗不了自己。","你终究去过长城吗？"],answer:3,explain:"“终究”不用于提问，追问时应该用“究竟”，可改为“你究竟去没去过长城？”。",explainEn:"终究 is not used in questions; to press for an answer use 究竟: 你究竟去没去过长城？"},{q:"翻译：The truth will come out sooner or later.",a:"真相终究会水落石出。",instr:"翻译",instrEn:"Translate",body:"The truth will come out sooner or later."}],note:"强调最终结果、本质或不可否认的事实。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Subject + zhōngjiū + result/judgment = after all / in the end …",noteEn:"Stresses the final result, the true nature, or an undeniable fact.",typeEn:"Adverb"},{id:"HSK6.35.2",name:"固定格式“愈……愈……”",pinyin:"yù ... yù ...",type:"程度结构",explainEn:"Use 愈…愈… to mean “the more…, the more…”. It is more formal than 越…越….",structure:"愈 + A，愈 + B",examples:[{zh:"事情愈复杂，愈需要冷静。",en:"The more complicated the matter, the more calm we need to be.",py:"Shìqing yù fùzá, yù xūyào lěngjìng."},{zh:"年纪愈大，愈重视健康。",en:"The older one gets, the more one values health.",py:"Niánjì yù dà, yù zhòngshì jiànkāng."},{zh:"了解得愈多，问题反而愈多。",en:"The more you understand, the more questions you may have.",py:"Liǎojiě de yù duō, wèntí fǎn'ér yù duō."}],exercises:[{kind:"choice",q:"这种病发现得愈早，治愈的希望___。",instr:"辨析",instrEn:"Pick the right one",body:"这种病发现得愈早，治愈的希望___。",options:["愈来愈大","愈大","更加大","愈是大"],answer:1,explain:"前面用“愈早”，后面要用“愈+形容词”呼应；“愈来愈”表示随时间不断变化，不和前面的“愈”配对，“愈是”要用在前一分句，“更加大”既不呼应也不通顺。",explainEn:'After 愈早 the second clause needs 愈 + adjective; 愈来愈 means "more and more over time", 愈是 belongs in the first clause, and 更加大 neither pairs nor reads well.'},{kind:"choice",q:"他愈___，大家愈不相信他。",instr:"完成",instrEn:"Complete the sentence",body:"他愈___，大家愈不相信他。",options:["拼命解释","解释清楚了","解释了一次","已经解释过"],answer:0,explain:"“愈……愈……”的前项要能不断加深，“拼命解释”可以；“解释清楚了、解释了一次、已经解释过”都是完成的一次性动作，无法随之变化。",explainEn:"The first part of 愈…愈 must be able to keep increasing; 拼命解释 works, but completed one-off actions cannot vary."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他愈想愈觉得不对劲。","天气愈冷，来滑雪的人愈多。","雨愈下大，我们愈着急。","问题拖得愈久，愈难解决。"],answer:2,explain:"“愈”要直接放在形容词或动词前，“愈下大”语序不对，应改为“雨下得愈大，我们愈着急”。",explainEn:"愈 must stand right before the adjective; say 雨下得愈大，我们愈着急."},{q:"翻译：The more I read this book, the more I like it.",a:"这本书我愈读愈喜欢。",instr:"翻译",instrEn:"Translate",body:"The more I read this book, the more I like it."}],note:"和“越……越……”基本相同，但书面语色彩更强。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yù + A, yù + B = the more A, the more B",noteEn:"Basically the same as 越……越……, but more formal.",typeEn:"Degree structure"}]},{num:36,title:"中国古代书院",points:[{id:"HSK6.36.1",name:"副词“一经”",pinyin:"yījīng",type:"副词/条件结构",explainEn:"Use 一经 to mean “once”, showing that once an action happens, a result will follow.",structure:"一经 + 动作，就/便 + 结果",examples:[{zh:"这个规定一经公布，就立即生效。",en:"Once this rule is announced, it takes effect immediately.",py:"Zhège guīdìng yìjīng gōngbù, jiù lìjí shēngxiào."},{zh:"产品一经售出，不能随意退换。",en:"Once the product is sold, it cannot be returned freely.",py:"Chǎnpǐn yìjīng shòuchū, bù néng suíyì tuìhuàn."},{zh:"消息一经确认，我们就通知大家。",en:"Once the news is confirmed, we will inform everyone.",py:"Xiāoxi yìjīng quèrèn, wǒmen jiù tōngzhī dàjiā."}],exercises:[{kind:"choice",q:"合同___双方签字，便具有法律效力。",instr:"辨析",instrEn:"Pick the right one",body:"合同___双方签字，便具有法律效力。",options:["一经","已经","曾经","经常"],answer:0,explain:"“一经……便……”表示只要经过某个动作就马上产生结果；“已经、曾经、经常”都不能和“便”构成这种条件关系。",explainEn:'一经…便… means "once…, then…"; 已经, 曾经 and 经常 cannot form this condition with 便.'},{kind:"choice",q:"这项发明一经问世，___。",instr:"完成",instrEn:"Complete the sentence",body:"这项发明一经问世，___。",options:["三十年后才有人注意","却一直没有人知道","很多年都无人问津","立刻受到了广泛关注"],answer:3,explain:"“一经”表示一出现就马上有结果，后面常用“就、便”；“三十年后才、一直没有、很多年都”与“马上”相反。",explainEn:'一经 means the result follows at once (就/便); "only after thirty years" or "nobody for years" contradicts it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["申请一经批准，我们会立即通知您。","这首歌一经推出，便大受欢迎。","他一经吃完饭了。","错误一经发现，必须马上改正。"],answer:2,explain:"“一经”是条件，后面要有结果分句，不能代替“已经”，应改为“他已经吃完饭了”。",explainEn:"一经 sets a condition and needs a result clause; here it should be 已经: 他已经吃完饭了."},{q:"翻译：Once the plan is approved, construction will start right away.",a:"方案一经批准，就立即开始施工。",instr:"翻译",instrEn:"Translate",body:"Once the plan is approved, construction will start right away."}],note:"较正式，常用于规则、新闻、说明等。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yìjīng + action, jiù/biàn + result = once …, then …",noteEn:"Fairly formal; common in rules, news and instructions.",typeEn:"Adverb / Conditional"},{id:"HSK6.36.2",name:"介词“本着 + 名词”",pinyin:"běnzhe + míngcí",type:"介词结构",explainEn:"Use 本着 + noun to mean “following / based on” a principle, spirit, purpose, or attitude.",structure:"本着 + 原则/精神/宗旨/态度 + 动词",examples:[{zh:"我们本着公平的原则处理问题。",en:"We handle the issue following the principle of fairness.",py:"Wǒmen běnzhe gōngpíng de yuánzé chǔlǐ wèntí."},{zh:"公司本着为客户负责的态度提供服务。",en:"The company provides service with a responsible attitude toward customers.",py:"Gōngsī běnzhe wèi kèhù fùzé de tàidu tígōng fúwù."},{zh:"双方本着合作精神继续讨论。",en:"Both sides continued discussions in a spirit of cooperation.",py:"Shuāngfāng běnzhe hézuò jīngshén jìxù tǎolùn."}],exercises:[{kind:"choice",q:"我们应该___实事求是的态度对待这个问题。",instr:"辨析",instrEn:"Pick the right one",body:"我们应该___实事求是的态度对待这个问题。",options:["本着","按照","依照","根据"],answer:0,explain:"“本着”常和“态度、精神、原则”等抽象名词搭配；“按照、依照、根据”后面多接规定、计划、材料，不说“按照……的态度”。",explainEn:"本着 collocates with 态度/精神/原则; 按照, 依照 and 根据 take rules, plans or data, not an attitude."},{kind:"choice",q:"双方本着___，顺利签订了合作协议。",instr:"完成",instrEn:"Complete the sentence",body:"双方本着___，顺利签订了合作协议。",options:["一份详细的合同","公司提供的数据","互利共赢的原则","律师的具体意见"],answer:2,explain:"“本着”后面要接“原则、精神、态度”等抽象名词；合同、数据、意见是具体材料，应该用“根据、按照”。",explainEn:"本着 takes abstract nouns like 原则; contracts, data and advice are concrete and go with 根据/按照."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们本着地图找到了那家餐厅。","本着对患者负责的精神，医生反复核对了检查结果。","我们本着节约的原则安排这次活动。","本着自愿的原则，大家可以选择参加或不参加。"],answer:0,explain:"“本着”只接原则、精神等抽象名词，“地图”是具体东西，应改为“我们按照地图找到了那家餐厅”。",explainEn:"本着 only takes abstract nouns; a map is concrete, so say 按照地图."},{q:"翻译：Taking an open attitude, the company listened carefully to its customers' suggestions.",a:"公司本着开放的态度，认真听取了顾客的建议。",instr:"翻译",instrEn:"Translate",body:"Taking an open attitude, the company listened carefully to its customers' suggestions."}],note:"后面常接“原则、精神、宗旨、态度、方针、观点”等抽象名词。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"běnzhe + principle/spirit/aim/attitude + Verb = in line with … , do …",noteEn:"Usually followed by abstract nouns such as 原则, 精神, 宗旨, 态度, 方针, 观点.",typeEn:"Prep. phrase"}]},{num:37,title:"警察的故事",points:[{id:"HSK6.37.1",name:"固定格式“为……起见”",pinyin:"wèi ... qǐjiàn",type:"目的结构",explainEn:"Use 为…起见 to mean “for the sake of / in order to”. It is formal.",structure:"为 + 名词/动词/形容词 + 起见，主句",examples:[{zh:"为安全起见，请系好安全带。",en:"For safety, please fasten your seat belt.",py:"Wèi ānquán qǐjiàn, qǐng jìhǎo ānquándài."},{zh:"为方便起见，我们把资料放在网上。",en:"For convenience, we put the materials online.",py:"Wèi fāngbiàn qǐjiàn, wǒmen bǎ zīliào fàng zài wǎng shang."},{zh:"为保险起见，你最好再检查一遍。",en:"To be safe, you had better check again.",py:"Wèi bǎoxiǎn qǐjiàn, nǐ zuìhǎo zài jiǎnchá yí biàn."}],exercises:[{kind:"choice",q:"为稳妥___，我们最好先签一份书面协议。",instr:"辨析",instrEn:"Pick the right one",body:"为稳妥___，我们最好先签一份书面协议。",options:["看来","来说","起见","而言"],answer:2,explain:"固定格式是“为……起见”，表示为了达到某种目的；“看来、来说、而言”不能和“为”构成表示目的的格式。",explainEn:'The fixed frame is 为…起见 ("for the sake of…"); 看来, 来说 and 而言 do not combine with 为 to express purpose.'},{kind:"choice",q:"为谨慎起见，___。",instr:"完成",instrEn:"Complete the sentence",body:"为谨慎起见，___。",options:["我们决定再请专家复查一遍","这件事已经很危险了","他是一个很谨慎的人","大家都觉得没什么问题"],answer:0,explain:"“为……起见”后面的主句要说为此采取的措施；其他选项只是描述情况或人，没有采取行动。",explainEn:"为…起见 must be followed by the step taken for that purpose; the other options just describe a situation."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["为公平起见，比赛结果由三位裁判共同决定。","为保险起见，出门前我又检查了一遍门窗。","为慎重起见，公司推迟了新产品的发布。","为赚钱起见，他每天打两份工。"],answer:3,explain:"“为……起见”只和安全、方便、慎重等抽象考虑搭配，不能接具体目标，应改为“为了赚钱，他每天打两份工”。",explainEn:"为…起见 goes with abstract considerations like safety or convenience, not a concrete goal; say 为了赚钱，他每天打两份工."},{q:"翻译：For safety's sake, children must be accompanied by an adult.",a:"为安全起见，儿童必须由成人陪同。",instr:"翻译",instrEn:"Translate",body:"For safety's sake, children must be accompanied by an adult."}],note:"多用于正式建议、说明，强调采取措施的目的。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèi + Noun/Verb/Adj + qǐjiàn, main clause = for the sake of …, …",noteEn:"Mostly in formal advice or explanations; stresses the purpose of the measure taken.",typeEn:"Purpose structure"},{id:"HSK6.37.2",name:"副词“暂且”",pinyin:"zànqiě",type:"副词",explainEn:"Use 暂且 to mean “for the time being / for now”.",structure:"暂且 + 动词/判断",examples:[{zh:"这个问题暂且不谈。",en:"Let us not discuss this issue for now.",py:"Zhège wèntí zànqiě bù tán."},{zh:"没有更好的办法，我们暂且这样做。",en:"There is no better way, so we will do this for now.",py:"Méiyǒu gèng hǎo de bànfǎ, wǒmen zànqiě zhèyàng zuò."},{zh:"结果还没出来，暂且不能下结论。",en:"The result is not out yet, so we cannot conclude for now.",py:"Jiéguǒ hái méi chūlai, zànqiě bù néng xià jiélùn."}],exercises:[{kind:"choice",q:"别的问题___放一放，我们先讨论最紧急的这件。",instr:"辨析",instrEn:"Pick the right one",body:"别的问题___放一放，我们先讨论最紧急的这件。",options:["尚且","并且","况且","暂且"],answer:3,explain:"“暂且”表示暂时先这样处理，修饰“放一放”；“尚且、并且、况且”都是关联性词语，不能这样修饰动词。",explainEn:'暂且 means "for the time being" and modifies 放一放; 尚且, 并且 and 况且 are connectors and cannot.'},{kind:"choice",q:"这个方案暂且这样定下来，___。",instr:"完成",instrEn:"Complete the sentence",body:"这个方案暂且这样定下来，___。",options:["以后再也不能修改了","永远按照这个执行","今后不必再讨论了","等有了新情况再调整"],answer:3,explain:"“暂且”表示暂时如此，以后可能改变；“再也不能、永远、不必再”都表示定死不变，和“暂且”矛盾。",explainEn:'暂且 means "for now", open to change; "never again", "forever" and "no need to discuss again" contradict it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你暂且住在我家，等找到房子再搬。","这件事暂且不提，先吃饭吧。","他暂且在这家公司工作了一辈子。","天色已晚，我们暂且在这里休息一夜。"],answer:2,explain:"“暂且”表示短时间先这样，不能和“一辈子”连用，应改为“他在这家公司工作了一辈子”。",explainEn:'暂且 means "for the time being" and clashes with a whole lifetime; drop it.'},{q:"翻译：We will do this for now.",a:"我们暂且这样做。",instr:"翻译",instrEn:"Translate",body:"We will do this for now."}],note:"表示暂时先这样处理，以后可能改变。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zànqiě + Verb/judgment = for now / for the time being",noteEn:"Handle it this way for now; it may change later.",typeEn:"Adverb"}]},{num:38,title:"慧眼捕捉商机",points:[{id:"HSK6.38.1",name:"副词“屡次”",pinyin:"lǚcì",type:"副词",explainEn:"Use 屡次 to mean “repeatedly / many times”, often for notable or negative events.",structure:"屡次 + 动词",examples:[{zh:"他屡次迟到，受到了批评。",en:"He was late repeatedly and was criticized.",py:"Tā lǚcì chídào, shòudàole pīpíng."},{zh:"这个问题屡次出现。",en:"This problem has appeared repeatedly.",py:"Zhège wèntí lǚcì chūxiàn."},{zh:"我们屡次提醒他注意安全。",en:"We repeatedly reminded him to pay attention to safety.",py:"Wǒmen lǚcì tíxǐng tā zhùyì ānquán."}],exercises:[{kind:"choice",q:"他___违反交通规则，被吊销了驾照。",instr:"辨析",instrEn:"Pick the right one",body:"他___违反交通规则，被吊销了驾照。",options:["依次","屡次","历次","其次"],answer:1,explain:"“屡次”表示同类事情一次又一次发生，可直接修饰动词；“依次”指按顺序，“历次”只能修饰名词（如“历次比赛”），“其次”指第二。",explainEn:'屡次 means "repeatedly" and modifies verbs; 依次 is "in order", 历次 only modifies nouns, 其次 means "next".'},{kind:"choice",q:"这家工厂屡次___，最终被责令停业。",instr:"完成",instrEn:"Complete the sentence",body:"这家工厂屡次___，最终被责令停业。",options:["在去年三月正式成立","被群众举报污染问题","第一次通过了安全检查","只接受过一次检查"],answer:1,explain:"“屡次”要求动作多次重复；“成立、第一次、只……一次”都是一次性的，不能和“屡次”连用。",explainEn:'屡次 needs a repeated action; being founded, "the first time" and "only once" are one-off events.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他屡次打破全国纪录。","这位作家的作品屡次获奖。","我以后会屡次来看你。","我们屡次提出意见，但一直没有回应。"],answer:2,explain:"“屡次”说的是已经多次发生的事，不能用于将来的打算，应改为“我以后会常来看你”。",explainEn:"屡次 describes things that have already happened many times, not future plans; say 我以后会常来看你."},{q:"翻译：We repeatedly reminded him.",a:"我们屡次提醒他。",instr:"翻译",instrEn:"Translate",body:"We repeatedly reminded him."}],note:"比“多次”更书面，常强调同类事情反复发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"lǚcì + Verb = repeatedly …",noteEn:"More formal than 多次; stresses that the same kind of thing keeps happening.",typeEn:"Adverb"},{id:"HSK6.38.2",name:"“依据”表示根据",pinyin:"yījù",type:"名词/动词/介词",explainEn:"Use 依据 to mean “basis / according to / base on”.",structure:"依据 + 材料/规则 + 动词；以……为依据",examples:[{zh:"我们依据数据做出了判断。",en:"We made the judgment based on data.",py:"Wǒmen yījù shùjù zuòchūle pànduàn."},{zh:"这个结论有充分的事实依据。",en:"This conclusion has sufficient factual basis.",py:"Zhège jiélùn yǒu chōngfèn de shìshí yījù."},{zh:"请以合同为依据处理这个问题。",en:"Please handle this issue based on the contract.",py:"Qǐng yǐ hétong wéi yījù chǔlǐ zhège wèntí."}],exercises:[{kind:"choice",q:"这所大学录取新生，主要以高考成绩为___。",instr:"辨析",instrEn:"Pick the right one",body:"这所大学录取新生，主要以高考成绩为___。",options:["依靠","依赖","依据","依照"],answer:2,explain:"“以……为依据”表示把某种材料当作判断的根据，录取看成绩正是这样；“依靠、依赖”指靠别人或某物来支持、生存，“依照”是介词，不能放在“为”后作宾语。",explainEn:"以…为依据 names the basis for a judgment, as grades are for admission; 依靠/依赖 mean relying on support, and 依照 is a preposition that cannot follow 为."},{kind:"choice",q:"这份报告以___为依据，得出了可靠的结论。",instr:"完成",instrEn:"Complete the sentence",body:"这份报告以___为依据，得出了可靠的结论。",options:["大量调查数据","一种乐观的心情","作者的个人愿望","大家的随口议论"],answer:0,explain:"“以……为依据”要接能作为根据的事实材料；心情、愿望、随口议论都不能支撑“可靠的结论”。",explainEn:"以…为依据 needs factual grounds; a mood, a wish or casual talk cannot support a reliable conclusion."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们以合同依据处理这件事。","选拔人才要以能力为依据。","他的说法缺乏科学依据。","依据有关规定，这笔费用由公司承担。"],answer:0,explain:"格式是“以……为依据”，句中缺了“为”，应改为“我们以合同为依据处理这件事”。",explainEn:"The frame is 以…为依据; 为 is missing: 我们以合同为依据处理这件事."},{q:"翻译：This conclusion has a factual basis.",a:"这个结论有事实依据。",instr:"翻译",instrEn:"Translate",body:"This conclusion has a factual basis."}],note:"既可作名词，也可作动词/介词性用法；常用于正式论证。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yījù + material/rule + Verb; yǐ … wéi yījù = according to …; take … as the basis",noteEn:"Works as a noun or as a verb/preposition; common in formal argument.",typeEn:"Noun / Verb / Preposition"}]},{num:39,title:"互联网时代的生活",points:[{id:"HSK6.39.1",name:"副词/形容词“任意”",pinyin:"rènyì",type:"副词/形容词",explainEn:"Use 任意 to mean “any / freely / at will”.",structure:"任意 + 动词；任意 + 名词",examples:[{zh:"你可以任意选择一种方式。",en:"You may freely choose any method.",py:"Nǐ kěyǐ rènyì xuǎnzé yì zhǒng fāngshì."},{zh:"不能任意修改数据。",en:"You cannot change the data at will.",py:"Bù néng rènyì xiūgǎi shùjù."},{zh:"从任意一个入口都可以进去。",en:"You can enter through any entrance.",py:"Cóng rènyì yí ge rùkǒu dōu kěyǐ jìnqu."}],exercises:[{kind:"choice",q:"展厅里的展品可以___拍照，但不能使用闪光灯。",instr:"辨析",instrEn:"Pick the right one",body:"展厅里的展品可以___拍照，但不能使用闪光灯。",options:["任何","任意","任凭","肆意"],answer:1,explain:"“任意”可以作状语修饰“拍照”，表示不受限制；“任何”只能修饰名词，“任凭”是“不管、听凭”，“肆意”带贬义，指毫无顾忌地做坏事。",explainEn:'任意 can modify 拍照 meaning "freely"; 任何 only modifies nouns, 任凭 means "no matter / let", and 肆意 is negative, used for reckless wrongdoing.'},{kind:"choice",q:"公共绿地属于大家，任何人都不能任意___。",instr:"完成",instrEn:"Complete the sentence",body:"公共绿地属于大家，任何人都不能任意___。",options:["保护花草","欣赏风景","砍伐树木","呼吸空气"],answer:2,explain:"“不能任意……”表示不能不受约束地做某事，后面应接需要限制的行为；保护、欣赏、呼吸都无须禁止。",explainEn:"不能任意… forbids doing something unchecked, so it needs a harmful act; protecting or enjoying needs no ban."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个问题任意人都能回答。","这些座位可以任意选择。","公司不能任意解雇员工。","在三角形内任意取一点。"],answer:0,explain:"修饰“人”表示“不论哪个人”应该用“任何”，应改为“这个问题任何人都能回答”。",explainEn:'To mean "anyone" before 人, use 任何: 这个问题任何人都能回答.'},{q:"翻译：You may choose any two of the following topics.",a:"你可以从下列题目中任意选择两个。",instr:"翻译",instrEn:"Translate",body:"You may choose any two of the following topics."}],note:"表示没有特别限制，可自由选择；正式语体常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"rènyì + Verb; rènyì + Noun = … freely / at will; any …",noteEn:"No particular limit — free to choose; common in formal style.",typeEn:"Adverb / Adjective"},{id:"HSK6.39.2",name:"副词“尚未”",pinyin:"shàngwèi",type:"副词",explainEn:"Use 尚未 to mean “have not yet”. It is more formal than 还没.",structure:"尚未 + 动词",examples:[{zh:"结果尚未公布。",en:"The result has not yet been announced.",py:"Jiéguǒ shàngwèi gōngbù."},{zh:"这个问题尚未解决。",en:"This problem has not yet been solved.",py:"Zhège wèntí shàngwèi jiějué."},{zh:"双方尚未达成一致。",en:"The two sides have not yet reached agreement.",py:"Shuāngfāng shàngwèi dáchéng yízhì."}],exercises:[{kind:"choice",q:"截至目前，事故原因___查明，调查仍在进行中。",instr:"辨析",instrEn:"Pick the right one",body:"截至目前，事故原因___查明，调查仍在进行中。",options:["尚且","尚未","早已","未必"],answer:1,explain:"“尚未”表示到现在还没有，以后可能会有，正合“调查仍在进行”；“早已”与之矛盾，“未必”表示不一定，“尚且”是关联词。",explainEn:'尚未 means "not yet", fitting an ongoing investigation; 早已 contradicts it, 未必 means "not necessarily", and 尚且 is a connective.'},{kind:"choice",q:"新校区尚未完工，___。",instr:"完成",instrEn:"Complete the sentence",body:"新校区尚未完工，___。",options:["已经有学生住进去两年了","去年就举行了竣工仪式","预计明年秋天投入使用","现在已经全部交付使用"],answer:2,explain:"“尚未”表示到现在还没完成，后面只能说将来的安排；其他选项都表示已经完工。",explainEn:'尚未 means "not finished yet", so only a future plan fits; the others say it is already done.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["此案尚未结案，请勿随意评论。","这项技术尚未成熟。","他尚未成年，不能单独签合同。","这个问题尚未解决了。"],answer:3,explain:"“尚未”表示还没有，后面不能加表示完成的“了”，应改为“这个问题尚未解决”。",explainEn:"尚未 (not yet) cannot take completion 了; say 这个问题尚未解决."},{q:"翻译：The two companies have not yet signed the contract.",a:"两家公司尚未签订合同。",instr:"翻译",instrEn:"Translate",body:"The two companies have not yet signed the contract."}],note:"常见于新闻、报告、正式说明。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shàngwèi + Verb = has not yet …",noteEn:"Common in news, reports and formal statements.",typeEn:"Adverb"}]},{num:40,title:"人类超能力会改变世界纪录吗",points:[{id:"HSK6.40.1",name:"固定格式“（把）……放在眼里”",pinyin:"(bǎ) ... fàng zài yǎnlǐ",type:"固定格式",explainEn:"Use （把）…放在眼里 to mean “take…seriously / consider…important”, often in the negative.",structure:"把 + 人/事 + 放在眼里；不把……放在眼里",examples:[{zh:"他根本没把这个困难放在眼里。",en:"He did not take this difficulty seriously at all.",py:"Tā gēnběn méi bǎ zhège kùnnan fàng zài yǎn li."},{zh:"你不能不把安全放在眼里。",en:"You cannot ignore safety.",py:"Nǐ bù néng bù bǎ ānquán fàng zài yǎn li."},{zh:"他太骄傲，谁都不放在眼里。",en:"He is so proud that he looks down on everyone.",py:"Tā tài jiāo'ào, shéi dōu bú fàng zài yǎn li."}],exercises:[{kind:"choice",q:"这点小困难，他根本___。",instr:"辨析",instrEn:"Pick the right one",body:"这点小困难，他根本___。",options:["不放眼里在","放不在眼里","不放在眼里","不在眼里放"],answer:2,explain:"固定格式是“（不）把……放在眼里”，否定词放在“放在眼里”前面，语序不能改变。",explainEn:"The fixed form is 不（把…）放在眼里; the negative goes before 放在眼里 and the order cannot change."},{kind:"choice",q:"他从不把对手放在眼里，___。",instr:"完成",instrEn:"Complete the sentence",body:"他从不把对手放在眼里，___。",options:["结果在决赛中输得很惨","所以每场比赛都认真研究对方","赛前总是仔细分析对手的录像","对每个对手都非常尊重"],answer:0,explain:"“不把……放在眼里”表示轻视、看不起，后面常接因此吃亏的结果；认真研究、仔细分析、非常尊重都与轻视相反。",explainEn:"不把…放在眼里 means looking down on someone, so a costly result follows; studying or respecting rivals is the opposite."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他从来不放在眼里别人。","他太骄傲了，连老师都不放在眼里。","这点困难，我们根本没放在眼里。","这家公司不把顾客的投诉放在眼里，终于吃了大亏。"],answer:0,explain:"对象要用“把”提到“放在眼里”前面，不能放在后面，应改为“他从来不把别人放在眼里”。",explainEn:"The object must come before 放在眼里 with 把; say 他从来不把别人放在眼里."},{q:"翻译：He looks down on everyone.",a:"他谁都不放在眼里。",instr:"翻译",instrEn:"Translate",body:"He looks down on everyone."}],note:"否定形式很常见，可表示“不重视”或“看不起某人”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bǎ + person/thing + fàng zài yǎn li; bù bǎ … fàng zài yǎn li = take … seriously; look down on …",noteEn:'The negative form is very common: "not take seriously" or "look down on someone".',typeEn:"Fixed pattern"},{id:"HSK6.40.2",name:"“不无”表示并非没有",pinyin:"bùwú",type:"动词/书面否定",explainEn:"Use 不无 to mean “not without / there is some…”. It is formal.",structure:"不无 + 道理/遗憾/可能/影响",examples:[{zh:"他的说法不无道理。",en:"What he said is not without reason.",py:"Tā de shuōfǎ bùwú dàoli."},{zh:"这次失败不无遗憾。",en:"This failure is not without regret.",py:"Zhè cì shībài bùwú yíhàn."},{zh:"这种变化不无可能。",en:"This change is not impossible.",py:"Zhè zhǒng biànhuà bùwú kěnéng."}],exercises:[{kind:"choice",q:"他的建议___道理，值得我们认真考虑。",instr:"辨析",instrEn:"Pick the right one",body:"他的建议___道理，值得我们认真考虑。",options:["毫无","不无","并无","绝无"],answer:1,explain:"“不无道理”是双重否定，意思是“有一定道理”，和“值得考虑”一致；“毫无、并无、绝无”都表示没有，与后半句矛盾。",explainEn:'不无道理 means "not without reason", matching "worth considering"; 毫无, 并无 and 绝无 all mean "none".'},{kind:"choice",q:"这次比赛我们只差一分就能夺冠，大家心里不无___。",instr:"完成",instrEn:"Complete the sentence",body:"这次比赛我们只差一分就能夺冠，大家心里不无___。",options:["得意","满足","轻松","遗憾"],answer:3,explain:"“不无”委婉地表示“有一些”，常接“遗憾、道理、可能”等；只差一分没夺冠，心里有的是遗憾。",explainEn:'不无 gently means "some" and often takes 遗憾; missing the title by one point leaves regret, not pride or ease.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个方案不无任何问题。","她的批评虽然尖锐，却不无道理。","专家认为，这两件事之间不无关系。","对于这个结果，大家不无遗憾。"],answer:0,explain:"“不无”意思是“有一些”，不能和表示全部否定的“任何”连用，应改为“这个方案毫无问题”。",explainEn:'不无 means "some" and cannot go with 任何; say 这个方案毫无问题.'},{q:"翻译：Her decision is not without risk.",a:"她的决定不无风险。",instr:"翻译",instrEn:"Translate",body:"Her decision is not without risk."}],note:"双重否定式书面表达，语气通常比直接说“有”更委婉。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùwú + dàoli/yíhàn/kěnéng/yǐngxiǎng = not without (some) reason/regret/possibility/effect",noteEn:"A formal double negative; usually more tactful than simply saying 有.",typeEn:"Verb / Formal negation"}]}],i={series:e,unit:6,lessons:n};export{i as default,n as lessons,e as series,t as unit};
